INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e3640a-e058-4a5d-8352-50f283397d79', '芳樹', '芳樹', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["何地早芳菲，宛在長門殿。","夭桃色若綬，穠李光如練。","啼鳥弄花疎，遊蜂飲香遍。","歎息春風起，飄零君不見。"]', '["何地早芳菲，宛在长门殿。","夭桃色若綬，穠李光如練。","啼鸟弄花疎，游蜂饮香遍。","歎息春风起，飄零君不见。"]', '诗', 'shi', '', NULL, '芳樹 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3ef808-a4d4-4857-8842-a476aaaca79d', '長安道', '长安道', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["秦地平如掌，層城入雲漢。","樓閣九衢春，車馬千門旦。","綠槐開復合，紅塵聚還散。","日晚鬬雞還，經過狹斜看。"]', '["秦地平如掌，層城入云漢。","楼閣九衢春，车马千门旦。","綠槐开复合，紅塵聚還散。","日晚鬬雞還，經過狹斜看。"]', '诗', 'shi', '', NULL, '長安道 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a65dc6-9d8b-4775-adec-d4fcfbd7799d', '有所思', '有所思', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["君子事行役，再空芳歲期。","美人曠延佇，萬里浮雲思。","園槿綻紅豔，郊桑柔綠滋。","坐看長夏晚，秋月照羅幃。"]', '["君子事行役，再空芳歲期。","美人曠延佇，万里浮云思。","园槿綻紅豔，郊桑柔綠滋。","坐看长夏晚，秋月照羅幃。"]', '诗', 'shi', '', NULL, '有所思 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('381f86a7-ba22-4df3-92ae-f9ffb71fb927', '臨高臺', '臨高台', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["高臺臨廣陌，車馬紛相續。","回首思舊鄉，雲山亂心曲。","遠望河流緩，周看原野綠。","向夕林鳥還，憂來飛景促。"]', '["高台臨廣陌，车马紛相續。","回首思旧乡，云山亂心曲。","远望河流緩，周看原野綠。","向夕林鸟還，憂来飞景促。"]', '诗', 'shi', '', NULL, '臨高臺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ea924b-7908-46e4-bdfb-7a80c53bce22', '鳳笙曲', '鳳笙曲', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["憶昔王子晉，鳳笙遊雲空。","揮手弄白日，安能戀青宮。","豈無嬋娟子，結念羅幃中。","憐壽不貴色，身世兩無窮。"]', '["憶昔王子晉，鳳笙游云空。","揮手弄白日，安能戀青宮。","豈無嬋娟子，結念羅幃中。","怜壽不貴色，身世兩無窮。"]', '诗', 'shi', '', NULL, '鳳笙曲 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d469f6eb-475a-4e5a-b1ac-014052ed4c61', '擬古別離', '擬古別離', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["白水東悠悠，中有西行舟。","舟行有返櫂，水去無還流。","奈何生別者，戚戚懷遠遊。","遠遊誰當惜，所悲會難收。","自君闃芳躧，青陽四五遒。","皓月掩蘭室，光風虛蕙樓。","相思無明晦，長歎累冬秋。","離居久遲暮，高駕何淹留。"]', '["白水东悠悠，中有西行舟。","舟行有返櫂，水去無還流。","奈何生別者，戚戚懷远游。","远游誰當惜，所悲會难收。","自君闃芳躧，青陽四五遒。","皓月掩蘭室，光风虛蕙楼。","相思無明晦，长歎累冬秋。","離居久遲暮，高駕何淹留。"]', '诗', 'shi', '', NULL, '擬古別離 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf24b17-cb47-47c8-b196-ce479aec9cf5', '辛丑歲十月上幸長安時扈從出西嶽作', '辛丑歲十月上幸长安时扈從出西嶽作', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["西鎮何穹崇，壯哉信靈造。","諸嶺皆峻秀，中峯特美好。","傍見巨掌存，勢如石東倒。","頗聞首陽去，開坼此河道。","磅礴壓洪源，巍峨壯清昊。","雲泉紛亂瀑，天磴屹橫抱。","子先呼其巔，宮女世不老。","下有府君廟，歷載傳灑掃。","皇明應天游，十月戒豐鎬。","微未忝閑從，兼得事蘋藻。","宿心愛茲山，意欲拾靈草。","陰壑已永閟，雲竇絕探討。","芳月期來過，迴策思方浩。"]', '["西鎮何穹崇，壯哉信靈造。","諸嶺皆峻秀，中峯特美好。","傍见巨掌存，勢如石东倒。","頗闻首陽去，开坼此河道。","磅礴壓洪源，巍峨壯清昊。","云泉紛亂瀑，天磴屹橫抱。","子先呼其巔，宮女世不老。","下有府君廟，歷載傳灑掃。","皇明應天游，十月戒豐鎬。","微未忝闲從，兼得事蘋藻。","宿心愛茲山，意欲拾靈草。","陰壑已永閟，云竇絕探討。","芳月期来過，迴策思方浩。"]', '诗', 'shi', '', NULL, '辛丑歲十月上幸長安時扈從出西嶽作 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da142b5b-c436-4971-a3cb-04ded1b99ab4', '和杜麟臺元志春情', '和杜麟台元志春情', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["嘉樹滿中園，氛氳羅秀色。","不見仙山雲，倚琴空太息。","沈思若在夢，緘怨似無憶。","青春坐南移，白日忽西匿。","蛾眉返清鏡，閨中不相識。"]', '["嘉樹满中园，氛氳羅秀色。","不见仙山云，倚琴空太息。","沈思若在梦，緘怨似無憶。","青春坐南移，白日忽西匿。","蛾眉返清镜，閨中不相識。"]', '诗', 'shi', '', NULL, '和杜麟臺元志春情 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56d6a45a-5af7-4be8-93e7-0c0bc3cbf45d', '別侍御嚴凝', '別侍御嚴凝', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["七澤雲夢林，三湘洞庭水。","自古傳剽俗，有時逋惡子。","令君出使車，行邁方靡靡。","靜言芟枳棘，慎勿傷蘭芷。"]', '["七澤云梦林，三湘洞庭水。","自古傳剽俗，有时逋惡子。","令君出使车，行邁方靡靡。","静言芟枳棘，慎勿傷蘭芷。"]', '诗', 'shi', '', NULL, '別侍御嚴凝 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a737f68-49fd-467f-94f4-9fd5361dae18', '送喬隨州侃', '送喬隨州侃', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["結交三十載，同遊一萬里。","情爲契闊生，心由別離死。","拜恩前後人，從宦差池起。","今爾歸漢東，明珠報知己。"]', '["結交三十載，同游一万里。","情爲契闊生，心由別離死。","拜恩前後人，從宦差池起。","今爾归漢东，明珠報知己。"]', '诗', 'shi', '', NULL, '送喬隨州侃 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0742ebdb-3596-49bb-ac05-b19d047e0d44', '送友人任括州', '送友人任括州', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["青春浩無際，白日乃遲遲。","胡爲賞心客，歎邁此芳時。","甌粵迫茲守，京闕從此辭。","茫茫理雲帆，草草念行期。","紛吾結遠佩，帳餞出河湄。","太息東流水，盈觴難再持。"]', '["青春浩無際，白日乃遲遲。","胡爲賞心客，歎邁此芳时。","甌粵迫茲守，京闕從此辞。","茫茫理云帆，草草念行期。","紛吾結远佩，帳餞出河湄。","太息东流水，盈觴难再持。"]', '诗', 'shi', '', NULL, '送友人任括州 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d245ffa8-eb68-49ee-b6e1-f6608fdc13f3', '餞遠', '餞远', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["任子徇遐祿，結友開舊襟。","撰酌輟行歎，指途勤遠心。","秋皛澄回壑，霽色肅明林。","曖然青軒暮，浩思非所任。"]', '["任子徇遐祿，結友开旧襟。","撰酌輟行歎，指途勤远心。","秋皛澄回壑，霽色肅明林。","曖然青軒暮，浩思非所任。"]', '诗', 'shi', '', NULL, '餞遠 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b024c8a6-7721-4908-81f1-29afb3163ae5', '同工部李侍郎適訪司馬子微', '同工部李侍郎適訪司马子微', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["紫微降天仙，丹地投雲藻。","上言華頂事，中問長生道。","華頂居最高，大壑朝陽早。","長生術何妙，童顏後天老。","清晨朝鳳京，靜夜思鴻寶。","憑崖飲蕙氣，過澗摘靈草。","人非冢已荒，海變田應燥。","昔嘗遊此郡，三霜弄溟島。","緒言霞上開，機事塵外掃。","頃來迫世務，清曠未云保。","崎嶇待漏恩，怵惕司言造。","軒皇重齋拜，漢武愛祈禱。","順風懷崆峒，承露在豐鎬。","泠然魏輕馭，復得散幽抱。","柱下留伯陽，儲闈登四皓。"]', '["紫微降天仙，丹地投云藻。","上言华頂事，中问长生道。","华頂居最高，大壑朝陽早。","长生術何妙，童顏後天老。","清晨朝鳳京，静夜思鴻寶。","憑崖饮蕙氣，過澗摘靈草。","人非冢已荒，海变田應燥。","昔嘗游此郡，三霜弄溟島。","緒言霞上开，機事塵外掃。","頃来迫世務，清曠未云保。","崎嶇待漏恩，怵惕司言造。","軒皇重斋拜，漢武愛祈禱。","順风懷崆峒，承露在豐鎬。","泠然魏轻馭，复得散幽抱。","柱下留伯陽，儲闈登四皓。"]', '诗', 'shi', '', NULL, '同工部李侍郎適訪司馬子微 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099c950a-b58f-48dd-ab8d-22c228b092ee', '自昌樂郡泝流至白石嶺下行入郴州', '自昌乐郡泝流至白石嶺下行入郴州', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["茲山界夷夏，天險橫寥廓。","太史漏登探，文命限開鑿。","北流自南瀉，羣峰回衆壑。","馳波如電騰，激石似雷落。","崖留盤古樹，澗蓄神農藥。","乳竇何淋漓，苔蘚更彩錯。","娟娟潭裏虹，渺渺灘邊鶴。","歲杪應流火，天高雲物薄。","金風吹綠梢，玉露洗紅籜。","泝舟始興廨，登踐桂陽郭。","匍匐緣修坂，穹窿曳長䋏。","礙林阻往來，遇堰每前却。","救艱不遑飯，畢昏無暇泊。","濯溪寧足懼，磴道誰云惡。","我行山水間，湍險皆不若。","安能獨見聞，書此貽京洛。"]', '["茲山界夷夏，天險橫寥廓。","太史漏登探，文命限开鑿。","北流自南瀉，羣峰回衆壑。","驰波如電腾，激石似雷落。","崖留盤古樹，澗蓄神農藥。","乳竇何淋漓，苔蘚更彩錯。","娟娟潭裏虹，渺渺灘邊鹤。","歲杪應流火，天高云物薄。","金风吹綠梢，玉露洗紅籜。","泝舟始兴廨，登踐桂陽郭。","匍匐緣修坂，穹窿曳长䋏。","礙林阻往来，遇堰每前却。","救艱不遑飯，畢昏無暇泊。","濯溪寧足懼，磴道誰云惡。","我行山水间，湍險皆不若。","安能独见闻，书此貽京洛。"]', '诗', 'shi', '', NULL, '自昌樂郡泝流至白石嶺下行入郴州 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb80e9ef-e078-4ae2-8502-7f344d5fc05d', '過蜀龍門', '過蜀龙门', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["龍門非禹鑿，詭怪乃天功。","西南出巴峽，不與衆山同。","長竇亙五里，宛轉復嵌空。","伏湍喣潛石，瀑水生輪風。","流水無晝夜，噴薄龍門中。","潭河勢不測，藻葩垂彩虹。","我行當季月，煙景共舂融。","江關勤亦甚，巘崿意難窮。","勢將息機事，煉藥此山東。"]', '["龙门非禹鑿，詭怪乃天功。","西南出巴峽，不與衆山同。","长竇亙五里，宛轉复嵌空。","伏湍喣潛石，瀑水生輪风。","流水無晝夜，噴薄龙门中。","潭河勢不測，藻葩垂彩虹。","我行當季月，煙景共舂融。","江关勤亦甚，巘崿意难窮。","勢將息機事，煉藥此山东。"]', '诗', 'shi', '', NULL, '過蜀龍門 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31eab78-1b8f-478b-871c-a88b09e0df70', '入衞作', '入衞作', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["淇上風日好，紛紛沿岸多。","綠芳幸未歇，泛濫此明波。","采蘩憶幽吹，理棹想荆歌。","鬱然懷君子，浩曠將如何。"]', '["淇上风日好，紛紛沿岸多。","綠芳幸未歇，泛濫此明波。","采蘩憶幽吹，理棹想荆歌。","鬱然懷君子，浩曠將如何。"]', '诗', 'shi', '', NULL, '入衞作 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('947651ac-32b6-4430-9031-039709b86c2d', '蝴蝶二首 一', '蝴蝶二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["縹緲青蟲脫殼微，不堪煙重雨霏霏。","一枝穠豔留教住，幾處春風借與飛。","防患每憂雞雀口，憐香偏遶綺羅衣。","無情豈解關魂夢，莫信莊周說是非。"]', '["縹緲青蟲脫殼微，不堪煙重雨霏霏。","一枝穠豔留教住，幾处春风借與飞。","防患每憂雞雀口，怜香偏遶綺羅衣。","無情豈解关魂梦，莫信莊周说是非。"]', '诗', 'shi', '', NULL, '蝴蝶二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c29180-d7e6-444c-95db-44d2d203a830', '蝴蝶二首 二', '蝴蝶二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["拂綠穿紅麗日長，一生心事住春光。","最嫌神女來行雨，愛伴西施去採香。","風定只應攢蘂粉，夜寒長是宿花房。","鳴蟬性分殊迂闊，空解三秋噪夕陽。"]', '["拂綠穿紅丽日长，一生心事住春光。","最嫌神女来行雨，愛伴西施去採香。","风定只應攢蘂粉，夜寒长是宿花房。","鳴蟬性分殊迂闊，空解三秋噪夕陽。"]', '诗', 'shi', '', NULL, '蝴蝶二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a83e700-8951-469d-ba56-5be416c33d45', '郡侯坐上觀琉璃瓶中遊魚', '郡侯坐上观琉璃瓶中游鱼', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["寶器一泓銀漢水，錦鱗纔動即先知。","似涵明月波寧隔，欲上輕冰律未移。","薄霧罩來分咫尺，碧綃籠處較毫釐。","文翁未得沈香餌，擬置金盤召左慈。"]', '["寶器一泓銀漢水，錦鱗纔动即先知。","似涵明月波寧隔，欲上轻冰律未移。","薄霧罩来分咫尺，碧綃籠处較毫釐。","文翁未得沈香餌，擬置金盤召左慈。"]', '诗', 'shi', '', NULL, '郡侯坐上觀琉璃瓶中遊魚 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94d01774-e25a-4321-9fb0-a91a15cd1e39', '翦刀', '翦刀', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["寶持多用繡爲囊，雙日交加兩鬢霜。","金匣掠平花翡翠，綠窗裁破錦鴛鴦。","初栽連理枝猶短，誤綰同心帶不長。","欲製緼袍先把看，質非紈綺愧銛鋩。"]', '["寶持多用繡爲囊，雙日交加兩鬢霜。","金匣掠平花翡翠，綠窗裁破錦鴛鴦。","初栽連理枝猶短，誤綰同心带不长。","欲製緼袍先把看，質非紈綺愧銛鋩。"]', '诗', 'shi', '', NULL, '翦刀 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('341affc4-7db1-4ec9-ac5f-06aceca64739', '紙被', '紙被', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["文采鴛鴦罷合歡，細柔輕綴好魚牋。","一牀明月蓋歸夢，數尺白雲籠冷眠。","披對勁風溫勝酒，擁聽寒風暖于綿。","赤眉豪客見皆笑，却問儒生直幾錢。"]', '["文采鴛鴦罷合歡，細柔轻綴好鱼牋。","一牀明月蓋归梦，數尺白云籠冷眠。","披对勁风溫勝酒，擁听寒风暖于綿。","赤眉豪客见皆笑，却问儒生直幾錢。"]', '诗', 'shi', '', NULL, '紙被 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a007ca-cb53-423d-b6c7-0e0c9db4b660', '紙帳', '紙帳', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["幾笑文園四壁空，避寒深入剡藤中。","誤懸謝守澄江練，自宿嫦娥白兔宮。","幾疊玉山開洞壑，半巖春霧結房櫳。","針羅截錦饒君侈，爭及蒙茸煖避風。"]', '["幾笑文园四壁空，避寒深入剡藤中。","誤懸謝守澄江練，自宿嫦娥白兔宮。","幾叠玉山开洞壑，半巖春霧結房櫳。","針羅截錦饒君侈，爭及蒙茸煖避风。"]', '诗', 'shi', '', NULL, '紙帳 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a5306f-e35c-4713-9ad4-c7e0a9fa62e6', '貢餘秘色茶盞', '貢餘秘色茶盞', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["捩翠融青瑞色新，陶成先得貢吾君。","功剜明月染春水，輕旋薄冰盛綠雲。","古鏡破苔當席上，嫩荷涵露別江濆。","中山竹葉醅初發，多病那堪中十分。"]', '["捩翠融青瑞色新，陶成先得貢吾君。","功剜明月染春水，轻旋薄冰盛綠云。","古镜破苔當席上，嫩荷涵露別江濆。","中山竹葉醅初發，多病那堪中十分。"]', '诗', 'shi', '', NULL, '貢餘秘色茶盞 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db00e55-df80-46b6-82ef-9290e4db7084', '筍鞭', '筍鞭', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["筇竹岩邊剔翠苔，錦江波冷洗瓊瑰。","纍纍節轉蒼龍骨，寸寸珠聯巨蚌胎。","須向廣場驅駔駿，莫從閑處撻駑駘。","寧同晉帝環營日，拋賺中途後騎來。"]', '["筇竹岩邊剔翠苔，錦江波冷洗瓊瑰。","纍纍節轉蒼龙骨，寸寸珠聯巨蚌胎。","須向廣場驱駔駿，莫從闲处撻駑駘。","寧同晉帝环營日，拋賺中途後騎来。"]', '诗', 'shi', '', NULL, '筍鞭 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cef1f4e-af27-46dc-bd13-474b521212a1', '詠簾', '詠簾', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["素節輕盈珠影勻，何人巧思間成文。","閑垂別殿風應度，半掩行宮麝欲薰。","繡戶遠籠寒焰重，玉樓高挂曙光分。","無情幾恨黃昏月，纔到如鉤便墮雲。"]', '["素節轻盈珠影勻，何人巧思间成文。","闲垂別殿风應度，半掩行宮麝欲薰。","繡戶远籠寒焰重，玉楼高挂曙光分。","無情幾恨黄昏月，纔到如鉤便墮云。"]', '诗', 'shi', '', NULL, '詠簾 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbbcc453-1e0b-4a6b-acf2-8effd16dab6c', '詠燈', '詠灯', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["分影由來恨不同，綠窗孤館兩何窮。","熒煌短焰長疑暗，零落殘花旋委空。","幾處隔簾愁夜雨，誰家當戶怯秋風。","莫言明滅無多事，曾比人生一世中。"]', '["分影由来恨不同，綠窗孤館兩何窮。","熒煌短焰长疑暗，零落殘花旋委空。","幾处隔簾愁夜雨，誰家當戶怯秋风。","莫言明滅無多事，曾比人生一世中。"]', '诗', 'shi', '', NULL, '詠燈 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('742f5e6f-b1eb-46d0-b3c7-e530d3aac46d', '詠扇', '詠扇', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["爲發涼飆滿玉堂，每親襟袖便難忘。","霜濃雪暗知何在，道契時來忽自揚。","曾伴一樽臨小檻，幾遮殘日過回廊。","漢宮如有秋風起，誰信班姬淚數行。"]', '["爲發涼飆满玉堂，每親襟袖便难忘。","霜濃雪暗知何在，道契时来忽自揚。","曾伴一樽臨小檻，幾遮殘日過回廊。","漢宮如有秋风起，誰信班姬泪數行。"]', '诗', 'shi', '', NULL, '詠扇 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9324b0c-06db-4ba1-bb4e-3471eeab042e', '詠筆二首 一', '詠笔二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["秦代將軍欲建功，截龍搜兔助英雄。","用多誰念毛皆拔，拋却更嫌心不中。","史氏只應歸道直，江淹何獨偶靈通。","班超握管不成事，投擲翻從萬里戎。"]', '["秦代將軍欲建功，截龙搜兔助英雄。","用多誰念毛皆拔，拋却更嫌心不中。","史氏只應归道直，江淹何独偶靈通。","班超握管不成事，投擲翻從万里戎。"]', '诗', 'shi', '', NULL, '詠筆二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e9b92f4-22f9-478e-9ba1-494daf6d9a85', '詠筆二首 二', '詠笔二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["君子三歸擅一名，秋毫雖細握非輕。","軍書羽檄教誰錄，帝命王言待我成。","勢健豈饒淝水陣，鋒銛還學歷山耕。","毛乾時有何人潤，盡把燒焚恨始平。"]', '["君子三归擅一名，秋毫雖細握非轻。","軍书羽檄教誰錄，帝命王言待我成。","勢健豈饒淝水陣，鋒銛還学歷山耕。","毛乾时有何人潤，尽把燒焚恨始平。"]', '诗', 'shi', '', NULL, '詠筆二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433d77c8-3db1-4309-af05-017cc063c435', '詠錢', '詠錢', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["多蓄多藏豈足論，有誰還議濟王孫。","能於禍處翻爲福，解向讐家買得恩。","幾怪鄧通難免餓，須知夷甫不曾言。","朝爭暮競歸何處，盡入權門與倖門。"]', '["多蓄多藏豈足論，有誰還議濟王孫。","能於禍处翻爲福，解向讐家買得恩。","幾怪鄧通难免餓，須知夷甫不曾言。","朝爭暮競归何处，尽入權门與倖门。"]', '诗', 'shi', '', NULL, '詠錢 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ba811e7-90f4-4d72-9ac1-e9d94d246ffd', '尚書筵中詠紅手帕', '尚书筵中詠紅手帕', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["鶴綾三尺曉霞濃，送與東家二八容。","羅帶繡裙輕好繫，藕絲紅縷細初縫。","別來拭淚遮桃臉，行去包香墜粉胸。","無事把將纏皓腕，爲君池上折芙蓉。"]', '["鹤綾三尺晓霞濃，送與东家二八容。","羅带繡裙轻好繫，藕絲紅縷細初縫。","別来拭泪遮桃臉，行去包香墜粉胸。","無事把將纏皓腕，爲君池上折芙蓉。"]', '诗', 'shi', '', NULL, '尚書筵中詠紅手帕 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba028a2f-decc-4bfb-abe3-15ab300eb410', '尚書新造花箋', '尚书新造花箋', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["濃染紅桃二月花，只宜神筆縱龍蛇。","淺澄秋水看雲母，碎擘輕苔間粉霞。","寫賦好追陳后寵，題詩堪送竇滔家。","使君即入金鑾殿，夜直無非草白麻。"]', '["濃染紅桃二月花，只宜神笔縱龙蛇。","淺澄秋水看云母，碎擘轻苔间粉霞。","寫賦好追陳后寵，題诗堪送竇滔家。","使君即入金鑾殿，夜直無非草白麻。"]', '诗', 'shi', '', NULL, '尚書新造花箋 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('558d3007-ac7a-4a3b-9382-2a8cdec48c7e', '釣車', '釣车', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["荻灣漁客巧妝成，硾鑄銀星一點輕。","拋過碧江鸂[鶒]岸，軋殘金井轆轤聲。","軸磨騂角冰光滑，輪卷春絲水面平。","把向嚴灘尋轍迹，漁臺基在輾難傾。"]', '["荻灣漁客巧妝成，硾鑄銀星一点轻。","拋過碧江鸂[鶒]岸，軋殘金井轆轤声。","軸磨騂角冰光滑，輪卷春絲水面平。","把向嚴灘尋轍迹，漁台基在輾难傾。"]', '诗', 'shi', '', NULL, '釣車 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7569631f-f6d7-44a3-afc1-1232f89d2347', '柳', '柳', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["漠漠金條引線微，年年先翠報春歸。","解籠飛靄延芳景，不逐亂花飄夕暉。","啼鳥噪蟬堪悵望，舞煙搖水自因依。","五株名顯陶家後，見說辭榮種者稀。"]', '["漠漠金條引線微，年年先翠報春归。","解籠飞靄延芳景，不逐亂花飄夕暉。","啼鸟噪蟬堪悵望，舞煙搖水自因依。","五株名显陶家後，见说辞榮種者稀。"]', '诗', 'shi', '', NULL, '柳 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59429c9-5135-438d-ba1b-6463f8f1fc50', '愁', '愁', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["夜長偏覺漏聲遲，往往隨歌慘翠眉。","黃葉落催砧杵日，子規啼破夢魂時。","明妃去泣千行淚，蔡琰歸梳兩鬢絲。","四皓入山招不得，無家歸客最堪欺。"]', '["夜长偏覺漏声遲，往往隨歌慘翠眉。","黄葉落催砧杵日，子規啼破梦魂时。","明妃去泣千行泪，蔡琰归梳兩鬢絲。","四皓入山招不得，無家归客最堪欺。"]', '诗', 'shi', '', NULL, '愁 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e92f082-c8a6-4012-9ef8-b9d1f738d50c', '草', '草', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["廢苑荒堦伴綠苔，恩疎長信恨難開。","姑蘇麋鹿食思食，楚澤王孫來不來。","色嫩似將藍汁染，葉齊如把翦刀裁。","燕昭沒後多卿士，千載流芳郭隗臺。"]', '["廢苑荒堦伴綠苔，恩疎长信恨难开。","姑蘇麋鹿食思食，楚澤王孫来不来。","色嫩似將藍汁染，葉齊如把翦刀裁。","燕昭沒後多卿士，千載流芳郭隗台。"]', '诗', 'shi', '', NULL, '草 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1b61cb-3102-490f-babe-eca519dd4aed', '螢', '螢', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["月墜西樓夜影空，透簾穿幕達房櫳。","流光堪在珠璣列，爲火不生榆柳中。","一一照通黃卷字，輕輕化出綠蕪叢。","欲知應候何時節，六月初迎大暑風。"]', '["月墜西楼夜影空，透簾穿幕達房櫳。","流光堪在珠璣列，爲火不生榆柳中。","一一照通黄卷字，轻轻化出綠蕪叢。","欲知應候何时節，六月初迎大暑风。"]', '诗', 'shi', '', NULL, '螢 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df790bb-c6f4-41f1-9215-3c3b08fe9702', '水', '水', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["火性何如水性柔，西來東出幾時休。","莫言通海能通漢，雖解浮舟也覆舟。","湘浦暮沈堯女怨，汾河秋泛漢皇愁。","洪波激湍歸何處，二月桃花滿眼流。"]', '["火性何如水性柔，西来东出幾时休。","莫言通海能通漢，雖解浮舟也覆舟。","湘浦暮沈堯女怨，汾河秋泛漢皇愁。","洪波激湍归何处，二月桃花满眼流。"]', '诗', 'shi', '', NULL, '水 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b75ba23-d671-4e34-a122-d418f6196cea', '苔', '苔', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["印留麋鹿野禽蹤，岩壁漁磯幾處逢。","金谷曉凝花影重，章華春映柳陰濃。","石橋羽客遺前迹，陳閣才人沒舊容。","歸去掃除階砌下，蘚痕殘綠一重重。"]', '["印留麋鹿野禽蹤，岩壁漁磯幾处逢。","金谷晓凝花影重，章华春映柳陰濃。","石橋羽客遺前迹，陳閣才人沒旧容。","归去掃除階砌下，蘚痕殘綠一重重。"]', '诗', 'shi', '', NULL, '苔 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe7f7a5-d731-4c61-a355-d372e2503401', '曉', '晓', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["水盡銅龍滴漸微，景陽鍾動夢魂飛。","潼關雞唱促歸騎，金殿燭殘求御衣。","窗下寒機猶自織，梁間棲燕欲雙飛。","羲和晴聳扶桑轡，借與寰瀛看早暉。"]', '["水尽銅龙滴漸微，景陽鍾动梦魂飞。","潼关雞唱促归騎，金殿燭殘求御衣。","窗下寒機猶自织，梁间棲燕欲雙飞。","羲和晴聳扶桑轡，借與寰瀛看早暉。"]', '诗', 'shi', '', NULL, '曉 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('059c7799-21ec-43fc-b21f-96d763b83f58', '別', '別', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["酒盡歌終問後期，泛萍浮梗不勝悲。","東門匹馬夜歸處，南浦片帆飛去時。","賦罷江淹吟更苦，詩成蘇武思何遲。","可憐范陸分襟後，空折梅花寄所思。"]', '["酒尽歌終问後期，泛萍浮梗不勝悲。","东门匹马夜归处，南浦片帆飞去时。","賦罷江淹吟更苦，诗成蘇武思何遲。","可怜范陸分襟後，空折梅花寄所思。"]', '诗', 'shi', '', NULL, '別 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1309b952-d792-4b93-805e-6808995b66cb', '夜', '夜', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["日墜虞淵燭影開，沈沈煙霧壓浮埃。","剡川雪滿子猷去，漢殿月生王母來。","簷挂蛛絲應漸織，風吹螢火不成灰。","愁人莫道何時旦，自有鐘鳴漏滴催。"]', '["日墜虞淵燭影开，沈沈煙霧壓浮埃。","剡川雪满子猷去，漢殿月生王母来。","簷挂蛛絲應漸织，风吹螢火不成灰。","愁人莫道何时旦，自有鐘鳴漏滴催。"]', '诗', 'shi', '', NULL, '夜 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a638f6e8-ba9f-48fa-ba33-e23c8e4d71b2', '雨', '雨', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["引電隨龍密又輕，酒桮閑噀得嘉名。","千山草木如雲暗，陸地波瀾接海平。","灑竹幾添春睡重，滴簷偏遣夜愁生。","陰妖冷孽成何怪，敢蔽高天日月明。"]', '["引電隨龙密又轻，酒桮闲噀得嘉名。","千山草木如云暗，陸地波瀾接海平。","灑竹幾添春睡重，滴簷偏遣夜愁生。","陰妖冷孽成何怪，敢蔽高天日月明。"]', '诗', 'shi', '', NULL, '雨 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8964b7f8-ac21-4c55-96db-49c87448374c', '萍', '萍', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["爲實隨流瑞色新，泛風縈草護遊鱗。","密行碧水澄涵月，澁滯輕橈去採蘋。","比物何名腰下劍，無根堪並鏡中身。","平湖春渚知何限，撥破閑投獨繭綸。"]', '["爲實隨流瑞色新，泛风縈草護游鱗。","密行碧水澄涵月，澁滯轻橈去採蘋。","比物何名腰下劍，無根堪並镜中身。","平湖春渚知何限，撥破闲投独繭綸。"]', '诗', 'shi', '', NULL, '萍 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250b1806-8ee3-450e-8c86-906e9ef8dce9', '恨', '恨', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["事與時違不自由，如燒如刺寸心頭。","烏江項籍忍歸去，雁塞李陵長繫留。","燕國飛霜將破夏，漢宮紈扇豈禁秋。","須知入骨難銷處，莫比人間取次愁。"]', '["事與时違不自由，如燒如刺寸心头。","烏江項籍忍归去，雁塞李陵长繫留。","燕国飞霜將破夏，漢宮紈扇豈禁秋。","須知入骨难銷处，莫比人间取次愁。"]', '诗', 'shi', '', NULL, '恨 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a59df1c-4d29-4b51-9735-18f6d19735f5', '鴻', '鴻', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["行如兄弟影連空，春去秋來燕不同。","紫塞別當秋露白，碧山飛入暮霞紅。","宣王德美周詩內，蘇武書傳漢苑中。","況解銜蘆避弓箭，一聲歸唳楚天風。"]', '["行如兄弟影連空，春去秋来燕不同。","紫塞別當秋露白，碧山飞入暮霞紅。","宣王德美周诗內，蘇武书傳漢苑中。","況解銜蘆避弓箭，一声归唳楚天风。"]', '诗', 'shi', '', NULL, '鴻 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff41a7a-2867-45c7-9729-269a5ecce6c1', '鶴', '鹤', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["閬苑瑤臺歲月長，一歸華表好增傷。","新聲乍警初零露，折羽閑飛幾片霜。","要伴神仙歸碧落，豈隨龜雁住方塘。","三山頂上無人處，瓊樹堪巢不死鄉。"]', '["閬苑瑤台歲月长，一归华表好增傷。","新声乍警初零露，折羽闲飞幾片霜。","要伴神仙归碧落，豈隨龟雁住方塘。","三山頂上無人处，瓊樹堪巢不死乡。"]', '诗', 'shi', '', NULL, '鶴 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5afcb7b-0593-44de-a08c-a9269a51c1c5', '鵲', '鵲', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["神化難源瑞即開，雕陵毛羽出塵埃。","香閨報喜行人至，碧漢填河織女回。","明月解隨烏繞樹，青銅寧愧雀爲臺。","瓊枝翠葉庭前植，從待翩翩去又來。"]', '["神化难源瑞即开，雕陵毛羽出塵埃。","香閨報喜行人至，碧漢填河织女回。","明月解隨烏繞樹，青銅寧愧雀爲台。","瓊枝翠葉庭前植，從待翩翩去又来。"]', '诗', 'shi', '', NULL, '鵲 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a540fd-84b5-4666-885b-2620ec8c33ac', '霜', '霜', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["應節誰窮造化端，菊黃豺祭問應難。","紅窗透出鴛衾冷，白草飛時雁塞寒。","露結芝蘭瓊屑厚，日乾葵藿粉痕殘。","世間無比催搖落，松竹何人肯更看。"]', '["應節誰窮造化端，菊黄豺祭问應难。","紅窗透出鴛衾冷，白草飞时雁塞寒。","露結芝蘭瓊屑厚，日乾葵藿粉痕殘。","世间無比催搖落，松竹何人肯更看。"]', '诗', 'shi', '', NULL, '霜 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36db4d01-5eb0-4d46-b986-723c3bb36ab8', '風', '风', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["城上寒來思莫窮，土囊萍末兩難同。","飄成遠浪江湖際，吹起暮塵京洛中。","飛雪蕭條殘臘節，落花狼藉古行宮。","春能和煦秋搖落，生殺還同造化功。"]', '["城上寒来思莫窮，土囊萍末兩难同。","飄成远浪江湖際，吹起暮塵京洛中。","飞雪蕭條殘臘節，落花狼藉古行宮。","春能和煦秋搖落，生殺還同造化功。"]', '诗', 'shi', '', NULL, '風 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3da03a3-79d5-4ec4-a2ea-6b8586c323be', '帆', '帆', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["豈勞孤棹送行舟，輕過天涯勢未休。","斷岸曉看殘月挂，遠灣寒背夕陽收。","川平直可追飛箭，風健還能泝急流。","幸遇濟川恩不淺，北溟東海更何愁。"]', '["豈勞孤棹送行舟，轻過天涯勢未休。","斷岸晓看殘月挂，远灣寒背夕陽收。","川平直可追飞箭，风健還能泝急流。","幸遇濟川恩不淺，北溟东海更何愁。"]', '诗', 'shi', '', NULL, '帆 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fff6bc0-28cd-4ade-b329-aef5f1fb8f91', '夢', '梦', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["月落燈前閉北堂，神魂交入杳冥鄉。","文通毫管醒來異，武帝蘅蕪覺後香。","傅說已徴賢可輔，周公不見恨何長。","生松十八年方應，通塞人間豈合忙。"]', '["月落灯前閉北堂，神魂交入杳冥乡。","文通毫管醒来異，武帝蘅蕪覺後香。","傅说已徴賢可輔，周公不见恨何长。","生松十八年方應，通塞人间豈合忙。"]', '诗', 'shi', '', NULL, '夢 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69efbeef-7563-46c6-9dab-f919f1de2aeb', '東', '东', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["紫氣天元出故關，大明先照九垓間。","鰲山海上秦娥去，鱸鱠江邊齊掾還。","青帝郊坰平似砥，主人階級峻如山。","蟠桃樹在煙濤水，解凍風高未得攀。"]', '["紫氣天元出故关，大明先照九垓间。","鰲山海上秦娥去，鱸鱠江邊齊掾還。","青帝郊坰平似砥，主人階級峻如山。","蟠桃樹在煙濤水，解凍风高未得攀。"]', '诗', 'shi', '', NULL, '東 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8987a0f6-a89c-4224-a462-67cb9e1a7282', '西', '西', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["密雲郊外已回秋，日下崦嵫景懶收。","秦帝城高堅似鐵，李斯書上曲如鉤。","寧惟東岳凌天秀，更有長庚瞰曙流。","見說山傍偏出將，犬戎降盡復何愁。"]', '["密云郊外已回秋，日下崦嵫景懶收。","秦帝城高堅似鐵，李斯书上曲如鉤。","寧惟东岳凌天秀，更有长庚瞰曙流。","见说山傍偏出將，犬戎降尽复何愁。"]', '诗', 'shi', '', NULL, '西 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c55f66-4fa7-41a5-9849-8a1e23cb0899', '南', '南', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["罩罩嘉魚憶此方，送君前浦恨難量。","火山遠照蒼梧郡，銅柱高標碧海鄉。","陸賈幾時來越島，三閭何日濯滄浪。","鍾儀冠帶歸心阻，蝴蝶飛園萬草芳。"]', '["罩罩嘉鱼憶此方，送君前浦恨难量。","火山远照蒼梧郡，銅柱高標碧海乡。","陸賈幾时来越島，三閭何日濯滄浪。","鍾儀冠带归心阻，蝴蝶飞园万草芳。"]', '诗', 'shi', '', NULL, '南 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c207ff-14dd-4c42-9097-519e8d4bd021', '北', '北', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雪滿湖天日影微，李君降虜失良時。","窮溟駕浪鵾鵬化，極海寄書鴻雁遲。","□□□來猶未啓，殘兵奔去杳難追。","可憐燕谷花[開]晚，鄒律如何爲一吹。"]', '["雪满湖天日影微，李君降虜失良时。","窮溟駕浪鵾鵬化，極海寄书鴻雁遲。","□□□来猶未啓，殘兵奔去杳难追。","可怜燕谷花[开]晚，鄒律如何爲一吹。"]', '诗', 'shi', '', NULL, '北 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12add4a4-08f7-4e0b-89e0-4dd7adb9aee1', '雲', '云', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["漠漠沈沈向夕暉，蒼梧巫峽兩相依。","天心白日休空蔽，海上故山應自歸。","似蓋好臨千乘載，如羅堪翦六銖衣。","爲霖須救蒼生旱，莫向西郊作雨稀。"]', '["漠漠沈沈向夕暉，蒼梧巫峽兩相依。","天心白日休空蔽，海上故山應自归。","似蓋好臨千乘載，如羅堪翦六銖衣。","爲霖須救蒼生旱，莫向西郊作雨稀。"]', '诗', 'shi', '', NULL, '雲 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e90f29e-1ec0-4b6f-b0b5-27b6fe4838d6', '燕', '燕', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["從待銜泥濺客衣，百禽靈性比他稀。","何嫌何恨秋須去，無約無期春自歸。","鵰鶚不容應不怪，棟梁相庇願相依。","吳王宮女嬌相襲，合整雙毛預奮飛。"]', '["從待銜泥濺客衣，百禽靈性比他稀。","何嫌何恨秋須去，無約無期春自归。","鵰鶚不容應不怪，棟梁相庇願相依。","吳王宮女嬌相襲，合整雙毛預奮飞。"]', '诗', 'shi', '', NULL, '燕 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c2d3acc-c0ae-4c3f-a078-3e36d2de16db', '蟬', '蟬', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["寒鳴寧與衆蟲同，翼鬢緌冠豈道窮。","殼蛻已從今日化，聲愁何似去年中。","朝催籬菊花開露，暮促庭槐葉墜風。","從此最能驚賦客，計居何處轉飛蓬。"]', '["寒鳴寧與衆蟲同，翼鬢緌冠豈道窮。","殼蛻已從今日化，声愁何似去年中。","朝催籬菊花开露，暮促庭槐葉墜风。","從此最能驚賦客，計居何处轉飞蓬。"]', '诗', 'shi', '', NULL, '蟬 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d6ae932-1ab4-4689-bf8a-279b4a398ad0', '露', '露', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["鶴鳴先警雁來天，洗竹沾花處處鮮。","散綵幾當蟬飲際，凝光宜對蚌胎前。","朝垂苑草煙猶重，夜滴宮槐月正圓。","怵惕與霜同降日，蘋蘩思薦獨淒然。"]', '["鹤鳴先警雁来天，洗竹沾花处处鲜。","散綵幾當蟬饮際，凝光宜对蚌胎前。","朝垂苑草煙猶重，夜滴宮槐月正圓。","怵惕與霜同降日，蘋蘩思薦独淒然。"]', '诗', 'shi', '', NULL, '露 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1140634f-7b02-43ac-8070-a0a153ca5e9d', '霞', '霞', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["天際何人濯錦歸，偏宜殘照與晨暉。","流爲洞府千年酒，化作靈山幾襲衣。","野燒燄連殊赫奕，愁雲陰隔乍依稀。","勞生願學長生術，飡盡紅桃上漢飛。"]', '["天際何人濯錦归，偏宜殘照與晨暉。","流爲洞府千年酒，化作靈山幾襲衣。","野燒燄連殊赫奕，愁云陰隔乍依稀。","勞生願学长生術，飡尽紅桃上漢飞。"]', '诗', 'shi', '', NULL, '霞 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82569b16-e108-4b7e-8aef-4e4a5e03ebad', '蒲', '蒲', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["濯秀盤根在碧流，紫茵含露向晴抽。","編爲細履隨君步，織作輕帆送客愁。","疎葉稍爲投餌釣，密叢還礙採蓮舟。","鴛鴦鸂鶒多情甚，日日雙雙遶傍游。"]', '["濯秀盤根在碧流，紫茵含露向晴抽。","編爲細履隨君步，织作轻帆送客愁。","疎葉稍爲投餌釣，密叢還礙採蓮舟。","鴛鴦鸂鶒多情甚，日日雙雙遶傍游。"]', '诗', 'shi', '', NULL, '蒲 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('544cb9f5-860c-4db1-882a-db17e88cd08a', '泉', '泉', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["非鑿非疏出洞門，源深流嶮合還分。","高成瀑布漱逋客，清入御溝朝聖君。","迸滴幾山穿破石，迅飛層嶠噴開雲。","舊齋一帶連松竹，明月窗前枕上聞。"]', '["非鑿非疏出洞门，源深流嶮合還分。","高成瀑布漱逋客，清入御溝朝聖君。","迸滴幾山穿破石，迅飞層嶠噴开云。","旧斋一带連松竹，明月窗前枕上闻。"]', '诗', 'shi', '', NULL, '泉 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd0a254-8b3a-4dfc-8c5b-c9460216e963', '煙', '煙', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["燎野焚林見所從，惹空橫水展形容。","能滋甘雨隨車潤，不並行雲逐夢蹤。","晴鳥迴籠嘉樹薄，春亭嬌幕好花濃。","有時片片風吹去，海碧山清過幾重。"]', '["燎野焚林见所從，惹空橫水展形容。","能滋甘雨隨车潤，不並行云逐梦蹤。","晴鸟迴籠嘉樹薄，春亭嬌幕好花濃。","有时片片风吹去，海碧山清過幾重。"]', '诗', 'shi', '', NULL, '煙 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfb2efa4-daf5-4fc9-950f-44e74f85e0dd', '閑', '闲', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["不管人間是與非，白雲流水自相依。","一瓢挂樹傲時代，五柳種門吟落暉。","江上翠娥遺佩去，岸邊紅袖采蓮歸。","客星辭得漢光武，却坐東江舊蘚磯。"]', '["不管人间是與非，白云流水自相依。","一瓢挂樹傲时代，五柳種门吟落暉。","江上翠娥遺佩去，岸邊紅袖采蓮归。","客星辞得漢光武，却坐东江旧蘚磯。"]', '诗', 'shi', '', NULL, '閑 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa8e3ca-57f4-45f8-a40e-87851ed06654', '忙', '忙', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雙競龍舟疾似風，一星毬子兩明同。","平吳破蜀三除裏，滅楚圖秦百戰中。","春近杜鵑啼不斷，寒催歸雁去何窮。","兵還失路旌旗亂，驚起紅塵似轉蓬。"]', '["雙競龙舟疾似风，一星毬子兩明同。","平吳破蜀三除裏，滅楚圖秦百戰中。","春近杜鵑啼不斷，寒催归雁去何窮。","兵還失路旌旗亂，驚起紅塵似轉蓬。"]', '诗', 'shi', '', NULL, '忙 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb339274-d89b-4c79-a113-3d94d0ea5dd4', '淚', '泪', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["發事牽情不自繇，偶然惆悵即難收。","已聞抱玉沾衣濕，見說迷途滿目流。","滴盡綺筵紅燭暗，墜殘妝閣曉花羞。","世間何處偏留得，萬點分明湘水頭。"]', '["發事牽情不自繇，偶然惆悵即难收。","已闻抱玉沾衣濕，见说迷途满目流。","滴尽綺筵紅燭暗，墜殘妝閣晓花羞。","世间何处偏留得，万点分明湘水头。"]', '诗', 'shi', '', NULL, '淚 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7710181b-8ad9-4df0-ab26-5268fe33d0e1', '月', '月', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["碧落誰分造化權，結霜凝雪作嬋娟。","寒蟬若不開三穴，狡兔何從上九天。","莫見團圓明處遠，須看灣曲鑒時偏。","郄詵樹老堯蓂換，惆悵今年似去年。"]', '["碧落誰分造化權，結霜凝雪作嬋娟。","寒蟬若不开三穴，狡兔何從上九天。","莫见團圓明处远，須看灣曲鑒时偏。","郄詵樹老堯蓂換，惆悵今年似去年。"]', '诗', 'shi', '', NULL, '月 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccd7aaf-96f3-44c3-85af-055348c1743c', '依御史溫飛卿華清宮二十二韻', '依御史溫飞卿华清宮二十二韻', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["地靈蒸水暖，天氣待宸遊。","嶽拱蓮花秀，峯高玉蘂秋。","朝元雕翠閣，乞巧繡瓊樓。","碧海供驪嶺，黃金絡馬頭。","五王更入帳，七貴迭封侯。","夕雨鳴鴛瓦，朝陽曄柘裘。","伊臯爭負鼎，舜禹讓垂旒。","墮珥閑應拾，遺釵醉不收。","飛煙籠劍戟，殘月照旌斿。","履朔求衣早，臨陽解佩羞。","宮詞裁錦段，御筆落銀鉤。","帝里新豐縣，長安舊雍州。","雪衣傳貝葉，蟬鬢插山榴。","對景瞻瑤兔，昇天駕綵虬。","丹書陳北虜，玄甲擐犀牛。","聖誥多屯否，生靈少怨尤。","穹旻當有輔，帷幄豈無籌。","鳳態傷紅豔，鸞輿緩紫騮。","樹名端正在，人欲夢魂休。","讖語山旁鬼，塵銷隴畔丘。","重來芳草恨，往事落花愁。","五十年鴻業，東憑渭水流。"]', '["地靈蒸水暖，天氣待宸游。","嶽拱蓮花秀，峯高玉蘂秋。","朝元雕翠閣，乞巧繡瓊楼。","碧海供驪嶺，黄金絡马头。","五王更入帳，七貴迭封侯。","夕雨鳴鴛瓦，朝陽曄柘裘。","伊臯爭負鼎，舜禹讓垂旒。","墮珥闲應拾，遺釵醉不收。","飞煙籠劍戟，殘月照旌斿。","履朔求衣早，臨陽解佩羞。","宮词裁錦段，御笔落銀鉤。","帝里新豐縣，长安旧雍州。","雪衣傳貝葉，蟬鬢插山榴。","对景瞻瑤兔，昇天駕綵虬。","丹书陳北虜，玄甲擐犀牛。","聖誥多屯否，生靈少怨尤。","穹旻當有輔，帷幄豈無籌。","鳳態傷紅豔，鸾輿緩紫騮。","樹名端正在，人欲梦魂休。","讖語山旁鬼，塵銷隴畔丘。","重来芳草恨，往事落花愁。","五十年鴻業，东憑渭水流。"]', '诗', 'shi', '', NULL, '依御史溫飛卿華清宮二十二韻 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df0c6d1-1aad-45e6-8cad-3241a44e5409', '尚書命題瓦硯', '尚书命題瓦硯', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["遠向端溪得，皆因郢匠成。","鑿山青靄斷，琢石紫花輕。","散墨松香起，濡毫藻句清。","入臺知價重，著匣恐塵生。","守黑還全器，臨池早著名。","春闈攜就處，軍幕載將行。","不獨雄文陣，兼能助筆耕。","莫嫌涓滴潤，深染古今情。","洗處無瑕玷，添時識滿盈。","蘭亭如見用，敲戛有金聲。"]', '["远向端溪得，皆因郢匠成。","鑿山青靄斷，琢石紫花轻。","散墨松香起，濡毫藻句清。","入台知價重，著匣恐塵生。","守黑還全器，臨池早著名。","春闈携就处，軍幕載將行。","不独雄文陣，兼能助笔耕。","莫嫌涓滴潤，深染古今情。","洗处無瑕玷，添时識满盈。","蘭亭如见用，敲戛有金声。"]', '诗', 'shi', '', NULL, '尚書命題瓦硯 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed3fb07-b56a-44d5-ab3e-a53ace3f1316', '東風解凍省試', '东风解凍省試', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["暖氣飄蘋末，凍痕銷水中。","扇冰初覺泮，吹海旋成空。","入律三春照，朝宗萬里通。","岸分天影闊，色照日光融。","波起輕搖綠，鱗遊乍躍紅。","殷勤排弱羽，飛翥趂和風。"]', '["暖氣飄蘋末，凍痕銷水中。","扇冰初覺泮，吹海旋成空。","入律三春照，朝宗万里通。","岸分天影闊，色照日光融。","波起轻搖綠，鱗游乍躍紅。","殷勤排弱羽，飞翥趂和风。"]', '诗', 'shi', '', NULL, '東風解凍省試 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fed89cd-90f4-43ea-b83c-7b1aa7283627', '和僕射二十四丈牡丹八韻', '和僕射二十四丈牡丹八韻', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["帝王城裏看，無故亦無新。","忍摘都緣借，移栽未有因。","光陰嫌太促，開落一何頻。","羞殺登墻女，饒將解佩人。","蘂堪靈鳳啄，香許白龍親。","素練籠霞曉，紅妝帶臉春。","莫辭終夕醉，易老少年身。","買取歸天上，寧教逐世塵。"]', '["帝王城裏看，無故亦無新。","忍摘都緣借，移栽未有因。","光陰嫌太促，开落一何頻。","羞殺登墻女，饒將解佩人。","蘂堪靈鳳啄，香許白龙親。","素練籠霞晓，紅妝带臉春。","莫辞終夕醉，易老少年身。","買取归天上，寧教逐世塵。"]', '诗', 'shi', '', NULL, '和僕射二十四丈牡丹八韻 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1430f85-779c-400c-b141-54ea16be439b', '釣絲竹', '釣絲竹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["藋藋拂清流，堪維舴艋舟。","野蟲懸作餌，溪月曲爲鉤。","雨潤搖堦長，風吹繞指柔。","若將諸樹比，還使綠楊羞。","蠶婦非堯女，漁人是子猷。","湖邊舊栽處，長映讀書樓。"]', '["藋藋拂清流，堪維舴艋舟。","野蟲懸作餌，溪月曲爲鉤。","雨潤搖堦长，风吹繞指柔。","若將諸樹比，還使綠楊羞。","蠶婦非堯女，漁人是子猷。","湖邊旧栽处，长映读书楼。"]', '诗', 'shi', '', NULL, '釣絲竹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3d99610-47c1-41ec-80bc-7f16a45a2026', '尚書會仙亭詠薔薇夤坐中聯四韻晚歸補緝所聯因成一篇', '尚书會仙亭詠薔薇夤坐中聯四韻晚归補緝所聯因成一篇', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["結綠根株翡翠莖，句芒中夜刺猩猩。","景陽妝赴嚴鐘出，楚峽神教暮雨晴。","躑躅豈能同日語，玫瑰方可一時呈。","風吹嫩帶香苞展，露灑啼思淚點輕。","阿母蘂宮期索去，昭君榆塞闕齎行。","藂高恐礙含泥燕，架隱宜棲報曙鶯。","鬬日只憂燒密葉，映階疑欲讓雙旌。","含煙散纈佳人惜，落地遺鈿少妓爭。","丹渥不因輸繡段，錢圓誰把買花聲。","海棠若要分流品，秋菊春蘭兩恰平。"]', '["結綠根株翡翠莖，句芒中夜刺猩猩。","景陽妝赴嚴鐘出，楚峽神教暮雨晴。","躑躅豈能同日語，玫瑰方可一时呈。","风吹嫩带香苞展，露灑啼思泪点轻。","阿母蘂宮期索去，昭君榆塞闕齎行。","藂高恐礙含泥燕，架隐宜棲報曙鶯。","鬬日只憂燒密葉，映階疑欲讓雙旌。","含煙散纈佳人惜，落地遺鈿少妓爭。","丹渥不因輸繡段，錢圓誰把買花声。","海棠若要分流品，秋菊春蘭兩恰平。"]', '诗', 'shi', '', NULL, '尚書會仙亭詠薔薇夤坐中聯四韻晚歸補緝所聯因成一篇 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c395c5fa-12ff-4ccc-9431-aefb193345ce', '和尚書詠泉山瀑布十二韻', '和尚书詠泉山瀑布十二韻', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["名齊火浣溢山椒，誰把驚虹挂一條。","天外倚來秋水刃，海心飛上白龍綃。","民田鑿斷雲根引，僧圃穿通竹影澆。","噴石似煙輕漠漠，濺崖如雨冷瀟瀟。","水中蠶緒纏蒼壁，日裏虹精挂絳霄。","寒漱綠陰仙桂老，碎流紅豔野桃夭。","千尋練寫長年在，六出花開夏日消。","急恐劃分青嶂骨，久應䙀裂翠微腰。","濯纓便可譏漁父，洗耳還宜傲帝堯。","林際猨猱偏得飯，岸邊烏鵲擬爲橋。","赤城未到詩先寄，廬阜曾遊夢已遙。","數夜積霖聲更遠，郡樓欹枕聽良宵。"]', '["名齊火浣溢山椒，誰把驚虹挂一條。","天外倚来秋水刃，海心飞上白龙綃。","民田鑿斷云根引，僧圃穿通竹影澆。","噴石似煙轻漠漠，濺崖如雨冷瀟瀟。","水中蠶緒纏蒼壁，日裏虹精挂絳霄。","寒漱綠陰仙桂老，碎流紅豔野桃夭。","千尋練寫长年在，六出花开夏日消。","急恐劃分青嶂骨，久應䙀裂翠微腰。","濯纓便可譏漁父，洗耳還宜傲帝堯。","林際猨猱偏得飯，岸邊烏鵲擬爲橋。","赤城未到诗先寄，廬阜曾游梦已遙。","數夜積霖声更远，郡楼欹枕听良宵。"]', '诗', 'shi', '', NULL, '和尚書詠泉山瀑布十二韻 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf228736-e4e4-4306-bfd1-e54a57d04b44', '自詠十韻', '自詠十韻', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["只合滄洲釣與耕，忽依螢燭愧功成。","未遊宦路叨卑宦，纔到名場得大名。","梁苑二年陪衆客，溫陵十載佐雙旌。","錢財盡是侯王惠，骨肉偕承里巷榮。","拙賦偏聞鐫印賣，惡詩親見畫圖呈多栽桃李期春色，闊鑿池塘許月明。","寒益輕裯饒美寢，出乘車馬免徒行。","麤支菽粟防飢歉，薄有桮盤備送迎。","僧俗共鄰棲隱樂，妻孥同愛水雲清。","如今便死還甘分，莫更嫌他白髮生。"]', '["只合滄洲釣與耕，忽依螢燭愧功成。","未游宦路叨卑宦，纔到名場得大名。","梁苑二年陪衆客，溫陵十載佐雙旌。","錢財尽是侯王惠，骨肉偕承里巷榮。","拙賦偏闻鐫印賣，惡诗親见畫圖呈多栽桃李期春色，闊鑿池塘許月明。","寒益轻裯饒美寢，出乘车马免徒行。","麤支菽粟防飢歉，薄有桮盤備送迎。","僧俗共鄰棲隐乐，妻孥同愛水云清。","如今便死還甘分，莫更嫌他白髮生。"]', '诗', 'shi', '', NULL, '自詠十韻 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('897d7a64-5411-488b-9e59-041f74493267', '鏡中覽懷', '镜中覽懷', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["晨起梳頭忽自悲，鏡中親見數莖絲。","從今休說龍泉劍，世上恩讐報已遲。"]', '["晨起梳头忽自悲，镜中親见數莖絲。","從今休说龙泉劍，世上恩讐報已遲。"]', '诗', 'shi', '', NULL, '鏡中覽懷 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ab14d1-365b-468f-8bd7-ec53d48bdc54', '楚國史', '楚国史', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["六國商於恨最多，良弓休綰劍休磨。","君王不翦如簧舌，再得張儀欲奈何。"]', '["六国商於恨最多，良弓休綰劍休磨。","君王不翦如簧舌，再得張儀欲奈何。"]', '诗', 'shi', '', NULL, '楚國史 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac24802-68ee-4afa-81c5-1f7d8b7faff3', '張儀', '張儀', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["荆楚南來又北歸，分明舌在不應違。","懷王本是無心者，籠得蒼蠅却放飛。"]', '["荆楚南来又北归，分明舌在不應違。","懷王本是無心者，籠得蒼蠅却放飞。"]', '诗', 'shi', '', NULL, '張儀 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd3dc1d-57f7-416d-898d-2a17500b8062', '薔薇', '薔薇', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["朝露灑時如濯錦，晚風飄處似遺鈿。","重門剩著黃金鎖，莫被飛瓊摘上天。"]', '["朝露灑时如濯錦，晚风飄处似遺鈿。","重门剩著黄金鎖，莫被飞瓊摘上天。"]', '诗', 'shi', '', NULL, '薔薇 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4ee675-2158-4a82-a8ba-0b922b96f20c', '大夫松', '大夫松', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["五樹旌封許歲寒，挽柯攀葉也無端。","爭如澗底凌霜節，不受秦皇亂世官。"]', '["五樹旌封許歲寒，挽柯攀葉也無端。","爭如澗底凌霜節，不受秦皇亂世官。"]', '诗', 'shi', '', NULL, '大夫松 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e033b3ed-18e6-49e0-80fe-c3d9889a1eae', '杏園', '杏园', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["杏苑簫聲好醉鄉，春風嘉宴更無雙。","憑誰爲謔穆天子，莫把瑤池並曲江。"]', '["杏苑簫声好醉乡，春风嘉宴更無雙。","憑誰爲謔穆天子，莫把瑤池並曲江。"]', '诗', 'shi', '', NULL, '杏園 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17483666-0c00-4a97-9824-4ee04d4ca776', '蕉葉', '蕉葉', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["綠綺新裁織女機，擺風搖日影離披。","只應青帝行春罷，閑倚東牆卓翠旗。"]', '["綠綺新裁织女機，擺风搖日影離披。","只應青帝行春罷，闲倚东牆卓翠旗。"]', '诗', 'shi', '', NULL, '蕉葉 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1efd5a-19b5-4bf9-9fcf-7c9b46d2d342', '路旁草', '路旁草', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["楚甸秦原萬里平，誰教根向路傍生。","輕蹄繡轂長相蹋，合是榮時不得榮。"]', '["楚甸秦原万里平，誰教根向路傍生。","轻蹄繡轂长相蹋，合是榮时不得榮。"]', '诗', 'shi', '', NULL, '路旁草 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8846f4b5-7891-4fd0-9d83-1a1252e4ca18', '讀漢紀', '读漢紀', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["布衣空手取中原，勁卒雄師不足論。","楚國八千秦百萬，豁開胸臆一時吞。"]', '["布衣空手取中原，勁卒雄師不足論。","楚国八千秦百万，豁开胸臆一时吞。"]', '诗', 'shi', '', NULL, '讀漢紀 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('105a9483-9975-4cfa-98b1-66ce01473700', '李夫人二首 一', '李夫人二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["不望金輿到錦帷，人間樂極即須悲。","若言要識愁中貌，也似君恩日日衰。"]', '["不望金輿到錦帷，人间乐極即須悲。","若言要識愁中貌，也似君恩日日衰。"]', '诗', 'shi', '', NULL, '李夫人二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411f1c67-19e7-4de2-8843-c4bb63f2ef2e', '李夫人二首 二', '李夫人二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["招得香魂爵少翁，九華燈燭曉還空。","漢王不及吳王樂，且與西施死處同。"]', '["招得香魂爵少翁，九华灯燭晓還空。","漢王不及吳王乐，且與西施死处同。"]', '诗', 'shi', '', NULL, '李夫人二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e60bc1d2-e4b3-4087-b004-d68dd8be4c01', '明妃', '明妃', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["不用牽心恨畫工，帝家無策及邊戎。","香魂若得昇明月，夜夜還應照漢宮。"]', '["不用牽心恨畫工，帝家無策及邊戎。","香魂若得昇明月，夜夜還應照漢宮。"]', '诗', 'shi', '', NULL, '明妃 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8371affc-cbca-4219-ba38-742fac321483', '馬嵬', '马嵬', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["二百年來事遠聞，從龍誰解盡如雲。","張均兄弟皆何在，却是楊妃死報君。"]', '["二百年来事远闻，從龙誰解尽如云。","張均兄弟皆何在，却是楊妃死報君。"]', '诗', 'shi', '', NULL, '馬嵬 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b534e5f-fc54-4244-b89b-1d2146c2da67', '依韻贈南安方處士五首 一', '依韻贈南安方处士五首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["七貴五侯生肯退，利塵名網死當拋。","黔婁寂寞嚴陵臥，借問何人與結交。"]', '["七貴五侯生肯退，利塵名網死當拋。","黔婁寂寞嚴陵臥，借问何人與結交。"]', '诗', 'shi', '', NULL, '依韻贈南安方處士五首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef07fbb-9021-4200-9b1a-1a07f721f004', '依韻贈南安方處士五首 二', '依韻贈南安方处士五首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["休把羸蹄蹋霜雪，書成何處獻君王。","嵩山好與浮丘約，三十六峰雲外鄉。"]', '["休把羸蹄蹋霜雪，书成何处獻君王。","嵩山好與浮丘約，三十六峰云外乡。"]', '诗', 'shi', '', NULL, '依韻贈南安方處士五首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89d7ccef-4f26-4b71-97c7-4eb4ef83579c', '依韻贈南安方處士五首 三', '依韻贈南安方处士五首 三', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["百萬僧中不爲僧，比君知道僅誰能。","無家寄泊南安縣，六月門前也似冰。"]', '["百万僧中不爲僧，比君知道僅誰能。","無家寄泊南安縣，六月门前也似冰。"]', '诗', 'shi', '', NULL, '依韻贈南安方處士五首 三 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8cc6a21-a9b7-4f26-a70a-0074e2a33795', '依韻贈南安方處士五首 四', '依韻贈南安方处士五首 四', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["兩鬢當春却似秋，僻居誇近野僧樓。","落花明月皆臨水，明月不流花自流。"]', '["兩鬢當春却似秋，僻居誇近野僧楼。","落花明月皆臨水，明月不流花自流。"]', '诗', 'shi', '', NULL, '依韻贈南安方處士五首 四 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e678ac0-2ce4-427d-ba12-1815c411a2af', '依韻贈南安方處士五首 五', '依韻贈南安方处士五首 五', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["晉楚忙忙起戰塵，龔黃門外有高人。","一畦雲薤三株竹，席上先生未是貧。"]', '["晉楚忙忙起戰塵，龔黄门外有高人。","一畦云薤三株竹，席上先生未是貧。"]', '诗', 'shi', '', NULL, '依韻贈南安方處士五首 五 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3253dca8-6a8c-493b-aa60-f7ee4f197377', '依韻荅黃校書', '依韻荅黄校书', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["慈恩雁塔參差榜，杏苑鶯花次第遊。","白日有愁猶可散，青山高臥況無愁。"]', '["慈恩雁塔參差榜，杏苑鶯花次第游。","白日有愁猶可散，青山高臥況無愁。"]', '诗', 'shi', '', NULL, '依韻荅黃校書 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfb61907-f39f-4797-8ee8-4086c79317a9', '傷進士謝庭皓', '傷進士謝庭皓', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["獻書猶未達明君，何事先遊岱岳雲。","惟有春風護冤魄，與生青草蓋孤墳。"]', '["獻书猶未達明君，何事先游岱岳云。","惟有春风護冤魄，與生青草蓋孤墳。"]', '诗', 'shi', '', NULL, '傷進士謝庭皓 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fdf6262-27bb-4869-8d88-4c3cbc853e92', '聞司空侍郎訃音', '闻司空侍郎訃音', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["園綺生雖逢漢室，巢由死不謁堯階。","夫君歿去何人葬，合取夷齊隱處埋。"]', '["园綺生雖逢漢室，巢由死不謁堯階。","夫君歿去何人葬，合取夷齊隐处埋。"]', '诗', 'shi', '', NULL, '聞司空侍郎訃音 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409ac501-f726-41d2-b592-d21557e75699', '偶題二首 一', '偶題二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["買骨須求騏驥骨，愛毛宜採鳳皇毛。","駑駘燕雀堪何用，仍向人前價例高。"]', '["買骨須求騏驥骨，愛毛宜採鳳皇毛。","駑駘燕雀堪何用，仍向人前價例高。"]', '诗', 'shi', '', NULL, '偶題二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06dc1837-2853-434f-b1fe-f269bb0726e7', '偶題二首 二', '偶題二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["賦就長安振大名，斬蛇功與樂天爭。","歸來延壽溪頭坐，終日無人問一聲。"]', '["賦就长安振大名，斬蛇功與乐天爭。","归来延壽溪头坐，終日無人问一声。"]', '诗', 'shi', '', NULL, '偶題二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8e4a6c-57dd-4541-8527-187202242ffe', '猨', '猨', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["宿有喬林飲有溪，生來蹤跡遠塵泥。","不知心更愁何事，每向深山夜夜啼。"]', '["宿有喬林饮有溪，生来蹤跡远塵泥。","不知心更愁何事，每向深山夜夜啼。"]', '诗', 'shi', '', NULL, '猨 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91daa04-61f6-460c-9d58-2c986981ce9d', '追和賈浪仙古鏡', '追和賈浪仙古镜', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["誰開黃帝橋山冢，明月飛光出九泉。","狼藉蘚痕磨不盡，黑雲殘點汙秋天。"]', '["誰开黄帝橋山冢，明月飞光出九泉。","狼藉蘚痕磨不尽，黑云殘点汙秋天。"]', '诗', 'shi', '', NULL, '追和賈浪仙古鏡 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5454a82f-723b-4df9-8c00-057f3d24f305', '蝴蝶三首 一', '蝴蝶三首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["不並難飛繭裏蛾，有花芳處定經過。","天風相送輕飄去，却笑[蜘蛛]謾織羅。"]', '["不並难飞繭裏蛾，有花芳处定經過。","天风相送轻飄去，却笑[蜘蛛]謾织羅。"]', '诗', 'shi', '', NULL, '蝴蝶三首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9be9eaa-7c69-4371-9538-0fc0ff65d054', '蝴蝶三首 二', '蝴蝶三首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["苒苒雙雙拂畫欄，佳人偷眼再三看。","莫欺翼短飛長近，試就花間撲已難。"]', '["苒苒雙雙拂畫欄，佳人偷眼再三看。","莫欺翼短飞长近，試就花间撲已难。"]', '诗', 'shi', '', NULL, '蝴蝶三首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acfd526f-af75-430e-97f3-4bd8802df7c1', '蝴蝶三首 三', '蝴蝶三首 三', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["栩栩無因繫得他，野園荒徑一何多。","不聞絲竹誰教舞，應仗流鶯爲唱歌。"]', '["栩栩無因繫得他，野园荒徑一何多。","不闻絲竹誰教舞，應仗流鶯爲唱歌。"]', '诗', 'shi', '', NULL, '蝴蝶三首 三 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d57802d4-e343-42b6-8118-413ed13a9c10', '新刺襪', '新刺襪', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["素手春溪罷浣紗，巧裁明月半彎斜。","齊宮合贈東昏寵，好步黃金菡萏花。"]', '["素手春溪罷浣紗，巧裁明月半彎斜。","齊宮合贈东昏寵，好步黄金菡萏花。"]', '诗', 'shi', '', NULL, '新刺襪 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('622cdc8c-10b2-49c5-948a-d05689b99352', '寄華山司空侍郎', '寄华山司空侍郎', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["山掌林中第一人，鶴書時或問眠雲。","莫言疎野全無事，明月清風肯放君。"]', '["山掌林中第一人，鹤书时或问眠云。","莫言疎野全無事，明月清风肯放君。"]', '诗', 'shi', '', NULL, '寄華山司空侍郎 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b0453a-1856-4853-a9ca-618f7b951f97', '初夏戲題', '初夏戲題', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["長養薰風拂曉吹，漸開荷芰落薔薇。","青蟲也學莊周夢，化作南園蛺蝶飛。"]', '["长養薰风拂晓吹，漸开荷芰落薔薇。","青蟲也学莊周梦，化作南园蛺蝶飞。"]', '诗', 'shi', '', NULL, '初夏戲題 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9a3c12-6c44-4bcd-b63a-195fd228a93e', '客舍寓懷', '客舍寓懷', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["灑灑灘聲晚霽時，客亭風袖半披垂。","野雲行止誰相待，明月襟懷祗自知。","無伴偶吟溪上路，有花偷笑臘前枝。","牽情景物潛惆悵，忽似傷春遠別離。"]', '["灑灑灘声晚霽时，客亭风袖半披垂。","野云行止誰相待，明月襟懷祗自知。","無伴偶吟溪上路，有花偷笑臘前枝。","牽情景物潛惆悵，忽似傷春远別離。"]', '诗', 'shi', '', NULL, '客舍寓懷 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb7923e-f685-473d-ac3e-752f8b84318c', '送王郎中', '送王郎中', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["惜別遠相送，却成惆悵多。","獨歸回首處，爭那暮山何。"]', '["惜別远相送，却成惆悵多。","独归回首处，爭那暮山何。"]', '诗', 'shi', '', NULL, '送王郎中 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17f9a69e-f778-4d2c-85d6-d8e5e1098e92', '江行無題一百首 一', '江行無題一百首 一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["傾酒向漣漪，乘流欲去時。","寸心同尺璧，投此報馮夷。"]', '["傾酒向漣漪，乘流欲去时。","寸心同尺璧，投此報馮夷。"]', '诗', 'shi', '', NULL, '江行無題一百首 一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17923b7c-e3bc-49a5-8e1f-32df5f55f3b0', '江行無題一百首 二', '江行無題一百首 二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["江曲全縈楚，雲飛半自秦。","峴山迴首望，如別故鄉人。"]', '["江曲全縈楚，云飞半自秦。","峴山迴首望，如別故乡人。"]', '诗', 'shi', '', NULL, '江行無題一百首 二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('992a9fdb-a059-480a-af0b-d39f745ab7b6', '江行無題一百首 三', '江行無題一百首 三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["浦煙含夜色，冷日轉秋旻。","自有沈碑在，清光不照人。"]', '["浦煙含夜色，冷日轉秋旻。","自有沈碑在，清光不照人。"]', '诗', 'shi', '', NULL, '江行無題一百首 三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0322221c-e8dc-4373-bf1f-92b3958adb1c', '江行無題一百首 四', '江行無題一百首 四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["楚岸雲空合，楚城人不來。","祗今誰善舞，莫恨廢章臺。"]', '["楚岸云空合，楚城人不来。","祗今誰善舞，莫恨廢章台。"]', '诗', 'shi', '', NULL, '江行無題一百首 四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c08c21-408a-4d67-8417-b8d2d77545c0', '江行無題一百首 五', '江行無題一百首 五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["行背青山郭，吟當白露秋。","風流無屈宋，空詠古荆州。"]', '["行背青山郭，吟當白露秋。","风流無屈宋，空詠古荆州。"]', '诗', 'shi', '', NULL, '江行無題一百首 五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee1b9d0-4da6-48f7-b87e-b2a44bc10363', '江行無題一百首 六', '江行無題一百首 六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["晚來漁父喜，網重欲收遲。","恐有長江使，金錢願贖龜。"]', '["晚来漁父喜，網重欲收遲。","恐有长江使，金錢願贖龟。"]', '诗', 'shi', '', NULL, '江行無題一百首 六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7594595-00c0-4d3c-afd4-db2a1914bf44', '江行無題一百首 七', '江行無題一百首 七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["去指龍沙路，徒懸象闕心。","夜涼無遠夢，不爲偶聞砧。"]', '["去指龙沙路，徒懸象闕心。","夜涼無远梦，不爲偶闻砧。"]', '诗', 'shi', '', NULL, '江行無題一百首 七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('363ade9d-5052-436a-9287-e0709430d552', '江行無題一百首 八', '江行無題一百首 八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["霧雲疎有葉，雨浪細無花。","穩放扁舟去，江天自有涯。"]', '["霧云疎有葉，雨浪細無花。","穩放扁舟去，江天自有涯。"]', '诗', 'shi', '', NULL, '江行無題一百首 八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eb2e943-8e06-451c-b231-a44fb2043de9', '江行無題一百首 九', '江行無題一百首 九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["好日當秋半，層波動旅腸。","已行千里外，誰與共秋光。"]', '["好日當秋半，層波动旅腸。","已行千里外，誰與共秋光。"]', '诗', 'shi', '', NULL, '江行無題一百首 九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('895f8e9b-409c-44a0-8428-7cdf14bd07f0', '江行無題一百首 十', '江行無題一百首 十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["潤色非東里，官曹更建章。","宦遊難自定，來喚櫂船郎。"]', '["潤色非东里，官曹更建章。","宦游难自定，来喚櫂船郎。"]', '诗', 'shi', '', NULL, '江行無題一百首 十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68cb702-b6a6-401a-a1ae-98228a2d566f', '江行無題一百首 十一', '江行無題一百首 十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["夜江清未曉，徒惜月光沉。","不是因行樂，堪傷老大心。"]', '["夜江清未晓，徒惜月光沉。","不是因行乐，堪傷老大心。"]', '诗', 'shi', '', NULL, '江行無題一百首 十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a1fdcf-42df-4bac-929c-67bfc851f259', '江行無題一百首 十二', '江行無題一百首 十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["翳日多喬木，維舟取束薪。","靜聽江叟語，盡是厭兵人。"]', '["翳日多喬木，維舟取束薪。","静听江叟語，尽是厭兵人。"]', '诗', 'shi', '', NULL, '江行無題一百首 十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709f5393-5755-4f83-a422-fbc529b4649f', '江行無題一百首 十三', '江行無題一百首 十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["箭漏日初短，汀煙草未衰。","雨餘雖更綠，不是採蘋時。"]', '["箭漏日初短，汀煙草未衰。","雨餘雖更綠，不是採蘋时。"]', '诗', 'shi', '', NULL, '江行無題一百首 十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c8dff9-340c-4a2b-b480-016d0dbe12f5', '江行無題一百首 十四', '江行無題一百首 十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["山雨夜來漲，喜魚跳滿江。","岸沙平欲盡，垂蓼入船窗。"]', '["山雨夜来漲，喜鱼跳满江。","岸沙平欲尽，垂蓼入船窗。"]', '诗', 'shi', '', NULL, '江行無題一百首 十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce9bcf6f-5fa8-4dc0-98ec-7e58bc7a27b3', '江行無題一百首 十五', '江行無題一百首 十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["渚邊新鴈下，舟上獨淒涼。","俱是南來客，憐君綴一行。"]', '["渚邊新鴈下，舟上独淒涼。","俱是南来客，怜君綴一行。"]', '诗', 'shi', '', NULL, '江行無題一百首 十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f07cf10-91b2-463f-8478-2278f9e1ab62', '江行無題一百首 十六', '江行無題一百首 十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["雲密連江暗，風斜著物鳴。","一杯真戰將，笑爾作愁兵。"]', '["云密連江暗，风斜著物鳴。","一杯真戰將，笑爾作愁兵。"]', '诗', 'shi', '', NULL, '江行無題一百首 十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf6bd3d-dab6-4217-9986-5da98288d15e', '江行無題一百首 十七', '江行無題一百首 十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["柳拂斜開路，籬邊數戶村。","可能還有意，不掩向江門。"]', '["柳拂斜开路，籬邊數戶村。","可能還有意，不掩向江门。"]', '诗', 'shi', '', NULL, '江行無題一百首 十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4230b7-1a46-4ab2-bd17-bfe981c40d0a', '江行無題一百首 十八', '江行無題一百首 十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["不識相如渴，徒吟子美詩。","江清惟獨看，心外更誰知。"]', '["不識相如渴，徒吟子美诗。","江清惟独看，心外更誰知。"]', '诗', 'shi', '', NULL, '江行無題一百首 十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9867bf-cc57-4040-9e47-f7b83b3516bc', '江行無題一百首 十九', '江行無題一百首 十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["牽路沿江狹，沙崩岸不平。","盡知行處險，誰肯載時輕。"]', '["牽路沿江狹，沙崩岸不平。","尽知行处險，誰肯載时轻。"]', '诗', 'shi', '', NULL, '江行無題一百首 十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f38cbf7-7fc7-42d4-8e6f-91c7b2864482', '江行無題一百首 二十', '江行無題一百首 二十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["憔悴異靈均，非讒作逐臣。","如逢漁父問，未是獨醒人。"]', '["憔悴異靈均，非讒作逐臣。","如逢漁父问，未是独醒人。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4dfe50-60c4-43d0-a014-69d9b73fc8f0', '江行無題一百首 二十一', '江行無題一百首 二十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["水含秋夜靜，雲帶夕陽高。","詩癖非吾病，何妨吮短豪。"]', '["水含秋夜静，云带夕陽高。","诗癖非吾病，何妨吮短豪。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd471e6-b92f-42a0-82ce-d56228ad0cf3', '江行無題一百首 二十二', '江行無題一百首 二十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["帶舟維古岸，還似阻西陵。","箕伯無多怒，回頭詎不能。"]', '["带舟維古岸，還似阻西陵。","箕伯無多怒，回头詎不能。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c7a29d-7ffe-41b0-9c86-17228a396718', '江行無題一百首 二十三', '江行無題一百首 二十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["秋雲久無雨，江燕社猶飛。","却笑舟中客，今年未得歸。"]', '["秋云久無雨，江燕社猶飞。","却笑舟中客，今年未得归。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b408321b-acd7-4886-aef1-45b551ebec69', '江行無題一百首 二十四', '江行無題一百首 二十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["帆翅初張處，雲鵬怒翼同。","莫愁千里路，自有到來風。"]', '["帆翅初張处，云鵬怒翼同。","莫愁千里路，自有到来风。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a267130-ba2d-4914-8b82-5df29e273085', '江行無題一百首 二十五', '江行無題一百首 二十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["佳節雖逢菊，浮生正似萍。","故山何處望，荒岸小長亭。"]', '["佳節雖逢菊，浮生正似萍。","故山何处望，荒岸小长亭。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06fddf0-4554-41d7-af7c-46e46200b444', '江行無題一百首 二十六', '江行無題一百首 二十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["月下江流靜，村荒人語稀。","鷺鴛雖有伴，仍共影雙飛。"]', '["月下江流静，村荒人語稀。","鷺鴛雖有伴，仍共影雙飞。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ee6fec-9de5-457f-a752-9e8aa546600f', '江行無題一百首 二十七', '江行無題一百首 二十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["斗轉月未落，舟行夜已深。","有村知不遠，風便數聲砧。"]', '["斗轉月未落，舟行夜已深。","有村知不远，风便數声砧。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4dcbd8-3136-4718-93fc-9f0245695da9', '江行無題一百首 二十八', '江行無題一百首 二十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["櫂驚沙鳥迅，飛濺夕陽波。","不顧魚多處，應防一目羅。"]', '["櫂驚沙鸟迅，飞濺夕陽波。","不顧鱼多处，應防一目羅。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b162d3-33b4-41d0-9f0f-3a555bf5b8e4', '江行無題一百首 二十九', '江行無題一百首 二十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["行到楚江岸，蒼茫人正迷。","秪如秦塞遠，格磔鷓鴣啼。"]', '["行到楚江岸，蒼茫人正迷。","秪如秦塞远，格磔鷓鴣啼。"]', '诗', 'shi', '', NULL, '江行無題一百首 二十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fe859f-a505-42d7-8052-a4ff8e067c7d', '江行無題一百首 三十', '江行無題一百首 三十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["漸覺江天遠，難逢故國書。","可能無往事，空食鼎中魚。"]', '["漸覺江天远，难逢故国书。","可能無往事，空食鼎中鱼。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c875f5b6-3f93-4d07-92f5-70078123cedb', '江行無題一百首 三十一', '江行無題一百首 三十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["岸草連荒色，村聲樂稔年。","晚晴貪穫稻，閑却採菱船。"]', '["岸草連荒色，村声乐稔年。","晚晴貪穫稻，闲却採菱船。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d46ecb8b-eb8f-42fc-a9c0-c7186af637dd', '江行無題一百首 三十二', '江行無題一百首 三十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["灘淺多遊鷺，江清易見魚。","怪來吟未足，秋物欠紅蕖。"]', '["灘淺多游鷺，江清易见鱼。","怪来吟未足，秋物欠紅蕖。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085572da-1b2e-4e52-8bfb-b9caf8af40e2', '江行無題一百首 三十三', '江行無題一百首 三十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["蛩響依沙草，螢飛透水煙。","夜涼誰詠史，空泊運租船。"]', '["蛩响依沙草，螢飞透水煙。","夜涼誰詠史，空泊運租船。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb8e0968-f859-4970-9642-31ea524a118d', '江行無題一百首 三十四', '江行無題一百首 三十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["睡穩葉舟輕，風微浪不驚。","人居蘆葦岸，終夜動秋聲。"]', '["睡穩葉舟轻，风微浪不驚。","人居蘆葦岸，終夜动秋声。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0718eaea-b984-4f6e-b220-bd3459d10141', '江行無題一百首 三十五', '江行無題一百首 三十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["自念平生意，曾期一郡符。","可知因謫宦，斑鬢入江湖。"]', '["自念平生意，曾期一郡符。","可知因謫宦，斑鬢入江湖。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad835cb8-a01c-43ab-b820-c7a093c3468e', '江行無題一百首 三十六', '江行無題一百首 三十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["水天涼夜月，不是少清光。","好景隨人物，秦淮憶建康。"]', '["水天涼夜月，不是少清光。","好景隨人物，秦淮憶建康。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98612140-19f6-47f2-9d7b-3a3a48936991', '江行無題一百首 三十七', '江行無題一百首 三十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["古來多思客，搖落恨江潭。","今日秋風至，蕭疎過沔南。"]', '["古来多思客，搖落恨江潭。","今日秋风至，蕭疎過沔南。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7d6f92-d035-425c-9d45-36b42a128141', '江行無題一百首 三十八', '江行無題一百首 三十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["映竹疑村好，穿蘆覺渚幽。","漸安無曠土，薑芋當農收。"]', '["映竹疑村好，穿蘆覺渚幽。","漸安無曠土，薑芋當農收。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcebb0ff-7824-4efe-a25d-945e06f374df', '江行無題一百首 三十九', '江行無題一百首 三十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["煙渚復煙渚，畫屏休畫屏。","引愁天末去，數點暮山青。"]', '["煙渚复煙渚，畫屏休畫屏。","引愁天末去，數点暮山青。"]', '诗', 'shi', '', NULL, '江行無題一百首 三十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e525bd2c-e76d-47c9-b624-4bc009487edd', '江行無題一百首 四十', '江行無題一百首 四十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["秋風動客心，寂寂不成吟。","飛上危檣立，鶯啼報好音。"]', '["秋风动客心，寂寂不成吟。","飞上危檣立，鶯啼報好音。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04081fe-7589-4e12-9228-03502803a213', '江行無題一百首 四十一', '江行無題一百首 四十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["見底高秋水，開懷萬里天。","旅吟還有伴，沙柳數枝蟬。"]', '["见底高秋水，开懷万里天。","旅吟還有伴，沙柳數枝蟬。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53d3326-2cb4-4019-ad28-9d4dbb886011', '江行無題一百首 四十二', '江行無題一百首 四十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["九日自佳節，扁舟無一杯。","曹園舊罇酒，戲馬憶高臺。"]', '["九日自佳節，扁舟無一杯。","曹园旧罇酒，戲马憶高台。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d1ff68-1738-45d9-8041-c9f475b7bb02', '江行無題一百首 四十三', '江行無題一百首 四十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["兵火有餘燼，貧村纔數家。","無人爭曉渡，殘月下寒沙。"]', '["兵火有餘燼，貧村纔數家。","無人爭晓渡，殘月下寒沙。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ec4172-b406-446a-824c-b0c2fa2f6dfe', '江行無題一百首 四十四', '江行無題一百首 四十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["渚禽菱芡足，不向稻粱爭。","靜宿涼灣月，應無失侶聲。"]', '["渚禽菱芡足，不向稻粱爭。","静宿涼灣月，應無失侶声。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d7ffec4-22ad-4647-a18b-830af5d7fcf8', '江行無題一百首 四十五', '江行無題一百首 四十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["輕雲未撲霜，樹杪橘初黃。","行是知名物，過風過水香。"]', '["轻云未撲霜，樹杪橘初黄。","行是知名物，過风過水香。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a2152cb-d73f-4ac5-9bc0-69b2b0685cbd', '江行無題一百首 四十六', '江行無題一百首 四十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["土曠深耕少，江平遠釣多。","平生皆棄本，金革竟如何。"]', '["土曠深耕少，江平远釣多。","平生皆棄本，金革竟如何。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6cf5454-bd77-436b-b372-8ff55066fd69', '江行無題一百首 四十七', '江行無題一百首 四十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["海月非常物，等閑不可尋。","披沙應有地，淺處定無金。"]', '["海月非常物，等闲不可尋。","披沙應有地，淺处定無金。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbb3b6fe-a14a-43b4-b484-22cde1b5e0d3', '江行無題一百首 四十八', '江行無題一百首 四十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["風晚冷颼颼，蘆花已白頭。","舊來紅葉寺，堪憶玉京秋。"]', '["风晚冷颼颼，蘆花已白头。","旧来紅葉寺，堪憶玉京秋。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70770bb-7575-4323-a99a-181305e36366', '江行無題一百首 四十九', '江行無題一百首 四十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["渺渺望天涯，清漣浸赤霞。","難逢星漢使，烏鵲日乘槎。"]', '["渺渺望天涯，清漣浸赤霞。","难逢星漢使，烏鵲日乘槎。"]', '诗', 'shi', '', NULL, '江行無題一百首 四十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdcdb756-9d8d-4d7c-bbf6-fb84a626928b', '江行無題一百首 五十', '江行無題一百首 五十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["風好來無陣，雲開去有踪。","釣歌無遠近，應喜罷艨艟。"]', '["风好来無陣，云开去有踪。","釣歌無远近，應喜罷艨艟。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2ffe00-2506-45e9-9671-62f5c115c80f', '江行無題一百首 五十一', '江行無題一百首 五十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["吳疆連楚甸，楚俗異吳鄉。","謾把罇中物，無人啄蟹黃。"]', '["吳疆連楚甸，楚俗異吳乡。","謾把罇中物，無人啄蟹黄。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b131b72-8e68-4045-98c2-63079681cf03', '江行無題一百首 五十二', '江行無題一百首 五十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["岸綠野煙遠，江紅斜照微。","撑開小漁艇，應到月明歸。"]', '["岸綠野煙远，江紅斜照微。","撑开小漁艇，應到月明归。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d13ffec-4b70-43cc-a16d-fce31334b3e7', '江行無題一百首 五十三', '江行無題一百首 五十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["雨餘江始漲，漾漾見流薪。","曾歎河中木，斯言憶古人。"]', '["雨餘江始漲，漾漾见流薪。","曾歎河中木，斯言憶古人。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f2ec26-7583-4ca9-ba89-9782cca6823c', '江行無題一百首 五十四', '江行無題一百首 五十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["垂露晚猶濃，清風不易逢。","涉江雖已晚，高樹搴芙蓉。"]', '["垂露晚猶濃，清风不易逢。","涉江雖已晚，高樹搴芙蓉。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40436bf4-67f6-457c-9c22-2ca94fff9a57', '江行無題一百首 五十五', '江行無題一百首 五十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["乘舟維夏口，煙野獨行時。","不見頭陀寺，空懷幼婦碑。"]', '["乘舟維夏口，煙野独行时。","不见头陀寺，空懷幼婦碑。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0cf93ec-5ae4-4c75-811d-68401500097d', '江行無題一百首 五十六', '江行無題一百首 五十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["晚泊武昌岸，津亭疎柳風。","數株曾手植，好事憶陶公。"]', '["晚泊武昌岸，津亭疎柳风。","數株曾手植，好事憶陶公。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b82ee65c-411f-4cf7-9368-53db642a5e29', '江行無題一百首 五十七', '江行無題一百首 五十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["舟航依浦定，星斗滿江寒。","若比陰霾日，何妨夜未闌。"]', '["舟航依浦定，星斗满江寒。","若比陰霾日，何妨夜未闌。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b289e8a2-a693-459c-b4f9-1f6e62bf6617', '江行無題一百首 五十八', '江行無題一百首 五十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["近戍離金落，孤岑望火門。","惟將知命意，瀟灑向乾坤。"]', '["近戍離金落，孤岑望火门。","惟將知命意，瀟灑向乾坤。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e47625f-9684-46be-84a8-328dbfc8267e', '江行無題一百首 五十九', '江行無題一百首 五十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["叢菊生堤上，此花長後時。","有人還採掇，何必在春期。"]', '["叢菊生堤上，此花长後时。","有人還採掇，何必在春期。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7293bec0-5595-4fa1-b706-3a76dfbb596a', '江行無題一百首 六十', '江行無題一百首 六十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["景夕殘霞落，秋寒細雨晴。","短纓何用濯，舟在月中行。"]', '["景夕殘霞落，秋寒細雨晴。","短纓何用濯，舟在月中行。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f4e9c6-31c4-48a6-8979-28fcd85053d3', '江行無題一百首 六十一', '江行無題一百首 六十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["堤壞漏江水，地坳成野塘。","晚荷人不折，留取作秋香。"]', '["堤壞漏江水，地坳成野塘。","晚荷人不折，留取作秋香。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98082815-a273-4a09-92dd-812c2b3ce57f', '江行無題一百首 六十二', '江行無題一百首 六十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["左宦終何路，攄懷亦自寬。","襞牋嘲白鷺，無意喻梟鸞。"]', '["左宦終何路，攄懷亦自寬。","襞牋嘲白鷺，無意喻梟鸾。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d902f96-9427-43ff-a047-e35483e7ed7e', '江行無題一百首 六十三', '江行無題一百首 六十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["樓空人不歸，雲白去時衣。","黃鶴無心下，長應笑令威。"]', '["楼空人不归，云白去时衣。","黄鹤無心下，长應笑令威。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec9688a6-6ed2-48f7-bcee-82e31ff33b58', '江行無題一百首 六十四', '江行無題一百首 六十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["白帝朝驚浪，陽臺暮映雲。","等閑生險易，世路秪如君。"]', '["白帝朝驚浪，陽台暮映云。","等闲生險易，世路秪如君。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac7e4cbf-b8ed-40cc-a86d-6c22b5197cc3', '江行無題一百首 六十五', '江行無題一百首 六十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["櫓慢生輕浪，帆虛帶白雲。","客船雖狹小，容得瘦將軍。"]', '["櫓慢生轻浪，帆虛带白云。","客船雖狹小，容得瘦將軍。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4602b3c1-aea1-4c12-9aa9-60b8e849c939', '江行無題一百首 六十六', '江行無題一百首 六十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["靜看秋江水，風微浪漸平。","人間馳競處，塵土自波成。"]', '["静看秋江水，风微浪漸平。","人间驰競处，塵土自波成。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4905d5fb-6078-4556-a676-5dfca6682fbe', '江行無題一百首 六十七', '江行無題一百首 六十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["風借帆方疾，風回櫂却遲。","較量人世事，不校一毫釐。"]', '["风借帆方疾，风回櫂却遲。","較量人世事，不校一毫釐。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1576c5f2-48dc-4d65-a495-95dc9573e645', '江行無題一百首 六十八', '江行無題一百首 六十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["咫尺愁風雨，匡廬不可登。","秪疑雲霧窟，猶有六朝僧。"]', '["咫尺愁风雨，匡廬不可登。","秪疑云霧窟，猶有六朝僧。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6731b33f-4a02-4f5e-a543-38225b05f0d3', '江行無題一百首 六十九', '江行無題一百首 六十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["江草何多思，冬青尚滿洲。","誰能驚鵩鳥，作賦爲沙鷗。"]', '["江草何多思，冬青尚满洲。","誰能驚鵩鸟，作賦爲沙鷗。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b83dcd-14eb-4b6a-b769-0040d523839d', '江行無題一百首 七十', '江行無題一百首 七十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["幸有煙波興，寧辭筆硯勞。","緣情無怨刺，却似反離騷。"]', '["幸有煙波兴，寧辞笔硯勞。","緣情無怨刺，却似反離騷。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f7f7833-4d0a-4822-b241-8b0139d9b779', '江行無題一百首 七十一', '江行無題一百首 七十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["沙上獨行時，高吟到楚詞。","難將垂岸蓼，盈把當江蘺。"]', '["沙上独行时，高吟到楚词。","难將垂岸蓼，盈把當江蘺。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d88e8fc3-14df-4105-9451-cd4bf55f1803', '江行無題一百首 七十二', '江行無題一百首 七十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["秋寒鷹隼健，逐雀下雲空。","知是江湖客，無心擊塞鴻。"]', '["秋寒鷹隼健，逐雀下云空。","知是江湖客，無心擊塞鴻。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98315dd2-f3c5-4d6f-8386-9f0f83d9d815', '江行無題一百首 七十三', '江行無題一百首 七十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["幽懷念煙水，長恨隔龍沙。","今日滕王閣，分明見落霞。"]', '["幽懷念煙水，长恨隔龙沙。","今日滕王閣，分明见落霞。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9175459a-8e05-48dc-87a1-abf8347708cf', '江行無題一百首 七十四', '江行無題一百首 七十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["江流何渺渺，懷古獨依依。","漁父非賢者，蘆中但有磯。"]', '["江流何渺渺，懷古独依依。","漁父非賢者，蘆中但有磯。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5004eed2-2a9a-4e68-8268-ddff25dcb37d', '江行無題一百首 七十五', '江行無題一百首 七十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["風雨正甘寢，雲霓忽曉晴。","放歌雖自遣，一歲又崢嶸。"]', '["风雨正甘寢，云霓忽晓晴。","放歌雖自遣，一歲又崢嶸。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8aa0e5-5746-4f5e-a006-86ddd946dc6b', '江行無題一百首 七十六', '江行無題一百首 七十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["幽思正遲遲，沙邊濯弄時。","自憐非博物，猶未識鳧葵。"]', '["幽思正遲遲，沙邊濯弄时。","自怜非博物，猶未識鳧葵。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed934b8-4536-4021-9f24-41ab44ccdd74', '江行無題一百首 七十七', '江行無題一百首 七十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["曾有煙波客，能歌西塞山。","落花惟待月，一釣紫菱灣。"]', '["曾有煙波客，能歌西塞山。","落花惟待月，一釣紫菱灣。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d2a4ac5-6d18-4433-95fc-9426f9e49f38', '江行無題一百首 七十八', '江行無題一百首 七十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["千頃水紋細，一拳嵐影孤。","君山寒樹綠，曾過洞庭湖。"]', '["千頃水紋細，一拳嵐影孤。","君山寒樹綠，曾過洞庭湖。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa43a5f-9cdd-4b61-83ff-e789b5bde426', '江行無題一百首 七十九', '江行無題一百首 七十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["光闊重湖水，低斜遠鴈行。","未曾無興詠，多謝沈東陽。"]', '["光闊重湖水，低斜远鴈行。","未曾無兴詠，多謝沈东陽。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d7a9b2-622c-4a24-abe4-3e3ed0f783a9', '江行無題一百首 八十', '江行無題一百首 八十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["晚菊繞江壘，忽如開古屏。","莫言時節過，白日有餘馨。"]', '["晚菊繞江壘，忽如开古屏。","莫言时節過，白日有餘馨。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf07926c-f8c3-434d-bdaf-9c211f0b1bbb', '江行無題一百首 八十一', '江行無題一百首 八十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["日落長亭晚，山門步障青。","可憐無酒分，處處有旗亭。"]', '["日落长亭晚，山门步障青。","可怜無酒分，处处有旗亭。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3190cb-c1c9-46eb-9c13-d495c674f6f1', '江行無題一百首 八十二', '江行無題一百首 八十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["遠岸無行樹，經霜有伴紅。","停船搜好句，題葉贈江楓。"]', '["远岸無行樹，經霜有伴紅。","停船搜好句，題葉贈江楓。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ca9fcfd-9286-443e-bf42-9a91e0e316ad', '江行無題一百首 八十三', '江行無題一百首 八十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["身世比行舟，無風亦暫休。","敢言終破浪，惟願穩乘流。"]', '["身世比行舟，無风亦暫休。","敢言終破浪，惟願穩乘流。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51b6f9a-b058-4c34-896e-09f1f4ba286a', '江行無題一百首 八十四', '江行無題一百首 八十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["數畝蒼苔石，煙蒙鶴卵洲。","定因詞客遇，名字始風流。"]', '["數畝蒼苔石，煙蒙鹤卵洲。","定因词客遇，名字始风流。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b422a81-48ce-4768-9d6a-084896d74cff', '江行無題一百首 八十五', '江行無題一百首 八十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["興閑停桂楫，路好過松門。","不負佳山水，還開酒一樽。"]', '["兴闲停桂楫，路好過松门。","不負佳山水，還开酒一樽。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c324b9b-fcf4-4a72-8498-08ca8010507e', '江行無題一百首 八十六', '江行無題一百首 八十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["短檝休敲桂，孤根自駐萍。","自憐非劒氣，空向斗牛星。"]', '["短檝休敲桂，孤根自駐萍。","自怜非劒氣，空向斗牛星。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100b4a87-826a-4b42-8a04-434310f5daf1', '江行無題一百首 八十七', '江行無題一百首 八十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["高浪如銀屋，江風一發時。","筆端降太白，才大語終奇。"]', '["高浪如銀屋，江风一發时。","笔端降太白，才大語終奇。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7659c7b-924c-4804-9dd3-068ad9a917c2', '江行無題一百首 八十八', '江行無題一百首 八十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["細竹漁家路，晴陽看結罾。","喜來邀客坐，分與折腰菱。"]', '["細竹漁家路，晴陽看結罾。","喜来邀客坐，分與折腰菱。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d0bd63-e6c5-4a2f-890a-111a5d669d1e', '江行無題一百首 八十九', '江行無題一百首 八十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["平湖五百里，江水想通波。","不奈扁舟去，其如決計何。"]', '["平湖五百里，江水想通波。","不奈扁舟去，其如決計何。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb5b899-8f13-4bb5-aa72-365dd8bc9f1f', '江行無題一百首 九十', '江行無題一百首 九十', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["數逢雲斷處，去岸映高山。","身到章江日，應猶未得閑。"]', '["數逢云斷处，去岸映高山。","身到章江日，應猶未得闲。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b215d922-ee4b-49cf-b268-2608562a5a9f', '江行無題一百首 九十一', '江行無題一百首 九十一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["一灣斜照水，三版順風船。","未敢相邀釣，勞生只自憐。"]', '["一灣斜照水，三版順风船。","未敢相邀釣，勞生只自怜。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0e4b32-caff-4b09-92c1-d1f9defce9f9', '江行無題一百首 九十二', '江行無題一百首 九十二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["江雨正霏微，江村晚渡稀。","何曾妨釣艇，更待得魚歸。"]', '["江雨正霏微，江村晚渡稀。","何曾妨釣艇，更待得鱼归。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a8fbb3-711e-4357-a50e-b31313c83377', '江行無題一百首 九十三', '江行無題一百首 九十三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["新野舊樓名，潯陽勝賞情。","照人長一色，江月共淒清。"]', '["新野旧楼名，潯陽勝賞情。","照人长一色，江月共淒清。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005f6c5a-a14c-4396-a092-bf8d0bcf478b', '江行無題一百首 九十四', '江行無題一百首 九十四', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["願飲西江水，那吟北渚愁。","莫教留滯跡，遠比蔡昭侯。"]', '["願饮西江水，那吟北渚愁。","莫教留滯跡，远比蔡昭侯。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十四 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac16933-bda9-43ef-a68d-aa17cfa35bae', '江行無題一百首 九十五', '江行無題一百首 九十五', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["湖口分江水，東流獨有情。","常時好風物，誰伴謝宣城。"]', '["湖口分江水，东流独有情。","常时好风物，誰伴謝宣城。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十五 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3732bc1a-82b6-4dce-b1cf-0ceec9a85a02', '江行無題一百首 九十六', '江行無題一百首 九十六', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["潯陽江畔菊，應似古來秋。","爲問幽棲客，吟時得酒不。"]', '["潯陽江畔菊，應似古来秋。","爲问幽棲客，吟时得酒不。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十六 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d29e83-0bd1-4298-b8d0-d2efba89a8f7', '江行無題一百首 九十七', '江行無題一百首 九十七', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["高峯有佳號，千尺倚寒風。","若使爐煙在，猶應爲上公。"]', '["高峯有佳號，千尺倚寒风。","若使爐煙在，猶應爲上公。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十七 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2bb01ed-11bf-4919-8c6d-15f019e79e17', '江行無題一百首 九十八', '江行無題一百首 九十八', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["萬木已清霜，江邊村事忙。","故溪黃稻熟，一夜夢中香。"]', '["万木已清霜，江邊村事忙。","故溪黄稻熟，一夜梦中香。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十八 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e471aec3-1c1b-4228-9564-2ae2e8990b91', '江行無題一百首 九十九', '江行無題一百首 九十九', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["楚水苦縈回，征帆落又開。","可緣非直路，却有好風來。"]', '["楚水苦縈回，征帆落又开。","可緣非直路，却有好风来。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十九 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e56f9988-89d6-40fc-84af-dba32f882445', '江行無題一百首 一百', '江行無題一百首 一百', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["遠謫歲時[晏]，暮江風雨寒。","仍愁繫舟處，驚夢近長灘。"]', '["远謫歲时[晏]，暮江风雨寒。","仍愁繫舟处，驚梦近长灘。"]', '诗', 'shi', '', NULL, '江行無題一百首 一百 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a8471a-2b0f-482d-80b6-7606855a84fc', '春恨三首 一', '春恨三首 一', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["負罪將軍在北朝，秦淮芳草綠迢迢。","高臺愛妾魂銷盡，始得丘遲爲一招。"]', '["負罪將軍在北朝，秦淮芳草綠迢迢。","高台愛妾魂銷尽，始得丘遲爲一招。"]', '诗', 'shi', '', NULL, '春恨三首 一 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d51823f-4690-4047-bb57-a9bd95666725', '春恨三首 二', '春恨三首 二', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["久戍臨洮報未歸，篋香銷盡別時衣。","身輕願比蘭堦蝶，萬里還尋塞草飛。"]', '["久戍臨洮報未归，篋香銷尽別时衣。","身轻願比蘭堦蝶，万里還尋塞草飞。"]', '诗', 'shi', '', NULL, '春恨三首 二 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97778acd-7c68-44ef-b330-98dd0ed1b2fc', '春恨三首 三', '春恨三首 三', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["永巷頻聞小苑遊，舊恩如淚亦難收。","君前願報新顏色，團扇須防白露秋。"]', '["永巷頻闻小苑游，旧恩如泪亦难收。","君前願報新顏色，團扇須防白露秋。"]', '诗', 'shi', '', NULL, '春恨三首 三 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125d47ef-f848-442e-871a-c37a890b01d0', '蜀國偶題', '蜀国偶題', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["忽憶明皇西幸時，暗傷潛恨竟誰知。","佩蘭應語宮臣道，莫向金盤進茘枝。"]', '["忽憶明皇西幸时，暗傷潛恨竟誰知。","佩蘭應語宮臣道，莫向金盤進茘枝。"]', '诗', 'shi', '', NULL, '蜀國偶題 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b06f1c-4632-42a2-9658-31b725d90e59', '未展芭蕉', '未展芭蕉', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["冷燭無煙綠蠟乾，芳心猶卷怯春寒。","一緘書箚藏何事，會被東風暗拆看。"]', '["冷燭無煙綠蠟乾，芳心猶卷怯春寒。","一緘书箚藏何事，會被东风暗拆看。"]', '诗', 'shi', '', NULL, '未展芭蕉 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4449fbb-cf45-43a2-b3ff-4ee886423be1', '同程九早入中書', '同程九早入中书', '8f402dc5-9107-408c-bc89-c9075aa90d19', '唐', '["漢家賢相重英奇，蟠木何材也見知。","不意雲霄能自致，空驚鵷鷺忽相隨。","臘雪初明柏子殿，春光欲上萬年枝。","獨慚皇鑒明如日，未厭春光向玉墀。"]', '["漢家賢相重英奇，蟠木何材也见知。","不意云霄能自致，空驚鵷鷺忽相隨。","臘雪初明柏子殿，春光欲上万年枝。","独慚皇鑒明如日，未厭春光向玉墀。"]', '诗', 'shi', '', NULL, '同程九早入中書 錢珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65fd2bb1-6ff8-4e39-ab8b-d35acb120d6b', '陳情獻中丞', '陳情獻中丞', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["孤拙竟何營，徒希折桂名。","始終誰肯薦，得失自難明。","貢乏雄文獻，歸無瘠土耕。","滄江長發夢，紫陌久慙行。","意縱求知切，才惟懼鑒精。","五言非琢玉，十載看遷鶯。","取進心甘鈍，傷嗟骨每驚。","塵襟痕積淚，客鬢白新莖。","顧盼身堪教，吹噓羽覺生。","依門情轉切，荷德力須傾。","獎善猶憐貢，垂恩必不輕。","從茲便提挈，雲路自生榮。"]', '["孤拙竟何營，徒希折桂名。","始終誰肯薦，得失自难明。","貢乏雄文獻，归無瘠土耕。","滄江长發梦，紫陌久慙行。","意縱求知切，才惟懼鑒精。","五言非琢玉，十載看遷鶯。","取進心甘鈍，傷嗟骨每驚。","塵襟痕積泪，客鬢白新莖。","顧盼身堪教，吹噓羽覺生。","依门情轉切，荷德力須傾。","獎善猶怜貢，垂恩必不轻。","從茲便提挈，云路自生榮。"]', '诗', 'shi', '', NULL, '陳情獻中丞 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1603f9fd-4294-4988-8c85-12f3ba52807a', '長安雪後', '长安雪後', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["碧落雲收盡，天涯雪霽時。","草開當井地，樹折帶巢枝。","野渡滋寒麥，高泉漲禁池。","遙分丹闕出，迴對上林宜。","宿片攀簷取，凝花就砌窺。","氣凌禽翅束，凍入馬蹄危。","北想連沙漠，南思極海涯。","冷光兼素彩，向暮朔風吹。"]', '["碧落云收尽，天涯雪霽时。","草开當井地，樹折带巢枝。","野渡滋寒麦，高泉漲禁池。","遙分丹闕出，迴对上林宜。","宿片攀簷取，凝花就砌窺。","氣凌禽翅束，凍入马蹄危。","北想連沙漠，南思極海涯。","冷光兼素彩，向暮朔风吹。"]', '诗', 'shi', '', NULL, '長安雪後 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77576a34-b2d1-498e-9cfe-ea51f70c2083', '送友人遊東川', '送友人游东川', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["食盡須分散，將行幾願留。","春兼三月閏，人擬半年遊。","風俗同吳地，山川擁梓州。","思君登棧道，猨嘯始應愁。"]', '["食尽須分散，將行幾願留。","春兼三月閏，人擬半年游。","风俗同吳地，山川擁梓州。","思君登棧道，猨嘯始應愁。"]', '诗', 'shi', '', NULL, '送友人遊東川 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3263eec-83a9-4775-8b60-809efe95d9ff', '題樟亭驛樓', '題樟亭驛楼', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["危檻倚山城，風帆檻外行。","日生滄海赤，潮落浙江清。","秋晚遙峰出，沙乾細草平。","西陵煙樹色，長見伍員情。"]', '["危檻倚山城，风帆檻外行。","日生滄海赤，潮落浙江清。","秋晚遙峰出，沙乾細草平。","西陵煙樹色，长见伍員情。"]', '诗', 'shi', '', NULL, '題樟亭驛樓 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4ef309-8478-43a2-ad29-64c8cec6d073', '大梁送友人東遊', '大梁送友人东游', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["自古東西路，舟車此地分。","河聲梁苑夜，草色楚田曛。","鴈已多南去，蟬猶在此聞。","聖朝無諫獵，何計謁明君。"]', '["自古东西路，舟车此地分。","河声梁苑夜，草色楚田曛。","鴈已多南去，蟬猶在此闻。","聖朝無諫獵，何計謁明君。"]', '诗', 'shi', '', NULL, '大梁送友人東遊 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c07120-a988-4f69-9687-0ab62e6fa2bd', '送友人遊蜀', '送友人游蜀', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["爲儒早得名，爲客不憂程。","春盡離丹闕，花繁到錦城。","雪消巴水漲，日上劍關明。","預想迴來樹，秋蟬已數聲。"]', '["爲儒早得名，爲客不憂程。","春尽離丹闕，花繁到錦城。","雪消巴水漲，日上劍关明。","預想迴来樹，秋蟬已數声。"]', '诗', 'shi', '', NULL, '送友人遊蜀 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af4d7207-2859-4ae9-9f1b-2f0833314330', '留別友人書齋', '留別友人书斋', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["相見不相暌，一留日已西。","軒涼庭木大，巷僻鳥巢低。","背俗修琴譜，思家話藥畦。","卜鄰期太華，同上上方梯。"]', '["相见不相暌，一留日已西。","軒涼庭木大，巷僻鸟巢低。","背俗修琴譜，思家話藥畦。","卜鄰期太华，同上上方梯。"]', '诗', 'shi', '', NULL, '留別友人書齋 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a93b883-a286-4cff-b440-0d0a38749ef6', '題耿處士林亭', '題耿处士林亭', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["身向閑中老，生涯本豁然。","草堂山水下，漁艇鳥花邊。","窺井猨兼鹿，啼林鳥雜蟬。","何時人事了，依此亦高眠。"]', '["身向闲中老，生涯本豁然。","草堂山水下，漁艇鸟花邊。","窺井猨兼鹿，啼林鸟杂蟬。","何时人事了，依此亦高眠。"]', '诗', 'shi', '', NULL, '題耿處士林亭 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f655743-ad8f-41db-b1cb-a440608023df', '商於逢友人', '商於逢友人', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["行役何時了，年年骨肉分。","春風來漢棹，雪路入商雲。","水險溪難定，林寒鳥異羣。","相逢聊坐石，啼狖語中聞。"]', '["行役何时了，年年骨肉分。","春风来漢棹，雪路入商云。","水險溪难定，林寒鸟異羣。","相逢聊坐石，啼狖語中闻。"]', '诗', 'shi', '', NULL, '商於逢友人 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2064ae72-e606-4bbb-88e8-31e61194cadc', '灞上逢故人', '灞上逢故人', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["花落杏園枝，驅車問路岐。","人情誰可會，身事自堪疑。","嶽雨狂雷送，溪槎漲水吹。","家山如此景，幾處不相隨。"]', '["花落杏园枝，驱车问路岐。","人情誰可會，身事自堪疑。","嶽雨狂雷送，溪槎漲水吹。","家山如此景，幾处不相隨。"]', '诗', 'shi', '', NULL, '灞上逢故人 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3615a17-7056-4380-8317-5c2493b3470b', '發浙江', '發浙江', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["島嶼遍含煙，煙中濟大川。","山城猶轉漏，沙浦已搖船。","海曙霞浮日，江遙水合天。","此時空闊思，翻想涉窮邊。"]', '["島嶼遍含煙，煙中濟大川。","山城猶轉漏，沙浦已搖船。","海曙霞浮日，江遙水合天。","此时空闊思，翻想涉窮邊。"]', '诗', 'shi', '', NULL, '發浙江 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fdd594f-ab98-4c43-bbf3-2a07560c51ab', '晚泊旴𣅿', '晚泊旴𣅿', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["廣葦夾深流，蕭蕭到海秋。","宿船橫月浦，驚鳥遶霜洲。","雲濕淮南樹，笳清泗水樓。","徒懸鄉國思，羈跡尚東游。"]', '["廣葦夾深流，蕭蕭到海秋。","宿船橫月浦，驚鸟遶霜洲。","云濕淮南樹，笳清泗水楼。","徒懸乡国思，羈跡尚东游。"]', '诗', 'shi', '', NULL, '晚泊旴𣅿 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917e73f1-6706-4c86-9cf5-323de43d5998', '歸江南', '归江南', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["歸日值江春，看花過楚津。","草晴蟲網遍，沙曉浪痕新。","蓮葉初浮水，鷗雛已狎人。","漁心慚未遂，空厭路岐塵。"]', '["归日值江春，看花過楚津。","草晴蟲網遍，沙晓浪痕新。","蓮葉初浮水，鷗雛已狎人。","漁心慚未遂，空厭路岐塵。"]', '诗', 'shi', '', NULL, '歸江南 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f96a6d-6d44-4729-aa26-9cef6a519a2f', '代北言懷', '代北言懷', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["困馬榆關北，那堪落景催。","路行沙不絕，風與雪兼來。","草得春猶白，鴻侵夏始迴。","行人莫遠入，戍角有餘哀。"]', '["困马榆关北，那堪落景催。","路行沙不絕，风與雪兼来。","草得春猶白，鴻侵夏始迴。","行人莫远入，戍角有餘哀。"]', '诗', 'shi', '', NULL, '代北言懷 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d7ed3d-704e-415b-ab4f-e4f9e6b278cc', '春遊曲江', '春游曲江', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["誤入杏花塵，晴江一看春。","菰蒲雖似越，骨肉且非秦。","曲岸藏翹鷺，垂楊拂躍鱗。","徒憐汀草色，未是醉眠人。"]', '["誤入杏花塵，晴江一看春。","菰蒲雖似越，骨肉且非秦。","曲岸藏翹鷺，垂楊拂躍鱗。","徒怜汀草色，未是醉眠人。"]', '诗', 'shi', '', NULL, '春遊曲江 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdeeb316-5a01-432c-93f0-ef4bffe37469', '和范秘書宿省中作', '和范秘书宿省中作', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["清省宜寒夜，仙才稱獨吟。","鐘來宮轉漏，月過閤移陰。","鶴避燈前盡，芸高幄外深。","想知因此興，暫動憶山心。"]', '["清省宜寒夜，仙才稱独吟。","鐘来宮轉漏，月過閤移陰。","鹤避灯前尽，芸高幄外深。","想知因此兴，暫动憶山心。"]', '诗', 'shi', '', NULL, '和范秘書宿省中作 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee9b5cf7-035e-42fd-8499-ab7569c9bf4f', '寄華陰姚少府', '寄华陰姚少府', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["泰華當公署，爲官興可知。","硯和青靄凍，簾對白雲垂。","峻掌光浮日，危蓮影入池。","料於三考內，應惜德音移。"]', '["泰华當公署，爲官兴可知。","硯和青靄凍，簾对白云垂。","峻掌光浮日，危蓮影入池。","料於三考內，應惜德音移。"]', '诗', 'shi', '', NULL, '寄華陰姚少府 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3113647-49aa-4045-8383-55c278e0eafc', '路泊富春寄友人', '路泊富春寄友人', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["江鐘寒夕微，江鳥望巢飛。","木落山城出，潮生海棹歸。","獨吟霜島月，誰寄雪天衣。","此別三千里，關西信更稀。"]', '["江鐘寒夕微，江鸟望巢飞。","木落山城出，潮生海棹归。","独吟霜島月，誰寄雪天衣。","此別三千里，关西信更稀。"]', '诗', 'shi', '', NULL, '路泊富春寄友人 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8f895a-df99-4370-b9ac-081bc82f9c91', '梅花', '梅花', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["數萼初含雪，孤標畫本難。","香中別有韻，清極不知寒。","橫笛和愁聽，斜枝倚病看。","朔風如解意，容易莫摧殘。"]', '["數萼初含雪，孤標畫本难。","香中別有韻，清極不知寒。","橫笛和愁听，斜枝倚病看。","朔风如解意，容易莫摧殘。"]', '诗', 'shi', '', NULL, '梅花 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a13de39-0997-4e53-af27-18de3993ae90', '銅雀妓二首 一', '銅雀妓二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["嚴妝垂玉筯，妙舞對清風。","無復君王顧，春來起漸慵。"]', '["嚴妝垂玉筯，妙舞对清风。","無复君王顧，春来起漸慵。"]', '诗', 'shi', '', NULL, '銅雀妓二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f5adf4-6d02-4fdd-a379-73c647148997', '銅雀妓二首 二', '銅雀妓二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["歌咽新翻曲，香銷舊賜衣。","陵園春雨暗，不見六龍歸。"]', '["歌咽新翻曲，香銷旧賜衣。","陵园春雨暗，不见六龙归。"]', '诗', 'shi', '', NULL, '銅雀妓二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50fbaf1f-cd4f-4db2-98e6-2fe73ce30080', '春閨二首 一', '春閨二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["寒食月明雨，落花香滿泥。","佳人持錦字，無雁寄遼西。"]', '["寒食月明雨，落花香满泥。","佳人持錦字，無雁寄遼西。"]', '诗', 'shi', '', NULL, '春閨二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1df922-db4c-4d3c-ad59-68d7a4b07db8', '春閨二首 二', '春閨二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["欲剪宜春字，春寒入剪刀。","遼陽在何處，莫望寄征袍。"]', '["欲剪宜春字，春寒入剪刀。","遼陽在何处，莫望寄征袍。"]', '诗', 'shi', '', NULL, '春閨二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7abcef57-6d62-4c9f-bcbe-c1c0aa8d1657', '訪僧不遇', '訪僧不遇', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["尋僧已寂寞，林下鎖山房。","松竹雖無語，牽衣借晚涼。"]', '["尋僧已寂寞，林下鎖山房。","松竹雖無語，牽衣借晚涼。"]', '诗', 'shi', '', NULL, '訪僧不遇 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b807423-dbcc-430c-8b72-d4e666f43d6e', '田上', '田上', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["雨足高田白，披蓑半夜耕。","人牛力俱盡，東方殊未明。"]', '["雨足高田白，披蓑半夜耕。","人牛力俱尽，东方殊未明。"]', '诗', 'shi', '', NULL, '田上 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c98ad78-29df-486c-918b-c66d9f27427c', '月夕', '月夕', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["月上隨人意，人閑月更清。","朱樓高百尺，不見到天明。"]', '["月上隨人意，人闲月更清。","朱楼高百尺，不见到天明。"]', '诗', 'shi', '', NULL, '月夕 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12289c42-52d0-4ce0-b5e0-327f42c3cc79', '槿花', '槿花', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["槿花不見夕，一日一回新。","東風吹桃李，須到明年春。"]', '["槿花不见夕，一日一回新。","东风吹桃李，須到明年春。"]', '诗', 'shi', '', NULL, '槿花 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27de97c-965f-4f02-b02c-4cd4a0cb48e3', '西施灘', '西施灘', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["宰嚭亡吳國，西施陷惡名。","浣紗春水急，似有不平聲。"]', '["宰嚭亡吳国，西施陷惡名。","浣紗春水急，似有不平声。"]', '诗', 'shi', '', NULL, '西施灘 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f7c036-50fb-4b99-985b-d57199c9dbf0', '江上逢故人', '江上逢故人', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["故里琴樽侶，相逢近臘梅。","江村買一醉，破淚却成咍。"]', '["故里琴樽侶，相逢近臘梅。","江村買一醉，破泪却成咍。"]', '诗', 'shi', '', NULL, '江上逢故人 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54ab8db5-ce4e-437c-b9aa-edf1ccb02193', '牧豎', '牧豎', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["牧豎持蓑笠，逢人氣傲然。","臥牛吹短笛，耕却傍溪田。"]', '["牧豎持蓑笠，逢人氣傲然。","臥牛吹短笛，耕却傍溪田。"]', '诗', 'shi', '', NULL, '牧豎 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb031a7-c7d4-4e05-9fe5-2874eace3c63', '過農家', '過農家', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["欲羨農家子，秋新看刈禾。","蘇秦無負郭，六印又如何。"]', '["欲羨農家子，秋新看刈禾。","蘇秦無負郭，六印又如何。"]', '诗', 'shi', '', NULL, '過農家 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a2c4c7-0cef-49a6-b026-48c34a99bf29', '江夕', '江夕', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["江心秋月白，起柁信潮行。","蛟龍化爲人，半夜吹笛聲。"]', '["江心秋月白，起柁信潮行。","蛟龙化爲人，半夜吹笛声。"]', '诗', 'shi', '', NULL, '江夕 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf83bcf-e87c-4453-b884-58787c95a3dc', '春墅', '春墅', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["蛙聲近過社，農事忽已忙。","鄰婦餉田歸，不見百花芳。"]', '["蛙声近過社，農事忽已忙。","鄰婦餉田归，不见百花芳。"]', '诗', 'shi', '', NULL, '春墅 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b216c7e8-8380-4bed-b78a-ced81bd10b6b', '江村', '江村', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["日暮片帆落，江村如有情。","獨對沙上月，滿船人睡聲。"]', '["日暮片帆落，江村如有情。","独对沙上月，满船人睡声。"]', '诗', 'shi', '', NULL, '江村 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ce5c7ac-64bf-4197-a4cd-78765e34546b', '擬樂府子夜四時歌四首 一', '擬乐府子夜四时歌四首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["吳子愛桃李，月色不到地。","明朝欲看花，六宮人不睡。"]', '["吳子愛桃李，月色不到地。","明朝欲看花，六宮人不睡。"]', '诗', 'shi', '', NULL, '擬樂府子夜四時歌四首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ca0a52-e50f-43da-ad3b-a0eea7e4f03c', '擬樂府子夜四時歌四首 二', '擬乐府子夜四时歌四首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["涼軒待月生，暗裏螢飛出。","低迴不稱意，蛙鳴亂清瑟。"]', '["涼軒待月生，暗裏螢飞出。","低迴不稱意，蛙鳴亂清瑟。"]', '诗', 'shi', '', NULL, '擬樂府子夜四時歌四首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('615358ae-a271-412e-9fd0-63c822b034a1', '擬樂府子夜四時歌四首 三', '擬乐府子夜四时歌四首 三', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["月色明如晝，蟲聲入戶多。","狂夫自不歸，滿地無天河。"]', '["月色明如晝，蟲声入戶多。","狂夫自不归，满地無天河。"]', '诗', 'shi', '', NULL, '擬樂府子夜四時歌四首 三 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b7c186-da62-4dfa-8a5f-186944ee1343', '擬樂府子夜四時歌四首 四', '擬乐府子夜四时歌四首 四', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["銀缸照殘夢，零淚霑粉臆。","洞房猶自寒，何況關山北。"]', '["銀缸照殘梦，零泪霑粉臆。","洞房猶自寒，何況关山北。"]', '诗', 'shi', '', NULL, '擬樂府子夜四時歌四首 四 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8816e6ae-84ad-4db1-b132-c41ce05797f1', '寄人二首 一', '寄人二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["花上斷續雨，江頭來去風。","相思春欲盡，未遣酒尊空。"]', '["花上斷續雨，江头来去风。","相思春欲尽，未遣酒尊空。"]', '诗', 'shi', '', NULL, '寄人二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c4b0ee-27e3-4a7d-a8c1-c300a80bb39d', '寄人二首 二', '寄人二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["澹澹長江水，悠悠遠客情。","落花相與恨，到地一無聲。"]', '["澹澹长江水，悠悠远客情。","落花相與恨，到地一無声。"]', '诗', 'shi', '', NULL, '寄人二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ef7e39-4ece-44b8-825e-9ae1a179c90f', '江鷗', '江鷗', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["白鳥波上棲，見人懶飛起。","爲有求魚心，不是戀江水。"]', '["白鸟波上棲，见人懶飞起。","爲有求鱼心，不是戀江水。"]', '诗', 'shi', '', NULL, '江鷗 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1951ae4-c079-47e1-90e9-fc5fe1c7c98e', '春晚', '春晚', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["三月寒食時，日色濃於酒。","落盡牆頭花，鶯聲隔原柳。"]', '["三月寒食时，日色濃於酒。","落尽牆头花，鶯声隔原柳。"]', '诗', 'shi', '', NULL, '春晚 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a815db8-4abd-4219-aeeb-02be5d657b19', '漢宮詞', '漢宮词', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["獨詔胡衣出，天花落殿堂。","他人不敢妬，垂淚向君王。"]', '["独詔胡衣出，天花落殿堂。","他人不敢妬，垂泪向君王。"]', '诗', 'shi', '', NULL, '漢宮詞 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42dfbd71-6a02-4779-b13f-90e9f9d2be42', '旅行', '旅行', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["少壯經勤苦，衰年始浪遊。","誰憐不龜手，他處却封侯。"]', '["少壯經勤苦，衰年始浪游。","誰怜不龟手，他处却封侯。"]', '诗', 'shi', '', NULL, '旅行 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('265fb53a-27c6-41bb-9050-ada25e9f9ee9', '班婕妤', '班婕妤', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["寵極辭同輦，恩深棄後宮。","自題秋扇後，不敢怨春風。"]', '["寵極辞同輦，恩深棄後宮。","自題秋扇後，不敢怨春风。"]', '诗', 'shi', '', NULL, '班婕妤 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68edd417-9da1-4f1a-b003-2aa0cf97e535', '元日有題', '元日有題', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["十載元正酒，相歡意轉深。","自量麋鹿分，只合在山林。"]', '["十載元正酒，相歡意轉深。","自量麋鹿分，只合在山林。"]', '诗', 'shi', '', NULL, '元日有題 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f95780a-5805-4778-9005-869907237587', '古樹', '古樹', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["古樹春風入，陽和力太遲。","莫言生意盡，更引萬年枝。"]', '["古樹春风入，陽和力太遲。","莫言生意尽，更引万年枝。"]', '诗', 'shi', '', NULL, '古樹 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a9661cf-57ca-449b-b308-69c113506170', '春題二首 一', '春題二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["青春未得意，見花却如讐。","路逢白面郎，醉插花滿頭。"]', '["青春未得意，见花却如讐。","路逢白面郎，醉插花满头。"]', '诗', 'shi', '', NULL, '春題二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5feb89f-dc1b-4d9b-b523-43934ff19d07', '春題二首 二', '春題二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["滿眼桃李花，愁人如不見。","別有惜花人，東風莫吹散。"]', '["满眼桃李花，愁人如不见。","別有惜花人，东风莫吹散。"]', '诗', 'shi', '', NULL, '春題二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a56e675-4972-41f5-9b57-7a676203580a', '長安春', '长安春', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["長安牡丹開，繡轂輾晴雷。","若使花長在，人應看不回。"]', '["长安牡丹开，繡轂輾晴雷。","若使花长在，人應看不回。"]', '诗', 'shi', '', NULL, '長安春 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c67f463-679f-4c52-8e1e-dea47735aa94', '病起二首 一', '病起二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["病起春已晚，曳筇傷綠苔。","強攀庭樹枝，喚作花未開。"]', '["病起春已晚，曳筇傷綠苔。","強攀庭樹枝，喚作花未开。"]', '诗', 'shi', '', NULL, '病起二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939a80cc-e75e-499e-9251-bdeee7d598ec', '病起二首 二', '病起二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["病起遶庭除，春泥黏屐齒。","如從萬里來，骨肉滿面喜。"]', '["病起遶庭除，春泥黏屐齒。","如從万里来，骨肉满面喜。"]', '诗', 'shi', '', NULL, '病起二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74add4ef-98f9-4833-8e5c-062bdfbab8f7', '峽路', '峽路', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["清猨啼不住，白水下來新。","八月莫爲客，夜長愁殺人。"]', '["清猨啼不住，白水下来新。","八月莫爲客，夜长愁殺人。"]', '诗', 'shi', '', NULL, '峽路 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db70d0ad-809e-4236-999d-7a773d0aaf46', '長門怨', '长门怨', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["長門春欲盡，明月照花枝。","買得相如賦，君恩不可移。"]', '["长门春欲尽，明月照花枝。","買得相如賦，君恩不可移。"]', '诗', 'shi', '', NULL, '長門怨 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974b9ab5-5e91-4a0c-a515-f9516043ab2d', '月夕有懷', '月夕有懷', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["圓光照一海，遠客在孤舟。","相憶無期見，中宵獨上樓。"]', '["圓光照一海，远客在孤舟。","相憶無期见，中宵独上楼。"]', '诗', 'shi', '', NULL, '月夕有懷 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac21d367-6082-451f-8c04-d00f406a7c7b', '夜泊九江', '夜泊九江', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["夜泊江門外，歡聲月裏樓。","明朝歸去路，猶隔洞庭秋。"]', '["夜泊江门外，歡声月裏楼。","明朝归去路，猶隔洞庭秋。"]', '诗', 'shi', '', NULL, '夜泊九江 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc8ccb7-1fc2-4a61-905d-7b59c79d5571', '寒食夜', '寒食夜', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["滿地梨花白，風吹碎月明。","大家寒食夜，獨貯望鄉情。"]', '["满地梨花白，风吹碎月明。","大家寒食夜，独貯望乡情。"]', '诗', 'shi', '', NULL, '寒食夜 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1addc82e-6d17-47d7-b089-3f7273fede40', '歸燕', '归燕', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["海燕頻來去，西人獨滯留。","天邊又相送，腸斷故園秋。"]', '["海燕頻来去，西人独滯留。","天邊又相送，腸斷故园秋。"]', '诗', 'shi', '', NULL, '歸燕 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5efe86-5e9a-4e12-9b71-73710139bd5c', '長安春', '长安春', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["珠箔映高柳，美人紅袖垂。","忽聞半天語，不見上樓時。"]', '["珠箔映高柳，美人紅袖垂。","忽闻半天語，不见上楼时。"]', '诗', 'shi', '', NULL, '長安春 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4973c3cd-702f-470d-abfa-c194e4688dca', '鑾駕東回', '鑾駕东回', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["兩川花捧御衣香，萬歲山呼輦路長。","天子還從馬嵬過，別無惆悵似明皇。"]', '["兩川花捧御衣香，万歲山呼輦路长。","天子還從马嵬過，別無惆悵似明皇。"]', '诗', 'shi', '', NULL, '鑾駕東回 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a808ecb-f462-4c8d-9ae3-b8f7e0401e8a', '釣魚', '釣鱼', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["閑釣江魚不釣名，瓦甌斟酒暮山青。","醉頭倒向蘆花裏，却笑無端犯客星。"]', '["闲釣江鱼不釣名，瓦甌斟酒暮山青。","醉头倒向蘆花裏，却笑無端犯客星。"]', '诗', 'shi', '', NULL, '釣魚 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28acff24-003a-4fd0-bf3a-b8a3a5dbfc65', '西施', '西施', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["苧蘿山下如花女，占得姑蘇臺上春。","一笑不能亡敵國，五湖何處有功臣。"]', '["苧蘿山下如花女，占得姑蘇台上春。","一笑不能亡敵国，五湖何处有功臣。"]', '诗', 'shi', '', NULL, '西施 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b15cfb0-61fb-4081-aa00-3504ea2c69f4', '馬嵬', '马嵬', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["萬乘淒涼蜀路歸，眼前珠翠與心違。","重華不是風流主，湘水猶傳泣二妃。"]', '["万乘淒涼蜀路归，眼前珠翠與心違。","重华不是风流主，湘水猶傳泣二妃。"]', '诗', 'shi', '', NULL, '馬嵬 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0695c4d-445c-4f5e-876a-66ed7276ba7c', '羯鼓', '羯鼓', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["華清宮裏打撩聲，供奉絲簧束手聽。","寂莫鑾輿斜谷裏，是誰翻得雨淋鈴。"]', '["华清宮裏打撩声，供奉絲簧束手听。","寂莫鑾輿斜谷裏，是誰翻得雨淋鈴。"]', '诗', 'shi', '', NULL, '羯鼓 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd98b37a-ab9e-4091-993a-275807aaa109', '寄李左司', '寄李左司', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["柏臺蘭省共清風，鳴玉朝聯夜被同。","肯信人間有兄弟，一生長在別離中。"]', '["柏台蘭省共清风，鳴玉朝聯夜被同。","肯信人间有兄弟，一生长在別離中。"]', '诗', 'shi', '', NULL, '寄李左司 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6216d09-d483-41dc-9d17-0b06080cca81', '梅', '梅', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["溪上寒梅初滿枝，夜來霜月透芳菲。","清光寂莫思無盡，應待琴尊與解圍。"]', '["溪上寒梅初满枝，夜来霜月透芳菲。","清光寂莫思無尽，應待琴尊與解圍。"]', '诗', 'shi', '', NULL, '梅 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e02bad-41af-4ef2-93fd-18e5b496a648', '天台陳逸人', '天台陳逸人', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["絕粒空山秋復春，欲看滄海化成塵。","近拋三井更深去，不怕虎狼唯怕人。"]', '["絕粒空山秋复春，欲看滄海化成塵。","近拋三井更深去，不怕虎狼唯怕人。"]', '诗', 'shi', '', NULL, '天台陳逸人 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7691e6d-8859-45d2-b4c7-36554d206f51', '雪竇禪師', '雪竇禪師', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["雪竇峰前一派懸，雪竇五月無炎天。","客塵半日洗欲盡，師到白頭林下禪。"]', '["雪竇峰前一派懸，雪竇五月無炎天。","客塵半日洗欲尽，師到白头林下禪。"]', '诗', 'shi', '', NULL, '雪竇禪師 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f585e4de-95f0-45f7-a34e-7c4221b6d3d4', '溪上遇雨二首 一', '溪上遇雨二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["回塘雨脚如繰絲，野禽不起沈魚飛。","耕蓑釣笠取未暇，秋田有望從淋漓。"]', '["回塘雨脚如繰絲，野禽不起沈鱼飞。","耕蓑釣笠取未暇，秋田有望從淋漓。"]', '诗', 'shi', '', NULL, '溪上遇雨二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df968053-5d06-4c13-ac3f-5b8cf26e433f', '溪上遇雨二首 二', '溪上遇雨二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["坐看黑雲銜猛雨，噴灑前山此獨晴。","忽驚雲雨在頭上，却是山前晚照明。"]', '["坐看黑云銜猛雨，噴灑前山此独晴。","忽驚云雨在头上，却是山前晚照明。"]', '诗', 'shi', '', NULL, '溪上遇雨二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf0386a-3b8e-430c-937f-2c7bb5a88634', '長門怨', '长门怨', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["長門花泣一枝春，爭奈君恩別處新。","錯把黃金買詞賦，相如自是薄情人。"]', '["长门花泣一枝春，爭奈君恩別处新。","錯把黄金買词賦，相如自是薄情人。"]', '诗', 'shi', '', NULL, '長門怨 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4cbf5d5-0022-4269-8b56-9a96630563d2', '秋夕', '秋夕', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["自憐三十未西遊，傍山尋水過却秋。","一夜雨聲多少事，不思量盡到心頭。"]', '["自怜三十未西游，傍山尋水過却秋。","一夜雨声多少事，不思量尽到心头。"]', '诗', 'shi', '', NULL, '秋夕 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e62035-a049-4814-b33b-06c0a39a1368', '過隆中', '過隆中', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["玄德蒼黃起臥龍，鼎分天下一言中。","可憐蜀國關張後，不見商量徐庶功。"]', '["玄德蒼黄起臥龙，鼎分天下一言中。","可怜蜀国关張後，不见商量徐庶功。"]', '诗', 'shi', '', NULL, '過隆中 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d4e4652-222a-4e7c-aca6-2f7dcd113df6', '關下', '关下', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["百二山河壯帝畿，關門何事更開遲。","應從漏却田文後，每度聞雞不免疑。"]', '["百二山河壯帝畿，关门何事更开遲。","應從漏却田文後，每度闻雞不免疑。"]', '诗', 'shi', '', NULL, '關下 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa7a4d3-1116-4528-a746-409f534c4af2', '寒食客中有懷', '寒食客中有懷', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["江上聞鶯禁火時，百花開盡柳依依。","故園兄弟別來久，應到清明猶望歸。"]', '["江上闻鶯禁火时，百花开尽柳依依。","故园兄弟別来久，應到清明猶望归。"]', '诗', 'shi', '', NULL, '寒食客中有懷 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea4c7c1-96de-468a-b4dc-2b7ae6e1679b', '溪夜', '溪夜', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["積雪消來溪水寬，滿樓明月碎琅玕。","漁人拋得釣筒盡，却放輕舟下急灘。"]', '["積雪消来溪水寬，满楼明月碎琅玕。","漁人拋得釣筒尽，却放轻舟下急灘。"]', '诗', 'shi', '', NULL, '溪夜 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c6d58fb-45bb-4da0-9a27-c47b583dffc9', '山居臥疾廣利大師見訪', '山居臥疾廣利大師见訪', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["桐谷孫枝已上弦，野人猶臥白雲邊。","九天飛錫應相誚，三到行朝二十年。"]', '["桐谷孫枝已上弦，野人猶臥白云邊。","九天飞錫應相誚，三到行朝二十年。"]', '诗', 'shi', '', NULL, '山居臥疾廣利大師見訪 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19282c0-6f4c-4824-a886-31587743db98', '村墅', '村墅', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["正月二月村墅閑，餘糧未乏人心寬。","南鄰雨中揭屋笑，酒熟數家來相看。"]', '["正月二月村墅闲，餘糧未乏人心寬。","南鄰雨中揭屋笑，酒熟數家来相看。"]', '诗', 'shi', '', NULL, '村墅 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ba3aaa-56fb-4349-8f6c-993e59c02f11', '悲李拾遺二首 一', '悲李拾遺二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["故友從來匪石心，諫多難得主恩深。","行朝半夜煙塵起，曉殿吁嗟一鏡沈。"]', '["故友從来匪石心，諫多难得主恩深。","行朝半夜煙塵起，晓殿吁嗟一镜沈。"]', '诗', 'shi', '', NULL, '悲李拾遺二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0759e765-e492-4a53-86d3-adbd90226f36', '悲李拾遺二首 二', '悲李拾遺二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["天涯時有北來塵，因話它人及故人。","也是先皇能罪己，殿前頻得觸龍鱗。"]', '["天涯时有北来塵，因話它人及故人。","也是先皇能罪己，殿前頻得觸龙鱗。"]', '诗', 'shi', '', NULL, '悲李拾遺二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e90db7a5-9194-43db-999b-321a6111b8db', '題李將軍傳', '題李將軍傳', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["猨臂將軍去似飛，彎弓百步虜無遺。","漢文自與封侯得，何必傷嗟不遇時。"]', '["猨臂將軍去似飞，彎弓百步虜無遺。","漢文自與封侯得，何必傷嗟不遇时。"]', '诗', 'shi', '', NULL, '題李將軍傳 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f3e021b-7f42-4a98-b8da-1cd77f15ba57', '酒醒', '酒醒', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["酒醒撥剔殘灰火，多少淒涼在此中。","爐畔自斟還自醉，打窗深夜雪兼風。"]', '["酒醒撥剔殘灰火，多少淒涼在此中。","爐畔自斟還自醉，打窗深夜雪兼风。"]', '诗', 'shi', '', NULL, '酒醒 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a60dc4e6-debb-4173-b3a9-4860533b2dd7', '郊居友人相訪', '郊居友人相訪', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["柴門深掩古城秋，背郭緣溪一徑幽。","不有小園新竹色，君來那肯暫淹留。"]', '["柴门深掩古城秋，背郭緣溪一徑幽。","不有小园新竹色，君来那肯暫淹留。"]', '诗', 'shi', '', NULL, '郊居友人相訪 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3493b6cf-3c6e-449e-977f-e318c970d58e', '鏡湖雪霽貽方干', '镜湖雪霽貽方干', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["天外曉嵐和雪望，月中歸棹帶冰行。","相逢半醉吟詩苦，應抵寒猨褭樹聲。"]', '["天外晓嵐和雪望，月中归棹带冰行。","相逢半醉吟诗苦，應抵寒猨褭樹声。"]', '诗', 'shi', '', NULL, '鏡湖雪霽貽方干 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e067dc71-805f-4574-90f0-8405411ec5a0', '秋霽', '秋霽', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["雨霽長空蕩滌清，遠山初出未知名。","夜來江上如鉤月，時有驚魚擲浪聲。"]', '["雨霽长空蕩滌清，远山初出未知名。","夜来江上如鉤月，时有驚鱼擲浪声。"]', '诗', 'shi', '', NULL, '秋霽 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df58e4c6-146a-4a87-8d30-73b746131439', '謝朱常侍寄貺蜀茶剡紙二首 一', '謝朱常侍寄貺蜀茶剡紙二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["瑟瑟香塵瑟瑟泉，驚風驟雨起爐煙。","一甌解却山中醉，便覺身輕欲上天。"]', '["瑟瑟香塵瑟瑟泉，驚风驟雨起爐煙。","一甌解却山中醉，便覺身轻欲上天。"]', '诗', 'shi', '', NULL, '謝朱常侍寄貺蜀茶剡紙二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9882b179-0e51-4177-a7bd-bcbed5160927', '謝朱常侍寄貺蜀茶剡紙二首 二', '謝朱常侍寄貺蜀茶剡紙二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["百幅輕明雪未融，薛家凡紙漫深紅。","不應點染閑言語，留記將軍蓋世功。"]', '["百幅轻明雪未融，薛家凡紙漫深紅。","不應点染闲言語，留記將軍蓋世功。"]', '诗', 'shi', '', NULL, '謝朱常侍寄貺蜀茶剡紙二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6825dad7-653d-4a02-85c0-ce50569da4bd', '讀杜紫微集', '读杜紫微集', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["紫微才調復知兵，長覺風雷筆下生。","還有枉拋心力處，多於五柳賦閑情。"]', '["紫微才調复知兵，长覺风雷笔下生。","還有枉拋心力处，多於五柳賦闲情。"]', '诗', 'shi', '', NULL, '讀杜紫微集 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('745d0d5f-a3e4-4d37-a1a1-8dce3c7c8781', '寓題', '寓題', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["海上乘查便合仙，若無仙骨未如船。","人間亦有支機石，虛被聲名到洞天。"]', '["海上乘查便合仙，若無仙骨未如船。","人间亦有支機石，虛被声名到洞天。"]', '诗', 'shi', '', NULL, '寓題 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd25b8b0-12a6-4e4a-afd5-6d8a81d814dd', '寓吟集', '寓吟集', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["陶集篇篇皆有酒，崔詩句句不無杯。","醉來已共身安約，讓却詩人作酒魁。"]', '["陶集篇篇皆有酒，崔诗句句不無杯。","醉来已共身安約，讓却诗人作酒魁。"]', '诗', 'shi', '', NULL, '寓吟集 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82bb1412-3207-44e7-befd-d3ee9f3d4b96', '溪居即事', '溪居即事', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["籬外誰家不繫船，春風吹入釣魚灣。","小童疑是有村客，急向柴門去却關。"]', '["籬外誰家不繫船，春风吹入釣鱼灣。","小童疑是有村客，急向柴门去却关。"]', '诗', 'shi', '', NULL, '溪居即事 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('061dfcc6-b614-4c62-a405-2316d5a108be', '雞', '雞', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["買得晨雞共雞語，常時不用等閑鳴。","深山月黑風雨夜，欲近曉天啼一聲。"]', '["買得晨雞共雞語，常时不用等闲鳴。","深山月黑风雨夜，欲近晓天啼一声。"]', '诗', 'shi', '', NULL, '雞 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('053c7b0a-88ca-451f-84dc-76df195bc167', '獻浙東柳大夫', '獻浙东柳大夫', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["屬城甘雨幾經春，聖主全分付越人。","俗眼不知青瑣貴，江頭爭看碧油新。"]', '["屬城甘雨幾經春，聖主全分付越人。","俗眼不知青瑣貴，江头爭看碧油新。"]', '诗', 'shi', '', NULL, '獻浙東柳大夫 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5a93c9-8486-4e2c-a496-e9512e5ea123', '楊柳枝詞', '楊柳枝词', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["霧撚煙搓一索春，年年長似染來新。","應須喚作風流線，繫得東西南北人。"]', '["霧撚煙搓一索春，年年长似染来新。","應須喚作风流線，繫得东西南北人。"]', '诗', 'shi', '', NULL, '楊柳枝詞 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f43cb8-2a57-46e7-9037-da9b7c8c5f04', '楚懷王', '楚懷王', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["宮花一朵掌中開，緩急翻爲敵國媒。","六里江山天下笑，張儀容易去還來。"]', '["宮花一朵掌中开，緩急翻爲敵国媒。","六里江山天下笑，張儀容易去還来。"]', '诗', 'shi', '', NULL, '楚懷王 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ff7592-9643-4cdc-a6c3-5a8bde83b40f', '對早梅寄友人二首 一', '对早梅寄友人二首 一', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["憶得前年君寄詩，海邊三見早梅詞。","與君猶是海邊客，又見早梅花發時。"]', '["憶得前年君寄诗，海邊三见早梅词。","與君猶是海邊客，又见早梅花發时。"]', '诗', 'shi', '', NULL, '對早梅寄友人二首 一 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8351dd2-c045-42a4-ac5b-6ae504f541be', '對早梅寄友人二首 二', '对早梅寄友人二首 二', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["憶得去年有遺恨，花前未醉到無花。","清芳一夜月通白，先脫寒衣送酒家。"]', '["憶得去年有遺恨，花前未醉到無花。","清芳一夜月通白，先脫寒衣送酒家。"]', '诗', 'shi', '', NULL, '對早梅寄友人二首 二 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6266f79f-b404-4018-ae32-25d31a2eadd0', '句', '句', '3d57f2d9-ea19-475e-a45e-1e4e92091df4', '唐', '["萬里一點白，長空鳥不飛。","如今却羨相如富，猶有人間四壁居。"]', '["万里一点白，长空鸟不飞。","如今却羨相如富，猶有人间四壁居。"]', '诗', 'shi', '', NULL, '句 崔道融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b947d6b-04dc-4edd-97f1-782fe327d022', '苦吟', '苦吟', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["莫話詩中事，詩中難更無。","吟安一箇字，撚斷數莖鬚。","險覓天應悶，狂搜海亦枯。","不同文賦易，爲著者之乎。"]', '["莫話诗中事，诗中难更無。","吟安一箇字，撚斷數莖鬚。","險覓天應悶，狂搜海亦枯。","不同文賦易，爲著者之乎。"]', '诗', 'shi', '', NULL, '苦吟 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11602a93-e149-48e0-9efb-8a0911951926', '雪', '雪', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["瑞雪落紛華，隨風一向斜。","地平鋪作月，天迥撒成花。","客滿燒煙舍，牛牽賣炭車。","吾皇憂挾纊，猶自問君家。"]', '["瑞雪落紛华，隨风一向斜。","地平鋪作月，天迥撒成花。","客满燒煙舍，牛牽賣炭车。","吾皇憂挾纊，猶自问君家。"]', '诗', 'shi', '', NULL, '雪 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c61b9a-b463-43e2-b6cd-b50deb767676', '松寺', '松寺', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["山寺取涼當夏夜，共僧蹲坐石堦前。","兩三條電欲爲雨，七八箇星猶在天。","衣汗稍停牀上扇，茶香時撥澗中泉。","通宵聽論蓮華義，不藉松窗一覺眠。"]', '["山寺取涼當夏夜，共僧蹲坐石堦前。","兩三條電欲爲雨，七八箇星猶在天。","衣汗稍停牀上扇，茶香时撥澗中泉。","通宵听論蓮华義，不藉松窗一覺眠。"]', '诗', 'shi', '', NULL, '松寺 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd011c73-a35f-47cf-a44a-5410db21f04f', '贈僧', '贈僧', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["浮世浮華一斷空，偶拋煩惱到蓮宮。","高僧解語牙無水，老鶴能飛骨有風。","野色吟餘生竹外，山陰坐久入池中。","禪師莫問求名苦，滋味過於食蓼蟲。"]', '["浮世浮华一斷空，偶拋煩惱到蓮宮。","高僧解語牙無水，老鹤能飞骨有风。","野色吟餘生竹外，山陰坐久入池中。","禪師莫问求名苦，滋味過於食蓼蟲。"]', '诗', 'shi', '', NULL, '贈僧 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1402199-f1c2-4457-8db1-fe4f31568caf', '逢友人赴闕', '逢友人赴闕', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["正當天下待雍熙，丹詔徴來早爲遲。","倚馬才高猶愛藝，問牛心在肯容私。","吏開黃閣排班處，民擁青門看入時。","却笑郡人留不得，感恩唯擬立生祠。"]', '["正當天下待雍熙，丹詔徴来早爲遲。","倚马才高猶愛藝，问牛心在肯容私。","吏开黄閣排班处，民擁青门看入时。","却笑郡人留不得，感恩唯擬立生祠。"]', '诗', 'shi', '', NULL, '逢友人赴闕 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f723ecc8-751a-4fb8-8ae0-ef1485c35d58', '哭李郢端公', '哭李郢端公', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["軍門半掩槐花宅，每過猶聞哭臨聲。","北固暴亡兼在路，東都權葬未歸塋。","漸窮老僕慵看馬，著慘佳人暗理箏。","詩侶酒徒消散盡，一場春夢越王城。"]', '["軍门半掩槐花宅，每過猶闻哭臨声。","北固暴亡兼在路，东都權葬未归塋。","漸窮老僕慵看马，著慘佳人暗理箏。","诗侶酒徒消散尽，一場春梦越王城。"]', '诗', 'shi', '', NULL, '哭李郢端公 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37752376-3872-4130-b9e9-ffaf2c9e6657', '謝楊尚書惠櫻桃', '謝楊尚书惠櫻桃', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["滿合虛紅怕動搖，尚書知重賜櫻桃。","揉藍尚帶新鮮葉，潑血猶殘舊折條。","萬顆真珠輕觸破，一團甘露軟含消。","春來老病尤珍荷，併食中腸似火燒。"]', '["满合虛紅怕动搖，尚书知重賜櫻桃。","揉藍尚带新鲜葉，潑血猶殘旧折條。","万顆真珠轻觸破，一團甘露軟含消。","春来老病尤珍荷，併食中腸似火燒。"]', '诗', 'shi', '', NULL, '謝楊尚書惠櫻桃 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ca58cb9-dce4-4730-92d6-d12c5d50c81d', '寒食日戲贈李侍御', '寒食日戲贈李侍御', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["十二街如市，紅塵咽不開。","灑蹄驄馬汗，沒處看花來。"]', '["十二街如市，紅塵咽不开。","灑蹄驄马汗，沒处看花来。"]', '诗', 'shi', '', NULL, '寒食日戲贈李侍御 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c5dff5-e887-460a-a766-002473728f95', '樊川寒食二首 一', '樊川寒食二首 一', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["寒食權豪盡出行，一川如畫雨初晴。","誰家絡絡游春盛，擔入花間軋軋聲。"]', '["寒食權豪尽出行，一川如畫雨初晴。","誰家絡絡游春盛，擔入花间軋軋声。"]', '诗', 'shi', '', NULL, '樊川寒食二首 一 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6d512f-ab71-444b-a59a-57087be8ffec', '樊川寒食二首 二', '樊川寒食二首 二', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["鞍馬和花總是塵，歌聲處處有佳人。","五陵年少麤於事，栲栳量金買斷春。"]', '["鞍马和花總是塵，歌声处处有佳人。","五陵年少麤於事，栲栳量金買斷春。"]', '诗', 'shi', '', NULL, '樊川寒食二首 二 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca59afa8-a895-413f-8296-aa45f5c5e77e', '句', '句', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["只訛些子緣，應耗沒多光。","臂鷹健卒懸氈帽，騎馬佳人卷畫衫。","每過私第邀看鶴，長著公裳送上驢。","名紙毛生五門下，家僮骨立六街中。","雲間鬧鐸騾駝至，雪裏殘骸虎拽來。","樹上諮諏批頰鳥，窗間壁駮叩頭蟲。","莫欺零落殘牙齒，曾吃紅綾餅餤來。","渡水蹇驢雙耳直，避風羸僕一肩高。","高據襄陽播盛名，問人人道是詩星。","涼雨打低殘菡萏，急風吹散小蜻蜓。"]', '["只訛些子緣，應耗沒多光。","臂鷹健卒懸氈帽，騎马佳人卷畫衫。","每過私第邀看鹤，长著公裳送上驢。","名紙毛生五门下，家僮骨立六街中。","云间鬧鐸騾駝至，雪裏殘骸虎拽来。","樹上諮諏批頰鸟，窗间壁駮叩头蟲。","莫欺零落殘牙齒，曾吃紅綾餅餤来。","渡水蹇驢雙耳直，避风羸僕一肩高。","高據襄陽播盛名，问人人道是诗星。","涼雨打低殘菡萏，急风吹散小蜻蜓。"]', '诗', 'shi', '', NULL, '句 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c46af4-c563-4579-b9d5-ba21cc8c6e43', '示門生馬侍郎胤孫', '示门生马侍郎胤孫', '03b482a6-9d59-42b9-85dd-3a4f5349bab8', '唐', '["宦途最重是文衡，天與愚夫著盛名。","三主禮闈年八十，門生門下見門生。"]', '["宦途最重是文衡，天與愚夫著盛名。","三主禮闈年八十，门生门下见门生。"]', '诗', 'shi', '', NULL, '示門生馬侍郎胤孫 裴皞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eea7761-3835-4f12-a870-8f53367f2e49', '贈杜荀鶴', '贈杜荀鹤', '489b70f0-b2f2-4a49-a13e-55c1e2217f99', '唐', '["金榜曉懸生世日，玉書潛記上升時。","九華山色高千尺，未必高於第八枝。"]', '["金榜晓懸生世日，玉书潛記上升时。","九华山色高千尺，未必高於第八枝。"]', '诗', 'shi', '', NULL, '贈杜荀鶴 王希羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26c5161-22f5-4a5f-b324-e9f2928a73e4', '宮怨二首 一', '宮怨二首 一', 'd0d77d95-7ff6-457c-806c-63032d3b340e', '唐', '["塵滿金爐不炷香，黃昏獨自立重廊。","笙歌何處承恩寵，一一隨風入上陽。"]', '["塵满金爐不炷香，黄昏独自立重廊。","笙歌何处承恩寵，一一隨风入上陽。"]', '诗', 'shi', '', NULL, '宮怨二首 一 柯崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('032611ff-1328-4dba-b3cf-9c02c70f7033', '宮怨二首 二', '宮怨二首 二', 'd0d77d95-7ff6-457c-806c-63032d3b340e', '唐', '["長門槐柳半蕭疎，玉輦沈思恨有餘。","紅淚漸消傾國態，黃金誰爲達相如。"]', '["长门槐柳半蕭疎，玉輦沈思恨有餘。","紅泪漸消傾国態，黄金誰爲達相如。"]', '诗', 'shi', '', NULL, '宮怨二首 二 柯崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7c1f03c-ed0b-4f82-991d-c010c6de03c4', '早春池亭獨游三首 一', '早春池亭独游三首 一', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["春意送殘臘，春晴融小洲。","蒲茸纔簇岸，柳頰已遮樓。","便有杯觴興，可攄羈旅愁。","鳧鷖亦相狎，盡日戲清流。"]', '["春意送殘臘，春晴融小洲。","蒲茸纔簇岸，柳頰已遮楼。","便有杯觴兴，可攄羈旅愁。","鳧鷖亦相狎，尽日戲清流。"]', '诗', 'shi', '', NULL, '早春池亭獨游三首 一 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04abc7f9-21aa-40bb-90e0-d134b4dd008c', '早春池亭獨游三首 二', '早春池亭独游三首 二', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["清流環綠篠，清景媚虹橋。","鶯刷初遷羽，莎拳擬拆苗。","細沙擢暖岸，淑景動和飆。","倍憶同袍侶，相歡倒一瓢。"]', '["清流环綠篠，清景媚虹橋。","鶯刷初遷羽，莎拳擬拆苗。","細沙擢暖岸，淑景动和飆。","倍憶同袍侶，相歡倒一瓢。"]', '诗', 'shi', '', NULL, '早春池亭獨游三首 二 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42037650-82e1-41bf-9242-4f15afa08db2', '早春池亭獨游三首 三', '早春池亭独游三首 三', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["一瓢歡自足，一日興偏多。","幽意人先賞，疎叢蝶未過。","知音新句苦，窺沼醉顏酡。","萬慮從相擬，今朝欲奈何。"]', '["一瓢歡自足，一日兴偏多。","幽意人先賞，疎叢蝶未過。","知音新句苦，窺沼醉顏酡。","万慮從相擬，今朝欲奈何。"]', '诗', 'shi', '', NULL, '早春池亭獨游三首 三 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1dbe55-0d25-4eb7-84f5-85674dfc2951', '鷺鷥', '鷺鷥', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["潔白孤高生不同，頂絲清軟冷搖風。","窺魚翹立荷香裏，慕侶低翻柳影中。","幾日下巢辭紫閣，多時凝目向晴空。","摩霄志在潛修羽，會接鑾凰別葦叢。"]', '["潔白孤高生不同，頂絲清軟冷搖风。","窺鱼翹立荷香裏，慕侶低翻柳影中。","幾日下巢辞紫閣，多时凝目向晴空。","摩霄志在潛修羽，會接鑾凰別葦叢。"]', '诗', 'shi', '', NULL, '鷺鷥 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe73140-9715-4692-9f01-056a4beccf6a', '春夜二首 一', '春夜二首 一', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["幾處兵戈阻路岐，憶山心切與山違。","時難何處披懷抱，日日日斜空醉歸。"]', '["幾处兵戈阻路岐，憶山心切與山違。","时难何处披懷抱，日日日斜空醉归。"]', '诗', 'shi', '', NULL, '春夜二首 一 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10152af1-e8bf-4b0c-9c68-a4ef266f738a', '春夜二首 二', '春夜二首 二', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["一別杜陵歸未期，秪憑魂夢接親知。","近來欲睡兼難睡，夜夜夜深聞子規。"]', '["一別杜陵归未期，秪憑魂梦接親知。","近来欲睡兼难睡，夜夜夜深闻子規。"]', '诗', 'shi', '', NULL, '春夜二首 二 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e1c771-c1d1-47f4-bb5a-d5a56902892b', '曉登迎春閣', '晓登迎春閣', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["未櫛憑欄眺錦城，煙籠萬井二江明。","香風滿閣花盈戶，樹樹樹梢啼曉鶯。"]', '["未櫛憑欄眺錦城，煙籠万井二江明。","香风满閣花盈戶，樹樹樹梢啼晓鶯。"]', '诗', 'shi', '', NULL, '曉登迎春閣 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35b0794-45a0-4f3a-a8a9-6b68d0f2a28a', '詠仙掌', '詠仙掌', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["萬古亭亭倚碧霄，不成擎亦不成招。","何如掬取天池水，灑向人間救旱苗。"]', '["万古亭亭倚碧霄，不成擎亦不成招。","何如掬取天池水，灑向人间救旱苗。"]', '诗', 'shi', '', NULL, '詠仙掌 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63223863-df5d-4277-b245-4cff39f7c87f', '郪中感舊', '郪中感旧', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["頃年曾住此中來，今日重游事可哀。","憶得幾家歡宴處，家家家業盡成灰。"]', '["頃年曾住此中来，今日重游事可哀。","憶得幾家歡宴处，家家家業尽成灰。"]', '诗', 'shi', '', NULL, '郪中感舊 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dce6d5a0-b9b3-405d-9d6a-f4bb00c2808c', '白髭', '白髭', 'd9f8f165-6652-4ef1-bdc7-855e5ef1cf6e', '唐', '["到處逢人求至藥，幾回染了又成絲。","素絲易染髭難染，墨翟當時合泣髭。"]', '["到处逢人求至藥，幾回染了又成絲。","素絲易染髭难染，墨翟當时合泣髭。"]', '诗', 'shi', '', NULL, '白髭 劉象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc0fa45-42bd-45b9-886e-394ce63f7770', '題縣令范傳真化洽亭', '題縣令范傳真化洽亭', '0c6b2572-19cc-4778-ae8b-258dfb8bfcaa', '唐', '["前有淺山，屹然如屏。","後有卑嶺，繚然如城。","跨池左右，足以建亭。","斯亭何名，化洽而成。"]', '["前有淺山，屹然如屏。","後有卑嶺，繚然如城。","跨池左右，足以建亭。","斯亭何名，化洽而成。"]', '诗', 'shi', '', NULL, '題縣令范傳真化洽亭 沈顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef77519a-bf95-4d2d-82f8-6b45675ede51', '書懷寄友人', '书懷寄友人', '0c6b2572-19cc-4778-ae8b-258dfb8bfcaa', '唐', '["江湖勞遍尋，祗自長愁襟。","到處慵開口，何人可話心。","登樓得句遠，望月抒情深。","却憶山齋後，猿聲相伴吟。"]', '["江湖勞遍尋，祗自长愁襟。","到处慵开口，何人可話心。","登楼得句远，望月抒情深。","却憶山斋後，猿声相伴吟。"]', '诗', 'shi', '', NULL, '書懷寄友人 沈顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1847ed8-c71b-4e23-adb5-2cb4bdfeb836', '題壁', '題壁', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["院似禪心靜，花如覺性圓。","自然知了義，爭肯學神仙。"]', '["院似禪心静，花如覺性圓。","自然知了義，爭肯学神仙。"]', '诗', 'shi', '', NULL, '題壁 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b45062b3-208b-4629-83e4-b5cbb0545fb3', '贈張全義', '贈張全義', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["洛陽風景實堪哀，昔日曾爲瓦子堆。","不是我公重葺理，至今猶是一堆灰。"]', '["洛陽风景實堪哀，昔日曾爲瓦子堆。","不是我公重葺理，至今猶是一堆灰。"]', '诗', 'shi', '', NULL, '贈張全義 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b06b80-2106-478e-9d16-34454c4fb6a1', '題懷素酒狂貼後', '題懷素酒狂貼後', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["十年揮素學臨池，始識王公學衛非。","草聖未須因酒發，筆端應解化龍飛。"]', '["十年揮素学臨池，始識王公学衛非。","草聖未須因酒發，笔端應解化龙飞。"]', '诗', 'shi', '', NULL, '題懷素酒狂貼後 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33709353-14db-44a6-8853-2abfcbfd6fdb', '句', '句', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["押引蝗蟲到洛京，合消郡守遠相迎。","到此今經三紀春。"]', '["押引蝗蟲到洛京，合消郡守远相迎。","到此今經三紀春。"]', '诗', 'shi', '', NULL, '句 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c08cf828-4af2-4026-8e3f-4ad565f219eb', '奉試詔用拓拔思恭爲京北收復都統', '奉試詔用拓拔思恭爲京北收复都統', '794c1338-f47f-40a6-b0a5-73c9be374dd9', '唐', '["飛騎經巴棧，鴻恩及夏臺。","將從天上去，人自日邊來。","此處金門遠，何時玉輦迴。","早平關右賊，莫待詔書催。"]', '["飞騎經巴棧，鴻恩及夏台。","將從天上去，人自日邊来。","此处金门远，何时玉輦迴。","早平关右賊，莫待詔书催。"]', '诗', 'shi', '', NULL, '奉試詔用拓拔思恭爲京北收復都統 李琪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea069414-3057-4b62-ace3-b1258ed5c167', '題廣愛寺楞伽山', '題廣愛寺楞伽山', '794c1338-f47f-40a6-b0a5-73c9be374dd9', '唐', '["善高天外遠，方丈海中遙。","自有山神護，應無劫火燒。","壞文侵古壁，飛劍出寒霄。","何似蒼蒼色，嚴妝十七朝。"]', '["善高天外远，方丈海中遙。","自有山神護，應無劫火燒。","壞文侵古壁，飞劍出寒霄。","何似蒼蒼色，嚴妝十七朝。"]', '诗', 'shi', '', NULL, '題廣愛寺楞伽山 李琪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac426724-c5fb-45a5-9438-4a294d2dcc82', '句', '句', '794c1338-f47f-40a6-b0a5-73c9be374dd9', '唐', '["哀痛不下詔，登封誰上書。"]', '["哀痛不下詔，登封誰上书。"]', '诗', 'shi', '', NULL, '句 李琪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd38359-8583-4024-8d49-8c9d24b4e945', '寄桂帥', '寄桂帥', '57a0bc80-8a2b-4028-b4cc-e5a1b45dc0c9', '唐', '["碧幢仁施合洪鈞，桂樹林前倍得春。","莫戀此時好風景，磻溪不是釣漁人。"]', '["碧幢仁施合洪鈞，桂樹林前倍得春。","莫戀此时好风景，磻溪不是釣漁人。"]', '诗', 'shi', '', NULL, '寄桂帥 劉崇龜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6b5efd-247f-4458-ad94-8e91be044942', '席上吟', '席上吟', 'bc5e1b29-3070-4201-82c8-9e8f5893e7f6', '唐', '["南行忽見李深之，手舞如蜚令不疑。","任有風流兼蘊藉，天生不似鄭都知。"]', '["南行忽见李深之，手舞如蜚令不疑。","任有风流兼蘊藉，天生不似鄭都知。"]', '诗', 'shi', '', NULL, '席上吟 劉崇魯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9570d1-808c-4adb-b0ed-11ced6affb6a', '寄孫儲', '寄孫儲', '979fc276-a942-449b-a30e-85fb3f81ce72', '唐', '["行行血淚灑塵襟，事逐東流渭水深。","秋跨蹇驢風尚緊，靜投孤店日初沈。","一枝猶挂東堂夢，千里空馳北巷心。","明月悲歌又前去，滿城煙樹噪春禽。"]', '["行行血泪灑塵襟，事逐东流渭水深。","秋跨蹇驢风尚緊，静投孤店日初沈。","一枝猶挂东堂梦，千里空驰北巷心。","明月悲歌又前去，满城煙樹噪春禽。"]', '诗', 'shi', '', NULL, '寄孫儲 孫定 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a8ebcd-bd40-495a-8d32-f2a4730d64e5', '江南行', '江南行', '6904380e-61ea-42b0-85eb-274dbc4c509f', '唐', '["江南蕭灑地，本自與君宜。","固節還同我，虛心欲待誰。","澗泉傍借響，山木共含滋。","粉膩蟲難篆，叢疎鳥易窺。","盡應逢野渡，中忽見村祠。","葉掃秋空靜，根橫古塹危。","影迷寒靄裏，聲出夜風時。","客棹深深過，人家遠遠移。","游邊曾結念，到此數題詩。","莫恨成龍晚，成龍會有期。"]', '["江南蕭灑地，本自與君宜。","固節還同我，虛心欲待誰。","澗泉傍借响，山木共含滋。","粉膩蟲难篆，叢疎鸟易窺。","尽應逢野渡，中忽见村祠。","葉掃秋空静，根橫古塹危。","影迷寒靄裏，声出夜风时。","客棹深深過，人家远远移。","游邊曾結念，到此數題诗。","莫恨成龙晚，成龙會有期。"]', '诗', 'shi', '', NULL, '江南行 許晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e92858e-1b32-49fb-87d7-4ccd3f21e8d5', '中秋月', '中秋月', '6904380e-61ea-42b0-85eb-274dbc4c509f', '唐', '["應是蟾宮別有情，每逢秋半倍澄清。","清光不向此中見，白髮爭教何處生？","閑地占將真可惜，幽窗分得始爲明。","殷勤好長來年桂，莫遣平人道不平。"]', '["應是蟾宮別有情，每逢秋半倍澄清。","清光不向此中见，白髮爭教何处生？","闲地占將真可惜，幽窗分得始爲明。","殷勤好长来年桂，莫遣平人道不平。"]', '诗', 'shi', '', NULL, '中秋月 許晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('830c5d07-a36a-4250-a13a-f07414dd3915', '臨終詩', '臨終诗', '923b9e58-eec7-49ad-9758-941bbc3d8811', '唐', '["舊國深恩不易酬，又離繼母出他州。","誰知天怒無因息，積媿終身乞速休。"]', '["旧国深恩不易酬，又離繼母出他州。","誰知天怒無因息，積媿終身乞速休。"]', '诗', 'shi', '', NULL, '臨終詩 薛凖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ec7c49-9bfb-40ef-8272-280670328274', '觀修處士畫桃花圖歌', '观修处士畫桃花圖歌', 'e4a1a8a5-7630-4de6-8f71-03208c06034b', '唐', '["一從天寶王維死，于今始遇修夫子。","能向鮫綃四幅中，丹青暗與春爭工。","勾芒若見應羞殺，暈綠勻紅漸分別。","堪憐彩筆似東風，一朵一枝隨手發。","燕支乍溼如含露，引得嬌鶯癡不去。","多少遊蜂盡日飛，看遍花心求入處。","工夫妙麗實奇絕，似對韶光好時節。","偏宜留著待深冬，鋪向樓前殛霜雪。"]', '["一從天寶王維死，于今始遇修夫子。","能向鮫綃四幅中，丹青暗與春爭工。","勾芒若见應羞殺，暈綠勻紅漸分別。","堪怜彩笔似东风，一朵一枝隨手發。","燕支乍溼如含露，引得嬌鶯癡不去。","多少游蜂尽日飞，看遍花心求入处。","工夫妙丽實奇絕，似对韶光好时節。","偏宜留著待深冬，鋪向楼前殛霜雪。"]', '诗', 'shi', '', NULL, '觀修處士畫桃花圖歌 裴諧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd55721-a10f-45ce-9790-b3f92cef1c14', '句', '句', 'e4a1a8a5-7630-4de6-8f71-03208c06034b', '唐', '["風回山火斷，朝落岸冰高。","名終埋不得，骨任朽何妨。"]', '["风回山火斷，朝落岸冰高。","名終埋不得，骨任朽何妨。"]', '诗', 'shi', '', NULL, '句 裴諧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60e7f3f5-a13c-48c4-8577-59a84f02f5bd', '長安春日', '长安春日', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["浩浩看花晨，六街揚遠塵。","塵中一丈日，誰是晏眠人。","御柳舞着水，野鸎啼破春。","徒云多失意，猶自惜離秦。"]', '["浩浩看花晨，六街揚远塵。","塵中一丈日，誰是晏眠人。","御柳舞着水，野鸎啼破春。","徒云多失意，猶自惜離秦。"]', '诗', 'shi', '', NULL, '長安春日 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209fa9c9-2ea4-48e8-90dc-32bc6b35515a', '慈恩寺貽楚霄上人', '慈恩寺貽楚霄上人', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["在秦生楚思，波浪接禪關。","塔礙高林鳥，窗開白日山。","樹陰移草上，岸色透庭間。","入內談經徹，空攜講疏還。"]', '["在秦生楚思，波浪接禪关。","塔礙高林鸟，窗开白日山。","樹陰移草上，岸色透庭间。","入內談經徹，空携講疏還。"]', '诗', 'shi', '', NULL, '慈恩寺貽楚霄上人 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dce131be-63ca-4cf6-a119-1cedadf62d2a', '崇義里言懷', '崇義里言懷', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["馬蹄京洛岐，復此少閑時。","老積滄洲夢，秋乖白閣期。","平生五字句，一夕滿頭絲。","把向侯門去，侯門未可知。"]', '["马蹄京洛岐，复此少闲时。","老積滄洲梦，秋乖白閣期。","平生五字句，一夕满头絲。","把向侯门去，侯门未可知。"]', '诗', 'shi', '', NULL, '崇義里言懷 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cd3b4e-f5c8-4b8f-8702-2da48ea583b4', '僧院松', '僧院松', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["此木韻彌全，秋霄學瑟弦。","空知百餘尺，未定幾多年。","古甲磨雲拆，孤根捉地堅。","何當拋一幹，作蓋道場前。"]', '["此木韻彌全，秋霄学瑟弦。","空知百餘尺，未定幾多年。","古甲磨云拆，孤根捉地堅。","何當拋一幹，作蓋道場前。"]', '诗', 'shi', '', NULL, '僧院松 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb54f2d-1806-450f-8367-6ea7d9caeb5d', '貽世', '貽世', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["富者非義取，樸風爭肯還。","紅塵不待曉，白首有誰閒。","淺度四溟水，平看諸國山。","只消年作劫，俱到總無間。"]', '["富者非義取，樸风爭肯還。","紅塵不待晓，白首有誰閒。","淺度四溟水，平看諸国山。","只消年作劫，俱到總無间。"]', '诗', 'shi', '', NULL, '貽世 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76035e48-29d5-4bf5-a24e-5d32279e8f1f', '南遊', '南游', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["直到南箕下，方諳漲海頭。","君恩過銅柱，戎節限交州。","犀占花陰臥，波衝瘴色流。","遠夷非不樂，自是北人愁。"]', '["直到南箕下，方諳漲海头。","君恩過銅柱，戎節限交州。","犀占花陰臥，波衝瘴色流。","远夷非不乐，自是北人愁。"]', '诗', 'shi', '', NULL, '南遊 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eba9433-c4e8-4ec2-8068-eb334a584a8c', '送胡中丞使日東', '送胡中丞使日东', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["辭天理玉簪，指日使雞林。","猶有中華戀，方同積浪深。","張帆度鯨口，銜命見臣心。","渥澤遐宣後，歸期抵萬金。"]', '["辞天理玉簪，指日使雞林。","猶有中华戀，方同積浪深。","張帆度鯨口，銜命见臣心。","渥澤遐宣後，归期抵万金。"]', '诗', 'shi', '', NULL, '送胡中丞使日東 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef5d938-b410-448e-9349-0592d63d315f', '哭陳陶處士', '哭陳陶处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["園裏先生塚，鳥啼春更傷。","空餘八封樹，尚對一茅堂。","白日埋杜甫，皇天無耒陽。","如何稽古力，報答甚茫茫。"]', '["园裏先生塚，鸟啼春更傷。","空餘八封樹，尚对一茅堂。","白日埋杜甫，皇天無耒陽。","如何稽古力，報答甚茫茫。"]', '诗', 'shi', '', NULL, '哭陳陶處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e65be977-d851-44bf-9d2d-2ea3acbd7cca', '言懷', '言懷', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["冥心坐似癡，寢食亦如遺。","爲覓出人句，秪求當路知。","豈能窮到老，未信達無時。","此道須天付，三光幸不私。"]', '["冥心坐似癡，寢食亦如遺。","爲覓出人句，秪求當路知。","豈能窮到老，未信達無时。","此道須天付，三光幸不私。"]', '诗', 'shi', '', NULL, '言懷 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb48263-ea8d-41b9-a4fa-bad775efa136', '月', '月', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["寥寥天地內，夜魄爽何輕。","頻見此輪滿，即應華髮生。","不圓爭得破，纔正又須傾。","人事還如此，因知倚伏情。"]', '["寥寥天地內，夜魄爽何轻。","頻见此輪满，即應华髮生。","不圓爭得破，纔正又須傾。","人事還如此，因知倚伏情。"]', '诗', 'shi', '', NULL, '月 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7c1295e-cd08-416e-a6ed-60b1d21f1607', '答匡山僧贈榔栗杖', '答匡山僧贈榔栗杖', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["栗杖出匡頂，百中無一枝。","雖因野僧得，猶畏嶽神知。","畫月冷光在，指雲秋片移。","宜留引蹇步，他日訪峨嵋。"]', '["栗杖出匡頂，百中無一枝。","雖因野僧得，猶畏嶽神知。","畫月冷光在，指云秋片移。","宜留引蹇步，他日訪峨嵋。"]', '诗', 'shi', '', NULL, '答匡山僧贈榔栗杖 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75395ac-9670-4d1e-b67c-e5b2abc63dab', '商山夜聞泉', '商山夜闻泉', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["瀉月聲不斷，坐來心益閑。","無人知落處，萬木冷空山。","遠憶雲容外，幽疑石縫間。","那辭通曙聽，明日度藍關。"]', '["瀉月声不斷，坐来心益闲。","無人知落处，万木冷空山。","远憶云容外，幽疑石縫间。","那辞通曙听，明日度藍关。"]', '诗', 'shi', '', NULL, '商山夜聞泉 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f33a2ef-e183-405b-ba8a-957fba2cae6a', '書懷', '书懷', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["默默守吾道，望榮來替愁。","吟詩應有罪，當路却如讐。","陸海儻難溺，九霄爭便休。","敢言名譽出，天未白吾頭。"]', '["默默守吾道，望榮来替愁。","吟诗應有罪，當路却如讐。","陸海儻难溺，九霄爭便休。","敢言名譽出，天未白吾头。"]', '诗', 'shi', '', NULL, '書懷 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cae27d-747e-4e81-9087-ab66bf4e369e', '道中', '道中', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["出門嗟世路，何日樸風歸。","是處太行險，□□應解飛。","主人厚薄禮，客子新故衣。","所以澆浮態，多令行者違。"]', '["出门嗟世路，何日樸风归。","是处太行險，□□應解飞。","主人厚薄禮，客子新故衣。","所以澆浮態，多令行者違。"]', '诗', 'shi', '', NULL, '道中 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a007048-dfed-40c8-920d-886f2e978b9f', '夏雲', '夏云', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["勢能成岳仞，頃刻長崔嵬。","瞑鳥飛不到，野風吹得開。","一天分萬態，立地看忘回。","欲結暑宵雨，先聞江上雷。"]', '["勢能成岳仞，頃刻长崔嵬。","瞑鸟飞不到，野风吹得开。","一天分万態，立地看忘回。","欲結暑宵雨，先闻江上雷。"]', '诗', 'shi', '', NULL, '夏雲 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1c0647-10d7-48b0-a4a4-bd88242b0354', '塞上行', '塞上行', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["上將擁黃鬚，安西逐指呼。","離鄉俱少壯，到磧減肌膚。","風雪夜防塞，腥羶朝繫胡。","爲君樂戰死，誰喜作征夫。"]', '["上將擁黄鬚，安西逐指呼。","離乡俱少壯，到磧減肌膚。","风雪夜防塞，腥羶朝繫胡。","爲君乐戰死，誰喜作征夫。"]', '诗', 'shi', '', NULL, '塞上行 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37de8672-2d8c-47da-b724-7370f6380c8b', '晨起', '晨起', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["曉色教不睡，卷簾清氣中。","林殘數枝月，髮冷一梳風。","竝鳥含鐘語，欹荷隔霧空。","莫疑營白日，道路本無窮。"]', '["晓色教不睡，卷簾清氣中。","林殘數枝月，髮冷一梳风。","竝鸟含鐘語，欹荷隔霧空。","莫疑營白日，道路本無窮。"]', '诗', 'shi', '', NULL, '晨起 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9de589-d088-4345-a5d0-b10232a14ecf', '感世', '感世', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["觸目盡如幻，幻中能幾時。","愁來捨行樂，事去莫吞悲。","白髮不由己，黃金留待誰。","耕煙得銘誌，翻爲古人思。"]', '["觸目尽如幻，幻中能幾时。","愁来捨行乐，事去莫吞悲。","白髮不由己，黄金留待誰。","耕煙得銘誌，翻爲古人思。"]', '诗', 'shi', '', NULL, '感世 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93935c72-328b-40e8-a1e1-1ca0359cf040', '觀華夷圖', '观华夷圖', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["落筆勝縮地，展圖當晏寧。","中華屬貴分，遠裔占何星。","分寸辨諸岳，斗升觀四溟。","長疑未到處，一一似曾經。"]', '["落笔勝縮地，展圖當晏寧。","中华屬貴分，远裔占何星。","分寸辨諸岳，斗升观四溟。","长疑未到处，一一似曾經。"]', '诗', 'shi', '', NULL, '觀華夷圖 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08dcdae3-ed35-4cc2-9d88-20c75ed9a219', '山上寒夜呈進士許棠', '山上寒夜呈進士許棠', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["山寒草堂暖，寂夜有良朋。","讀易分高燭，煎茶取折冰。","庭垂河半角，窗露月微稜。","俱入論心地，爭無俗者憎。"]', '["山寒草堂暖，寂夜有良朋。","读易分高燭，煎茶取折冰。","庭垂河半角，窗露月微稜。","俱入論心地，爭無俗者憎。"]', '诗', 'shi', '', NULL, '山上寒夜呈進士許棠 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80661f8b-56df-4243-af49-1cb526e62bad', '滕王閣春日晚眺', '滕王閣春日晚眺', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["凌春帝子閣，偶眺日移西。","浪勢平花塢，帆陰上柳堤。","凝嵐藏宿翼，疊鼓碎歸蹄。","只此長吟詠，因高思不迷。"]', '["凌春帝子閣，偶眺日移西。","浪勢平花塢，帆陰上柳堤。","凝嵐藏宿翼，叠鼓碎归蹄。","只此长吟詠，因高思不迷。"]', '诗', 'shi', '', NULL, '滕王閣春日晚眺 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9376a3-4b2e-48bf-82af-21c4e6f0faf3', '鍾陵野步', '鍾陵野步', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["岡扉聊自啓，信步出波邊。","野火風吹闊，春冰鶴啄穿。","渚檣齊驛樹，山鳥入公田。","未創孤雲勢，空思白閣年。"]', '["岡扉聊自啓，信步出波邊。","野火风吹闊，春冰鹤啄穿。","渚檣齊驛樹，山鸟入公田。","未創孤云勢，空思白閣年。"]', '诗', 'shi', '', NULL, '鍾陵野步 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('393346d5-2332-4d13-82f6-09fcaf1798f2', '哭胡處士', '哭胡处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["故人江閣在，重到事悠悠。","無爾向潭上，爲吾傾甕頭。","空餘赤楓葉，墮落釣魚舟。","疑是沖虛去，不爲天地囚。"]', '["故人江閣在，重到事悠悠。","無爾向潭上，爲吾傾甕头。","空餘赤楓葉，墮落釣鱼舟。","疑是沖虛去，不爲天地囚。"]', '诗', 'shi', '', NULL, '哭胡處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb52dc6-8ed8-4ee2-bfd7-4ba4313c1688', '青龍寺贈雲顥法師', '青龙寺贈云顥法師', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["紫檀衣且香，春殿日尤長。","此地開新講，何山鏁舊房。","僧名喧北闕，師印續南方。","莫惜青蓮喻，秦人聽未忘。"]', '["紫檀衣且香，春殿日尤长。","此地开新講，何山鏁旧房。","僧名喧北闕，師印續南方。","莫惜青蓮喻，秦人听未忘。"]', '诗', 'shi', '', NULL, '青龍寺贈雲顥法師 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55717c36-2293-4f85-84e4-e0d4bd50f27a', '薦福寺贈應制白公', '薦福寺贈應制白公', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["才子紫檀衣，明君寵顧時。","講昇高座懶，書荅重臣遲。","瓶勢傾圓頂，刀聲落碎髭。","還聞穿內去，隨駕進新詩。"]', '["才子紫檀衣，明君寵顧时。","講昇高座懶，书荅重臣遲。","瓶勢傾圓頂，刀声落碎髭。","還闻穿內去，隨駕進新诗。"]', '诗', 'shi', '', NULL, '薦福寺贈應制白公 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b460e5-29d2-4439-ac07-cd35622d53cb', '觀山寺僧穿井', '观山寺僧穿井', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["雲僧鑿山井，寒碧在中庭。","況是分嵓眼，同來下石瓶。","旁痕終變蘚，圓影即澄星。","異夜天龍蟄，應聞說葉經。"]', '["云僧鑿山井，寒碧在中庭。","況是分嵓眼，同来下石瓶。","旁痕終变蘚，圓影即澄星。","異夜天龙蟄，應闻说葉經。"]', '诗', 'shi', '', NULL, '觀山寺僧穿井 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97f378f3-b451-45e9-ac96-ab1a8c7d2ac3', '送德光禪師', '送德光禪師', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["天涯緣事了，又造石霜微。","不以千峰險，唯將獨影歸。","有爲嫌假佛，無境是真機。","到後流沙錫，何時更有飛。"]', '["天涯緣事了，又造石霜微。","不以千峰險，唯將独影归。","有爲嫌假佛，無境是真機。","到後流沙錫，何时更有飞。"]', '诗', 'shi', '', NULL, '送德光禪師 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b83eff-5da9-4a0f-b98b-a2944af5bffb', '贈南陵李主簿', '贈南陵李主簿', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["外邑官同隱，寧勞短吏趨。","看雲情自足，愛酒逸應無。","簟席彈碁子，衣裳惹印朱。","仍聞陂水近，亦擬掉菰蒲。"]', '["外邑官同隐，寧勞短吏趨。","看云情自足，愛酒逸應無。","簟席彈碁子，衣裳惹印朱。","仍闻陂水近，亦擬掉菰蒲。"]', '诗', 'shi', '', NULL, '贈南陵李主簿 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97569e1c-7bac-4799-a644-b84a7662e152', '慈恩寺東樓', '慈恩寺东楼', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["寺樓涼出竹，非與曲江賒。","野火流穿苑，秦山疊入巴。","風梢離衆葉，岸角積虛沙。","此地鐘聲近，令人思未涯。"]', '["寺楼涼出竹，非與曲江賒。","野火流穿苑，秦山叠入巴。","风梢離衆葉，岸角積虛沙。","此地鐘声近，令人思未涯。"]', '诗', 'shi', '', NULL, '慈恩寺東樓 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe8d8b73-ef57-40b4-8133-59517170ad6a', '古塚', '古塚', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["代遠已難問，纍纍次古城。","民田侵不盡，客路踏還平。","作穴蛇分蟄，依岡鹿繞行。","唯應風雨夕，鬼火出林明。"]', '["代远已难问，纍纍次古城。","民田侵不尽，客路踏還平。","作穴蛇分蟄，依岡鹿繞行。","唯應风雨夕，鬼火出林明。"]', '诗', 'shi', '', NULL, '古塚 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8919038-49ac-45eb-8fba-e2313a2b375d', '訪山友', '訪山友', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["一逕通高屋，重雲翳兩原。","山寒初宿頂，泉落未知根。","急雨洗荒壁，驚風開靜門。","聽君吟廢夜，苦却建溪猿。"]', '["一逕通高屋，重云翳兩原。","山寒初宿頂，泉落未知根。","急雨洗荒壁，驚风开静门。","听君吟廢夜，苦却建溪猿。"]', '诗', 'shi', '', NULL, '訪山友 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbbbd13-6d29-4128-952c-96d45e353fc8', '林下書懷寄建州李頻員外', '林下书懷寄建州李頻員外', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["一從諸事嬾，海上跡宜沉。","吾道不當路，鄙人甘入林。","雲垂方覓鶴，月濕始收琴。","水石南州好，誰陪刻骨吟。"]', '["一從諸事嬾，海上跡宜沉。","吾道不當路，鄙人甘入林。","云垂方覓鹤，月濕始收琴。","水石南州好，誰陪刻骨吟。"]', '诗', 'shi', '', NULL, '林下書懷寄建州李頻員外 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf5fdd1-ff56-4375-b5c9-9ddb33684b1c', '猿', '猿', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["曾宿三巴路，今來不願聽。","雲根啼片白，峰頂擲尖青。","護果憎禽啄，栖霜覷葉零。","唯應臥嵐客，憐爾傍嵒扃。"]', '["曾宿三巴路，今来不願听。","云根啼片白，峰頂擲尖青。","護果憎禽啄，栖霜覷葉零。","唯應臥嵐客，怜爾傍嵒扃。"]', '诗', 'shi', '', NULL, '猿 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e77c0a3-b739-43dd-9417-08fa13f52370', '秋日送方干遊上元', '秋日送方干游上元', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["天高淮泗白，料子趨修程。","汲水疑山動，揚帆覺岸行。","雲離京口樹，鴈入石頭城。","後夜分遙念，諸峰霜露生。"]', '["天高淮泗白，料子趨修程。","汲水疑山动，揚帆覺岸行。","云離京口樹，鴈入石头城。","後夜分遙念，諸峰霜露生。"]', '诗', 'shi', '', NULL, '秋日送方干遊上元 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b2e5e4-d3ba-4f01-a69f-ccda3d6d3b89', '哭李頻員外', '哭李頻員外', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["出麾臨建水，下世在公堂。","苦集休開篋，清資罷轉郎。","瘴中無子奠，嶺外一妻孀。","定是浮香骨，東歸就故鄉。"]', '["出麾臨建水，下世在公堂。","苦集休开篋，清資罷轉郎。","瘴中無子奠，嶺外一妻孀。","定是浮香骨，东归就故乡。"]', '诗', 'shi', '', NULL, '哭李頻員外 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c8b7df-b2f8-4e6c-b1c4-af0d7a7f57ed', '山中言事', '山中言事', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["嵐靄潤窗櫺，吟詩得冷癥。","教餐有效藥，多媿獨行僧。","雲濕煎茶火，冰封汲井繩。","片扉深著掩，經國自無能。"]', '["嵐靄潤窗櫺，吟诗得冷癥。","教餐有效藥，多媿独行僧。","云濕煎茶火，冰封汲井繩。","片扉深著掩，經国自無能。"]', '诗', 'shi', '', NULL, '山中言事 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97921cdd-7120-4631-939b-afb9bbdb0533', '送左協律京西從事', '送左協律京西從事', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["辟書來幾日，遂喜就嘉招。","猶向風沙淺，非於甸服遙。","時平無探騎，秋靜見盤雕。","若遣關中使，煩君問寂寥。"]', '["辟书来幾日，遂喜就嘉招。","猶向风沙淺，非於甸服遙。","时平無探騎，秋静见盤雕。","若遣关中使，煩君问寂寥。"]', '诗', 'shi', '', NULL, '送左協律京西從事 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d37f93-9193-4958-b422-d1261ed999c2', '望九華寄池陽太守', '望九华寄池陽太守', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["造化峰峰異，宜教岳德謙。","靈蹤載籍古，怪刃刺雲尖。","盤蹙陵陽壯，孤標建鄴瞻。","霽餘堪洗目，青出謝家簷。"]', '["造化峰峰異，宜教岳德謙。","靈蹤載籍古，怪刃刺云尖。","盤蹙陵陽壯，孤標建鄴瞻。","霽餘堪洗目，青出謝家簷。"]', '诗', 'shi', '', NULL, '望九華寄池陽太守 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2012d85-9666-4dbb-82ee-226b91edeb41', '上廣州支使王拾遺', '上廣州支使王拾遺', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["明時應不諫，天幕稱仙才。","聘入關中去，人從帝側來。","詩窗盛島嶼，檄盾照風雷。","幾度陪旄節，營巡海色迴。"]', '["明时應不諫，天幕稱仙才。","聘入关中去，人從帝側来。","诗窗盛島嶼，檄盾照风雷。","幾度陪旄節，營巡海色迴。"]', '诗', 'shi', '', NULL, '上廣州支使王拾遺 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a19895-989b-4734-ae7e-80874480b22d', '題僧松禪', '題僧松禪', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["空山澗畔枯松樹，禪老堂頭甲乙身。","傳是昔朝僧種著，下頭應有茯苓神。"]', '["空山澗畔枯松樹，禪老堂头甲乙身。","傳是昔朝僧種著，下头應有茯苓神。"]', '诗', 'shi', '', NULL, '題僧松禪 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55600dcb-b3c1-4590-97fa-59fa121fd056', '贈華陰李明府', '贈华陰李明府', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["佩墨縣兼清，約關西近城。","三峰豈不重，厚地戴猶輕。","雪篠欹難直，風泉噴易橫。","須知高枕外，長是勸民耕。"]', '["佩墨縣兼清，約关西近城。","三峰豈不重，厚地戴猶轻。","雪篠欹难直，风泉噴易橫。","須知高枕外，长是勸民耕。"]', '诗', 'shi', '', NULL, '贈華陰李明府 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc0eefb-b9a8-47a0-a95c-7be6a3b2d5cc', '送人庭鶴', '送人庭鹤', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["度歲休籠閉，身輕好羽儀。","白雲□是伴，滄海得因誰。","唳起遺殘食，盤餘在逈枝。","條風頻雨去，只恐更相隨。"]', '["度歲休籠閉，身轻好羽儀。","白云□是伴，滄海得因誰。","唳起遺殘食，盤餘在逈枝。","條风頻雨去，只恐更相隨。"]', '诗', 'shi', '', NULL, '送人庭鶴 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10115706-fe66-4c99-bc40-38af61f41da2', '信州聞通寺題僧砌下泉', '信州闻通寺題僧砌下泉', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["細聲從嶠足，幽淡浸香墀。","此境未開日，何人初見時。","耗痕延黑蘚，淨罅吐微澌。","應有喬梢鶴，下來當飲之。"]', '["細声從嶠足，幽淡浸香墀。","此境未开日，何人初见时。","耗痕延黑蘚，淨罅吐微澌。","應有喬梢鹤，下来當饮之。"]', '诗', 'shi', '', NULL, '信州聞通寺題僧砌下泉 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f886e768-fe15-439c-b0fc-a92ae1aacfc2', '山中', '山中', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["此地似商嶺，雲霞空往還。","衰條難定鳥，缺月易依山。","野色耕不盡，溪容釣自閑。","分因多臥退，百計少相關。"]', '["此地似商嶺，云霞空往還。","衰條难定鸟，缺月易依山。","野色耕不尽，溪容釣自闲。","分因多臥退，百計少相关。"]', '诗', 'shi', '', NULL, '山中 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b8ff01-829b-4c21-9259-1490faa3ff09', '寄崇聖寺僧', '寄崇聖寺僧', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["不醉長安酒，冥心只似師。","望山吟過日，伴鶴立多時。","溝遠流聲細，林寒綠色遲。","菴西蘿月夕，重約語空期。"]', '["不醉长安酒，冥心只似師。","望山吟過日，伴鹤立多时。","溝远流声細，林寒綠色遲。","菴西蘿月夕，重約語空期。"]', '诗', 'shi', '', NULL, '寄崇聖寺僧 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e06eb027-c492-48ef-a60d-31a52ca2ac24', '金陵道中寄', '金陵道中寄', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["忍苦待知音，無時省廢吟。","始爲分路客，莫問向隅心。","嶠翠藏幽瀑，枝風下曉禽。","憶君秋欲盡，馬上秣陵砧。"]', '["忍苦待知音，無时省廢吟。","始爲分路客，莫问向隅心。","嶠翠藏幽瀑，枝风下晓禽。","憶君秋欲尽，马上秣陵砧。"]', '诗', 'shi', '', NULL, '金陵道中寄 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1846657b-f3c8-468b-bbd1-7cecc99e852f', '都門送許棠東歸', '都门送許棠东归', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["舊客東歸遠，長安詩少朋。","去愁分磧鴈，行計逐鄉僧。","華岳無時雪，黃河漫處冰。","知辭國門路，片席認西陵。"]', '["旧客东归远，长安诗少朋。","去愁分磧鴈，行計逐乡僧。","华岳無时雪，黄河漫处冰。","知辞国门路，片席認西陵。"]', '诗', 'shi', '', NULL, '都門送許棠東歸 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('296599ef-2153-41b5-9935-7ec87711e0d1', '送進士喻坦之遊太原', '送進士喻坦之游太原', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["北鄙征難盡，詩愁滿去程。","廢巢侵燒色，荒塚入鋤聲。","逗野河流濁，離雲磧日明。","幷州戎壘地，角動引風生。"]', '["北鄙征难尽，诗愁满去程。","廢巢侵燒色，荒塚入鋤声。","逗野河流濁，離云磧日明。","幷州戎壘地，角动引风生。"]', '诗', 'shi', '', NULL, '送進士喻坦之遊太原 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01be89cd-516b-4fb0-a4ba-4a6af88d2c66', '九江暮春書事', '九江暮春书事', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["楊柳城初鏁，輪蹄息去蹤。","春流無舊岸，夜色失諸峰。","影動漁邊火，聲遲話後鐘。","明朝廻去鴈，誰向北郊逢。"]', '["楊柳城初鏁，輪蹄息去蹤。","春流無旧岸，夜色失諸峰。","影动漁邊火，声遲話後鐘。","明朝廻去鴈，誰向北郊逢。"]', '诗', 'shi', '', NULL, '九江暮春書事 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf601b26-e0ba-4acd-bda4-d6b786631b43', '再到洪州望西山', '再到洪州望西山', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["洪州向西顧，不忍暫忘君。","記得瀑泉落，省同幽鳥聞。","一廻經雨雹，長有剩風雲。","未定却栖息，前頭江海分。"]', '["洪州向西顧，不忍暫忘君。","記得瀑泉落，省同幽鸟闻。","一廻經雨雹，长有剩风云。","未定却栖息，前头江海分。"]', '诗', 'shi', '', NULL, '再到洪州望西山 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('725fe5df-06bf-467d-9db2-1b37c9ec7130', '與胡汾坐月期貫休上人不至', '與胡汾坐月期貫休上人不至', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["掃庭秋漏滴，接話貴忘眠。","靜夜人相語，低枝鳥暗遷。","星圍南極定，月照斷河連。","後會花宮子，應開石上禪。"]', '["掃庭秋漏滴，接話貴忘眠。","静夜人相語，低枝鸟暗遷。","星圍南極定，月照斷河連。","後會花宮子，應开石上禪。"]', '诗', 'shi', '', NULL, '與胡汾坐月期貫休上人不至 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550ac225-1211-41b3-aafc-7b60bcf9303a', '贈胡處士', '贈胡处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["年光離岳色，帶疾臥南原。","白日與無事，俗人嗔閉門。","樵魚臨片水，野鹿入荒園。","莫問榮華事，清霜點髮根。"]', '["年光離岳色，带疾臥南原。","白日與無事，俗人嗔閉门。","樵鱼臨片水，野鹿入荒园。","莫问榮华事，清霜点髮根。"]', '诗', 'shi', '', NULL, '贈胡處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3bb9f9e-afcd-494f-acfd-d97741107ae2', '鉛山寫懷', '鉛山寫懷', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["天涯兵火後，風景畏臨門。","骨肉到時節，團圓因夢魂。","池塘營水眼，嶺嶠結花根。","耳縱聽歌吹，中心不可論。"]', '["天涯兵火後，风景畏臨门。","骨肉到时節，團圓因梦魂。","池塘營水眼，嶺嶠結花根。","耳縱听歌吹，中心不可論。"]', '诗', 'shi', '', NULL, '鉛山寫懷 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db7feb9c-1557-4c6c-ad74-3200eb898387', '書翠巖寺壁', '书翠巖寺壁', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["何年話尊宿，瞻禮此堂中。","入郭非無路，歸林自學空。","濺瓶雲嶠水，逆磬雪川風。","時說南廬事，知師用意同。"]', '["何年話尊宿，瞻禮此堂中。","入郭非無路，归林自学空。","濺瓶云嶠水，逆磬雪川风。","时说南廬事，知師用意同。"]', '诗', 'shi', '', NULL, '書翠巖寺壁 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('962d8cdd-c257-404e-90f9-fca1c605d3f6', '江西題東湖', '江西題东湖', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["鑿出江湖思，涼多□□間。","無風觸微浪，半日□秋山。","客袖沙光滿，船窗荻影閑。","時人見黃綬，應笑狎鷗還。"]', '["鑿出江湖思，涼多□□间。","無风觸微浪，半日□秋山。","客袖沙光满，船窗荻影闲。","时人见黄綬，應笑狎鷗還。"]', '诗', 'shi', '', NULL, '江西題東湖 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c8f8fb5-bd7c-4570-a04e-572d14b7b615', '題湖南岳麓寺', '題湖南岳麓寺', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["海雲山上寺，每到每開襟。","萬木長不住，細泉聽更深。","蜩沾高雨斷，鳥遇夕嵐沈。","此地良宵月，秋懷隔楚砧。"]', '["海云山上寺，每到每开襟。","万木长不住，細泉听更深。","蜩沾高雨斷，鸟遇夕嵐沈。","此地良宵月，秋懷隔楚砧。"]', '诗', 'shi', '', NULL, '題湖南岳麓寺 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e7f8af-e26e-492f-882b-6d2c66c9b006', '贈衡山麋明府', '贈衡山麋明府', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["爲縣瀟湘水，門前樹配苔。","晚吟公籍少，春醉積林開。","滌硯松香起，擎茶岳影來。","任官當此境，更莫夢天台。"]', '["爲縣瀟湘水，门前樹配苔。","晚吟公籍少，春醉積林开。","滌硯松香起，擎茶岳影来。","任官當此境，更莫梦天台。"]', '诗', 'shi', '', NULL, '贈衡山麋明府 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd11f011-f6e5-4e30-b06e-6e9f5222675b', '塞上', '塞上', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["邊寒來所闊，今日復明朝。","河凌堅通馬，胡雲缺見雕。","砂中程獨泣，鄉外隱誰招。","廻首若經歲，靈州生柳條。"]', '["邊寒来所闊，今日复明朝。","河凌堅通马，胡云缺见雕。","砂中程独泣，乡外隐誰招。","廻首若經歲，靈州生柳條。"]', '诗', 'shi', '', NULL, '塞上 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6772e8e6-24c8-438e-86d5-e670bee44602', '送邵安石及第歸連州覲省', '送邵安石及第归連州覲省', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["及第兼歸覲，宜忘涉驛勞。","青雲重慶少，白日一飛高。","轉楚聞啼狖，臨湘見疊濤。","海陽沈飲罷，何地佐旌旄。"]', '["及第兼归覲，宜忘涉驛勞。","青云重慶少，白日一飞高。","轉楚闻啼狖，臨湘见叠濤。","海陽沈饮罷，何地佐旌旄。"]', '诗', 'shi', '', NULL, '送邵安石及第歸連州覲省 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33de29ff-0129-4ff6-a175-529713d046c0', '邊上送友人歸寧', '邊上送友人归寧', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["鄉路穿京過，寧心去少同。","日斜尋闊磧，春盡逐歸鴻。","獨樹河聲外，凝笳塞色中。","憐君到此處，却背老萊風。"]', '["乡路穿京過，寧心去少同。","日斜尋闊磧，春尽逐归鴻。","独樹河声外，凝笳塞色中。","怜君到此处，却背老萊风。"]', '诗', 'shi', '', NULL, '邊上送友人歸寧 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13271d26-4e05-4c92-9081-fc65dea31af2', '除夜', '除夜', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["殘臘即又盡，東風應漸聞。","一宵猶幾許，兩歲欲平分。","燎暗傾時斗，春通綻處芬。","明朝遙捧酒，先合祝堯君。"]', '["殘臘即又尽，东风應漸闻。","一宵猶幾許，兩歲欲平分。","燎暗傾时斗，春通綻处芬。","明朝遙捧酒，先合祝堯君。"]', '诗', 'shi', '', NULL, '除夜 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf35e867-fc2c-4bee-9587-c0e55c19a102', '題甘露寺', '題甘露寺', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["香門接巨壘，畫角間清鐘。","北固一何峭，西僧多此逢。","天垂無際海，雲白久晴峰。","旦暮然燈外，濤頭振蟄龍。"]', '["香门接巨壘，畫角间清鐘。","北固一何峭，西僧多此逢。","天垂無際海，云白久晴峰。","旦暮然灯外，濤头振蟄龙。"]', '诗', 'shi', '', NULL, '題甘露寺 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bffe88b3-c216-4a63-b137-87b8afe3abd4', '貽住山僧', '貽住山僧', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["罷講巡巖塢，無窮得野情。","臘高猶伴鹿，夏滿不歸城。","雲朵緣崖發，峰陰截水清。","自然雙洗耳，唯任白毫生。"]', '["罷講巡巖塢，無窮得野情。","臘高猶伴鹿，夏满不归城。","云朵緣崖發，峰陰截水清。","自然雙洗耳，唯任白毫生。"]', '诗', 'shi', '', NULL, '貽住山僧 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780c912d-bd36-4ad3-8df3-ae32333781ad', '題鶴鳴泉', '題鹤鳴泉', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["仙鶴曾鳴處，泉兼半井苔。","直峰拋影入，片月瀉光來。","瀲灩侵顏冷，深沉慰眼開。","何因值舟頂，滿汲石瓶廻。"]', '["仙鹤曾鳴处，泉兼半井苔。","直峰拋影入，片月瀉光来。","瀲灩侵顏冷，深沉慰眼开。","何因值舟頂，满汲石瓶廻。"]', '诗', 'shi', '', NULL, '題鶴鳴泉 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc522fa-ef96-4126-a6f8-d6a2447f22e4', '吊賈島二首 一', '吊賈島二首 一', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["先生不折桂，謫去抱何冤。","已葬離燕骨，難招入劒魂。","旅墳低却草，稚子哭勝猿。","冥寞如搜句，宜邀賀監論。"]', '["先生不折桂，謫去抱何冤。","已葬離燕骨，难招入劒魂。","旅墳低却草，稚子哭勝猿。","冥寞如搜句，宜邀賀監論。"]', '诗', 'shi', '', NULL, '吊賈島二首 一 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd75d9b9-3cbb-4ae5-8d24-297b9ce2475f', '吊賈島二首 二', '吊賈島二首 二', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["青斾低寒水，清笳出曉風。","鳥來傷賈傅，馬立葬滕公。","松柏青山上，城池白日中。","一朝今古隔，惟有月明同。"]', '["青斾低寒水，清笳出晓风。","鸟来傷賈傅，马立葬滕公。","松柏青山上，城池白日中。","一朝今古隔，惟有月明同。"]', '诗', 'shi', '', NULL, '吊賈島二首 二 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff2789f2-da3b-47e1-803b-a1f9840a5516', '憶江西幷悼亡友', '憶江西幷悼亡友', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["前心奈兵阻，悔作豫章分。","芳草未歸日，故人多是墳。","帆行出岫雨，馬踐過江雲。","此地一罇酒，當時皆以文。"]', '["前心奈兵阻，悔作豫章分。","芳草未归日，故人多是墳。","帆行出岫雨，马踐過江云。","此地一罇酒，當时皆以文。"]', '诗', 'shi', '', NULL, '憶江西幷悼亡友 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4186eec5-32e2-40c7-bf47-e1d5b43d06c1', '九江送方干歸鏡湖', '九江送方干归镜湖', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["一檣懸五兩，此日動歸風。","客路拋湓口，家林入鏡中。","譚餘雲出嶠，詠苦月欹空。","更若看鳷鵲，何人夜坐同。"]', '["一檣懸五兩，此日动归风。","客路拋湓口，家林入镜中。","譚餘云出嶠，詠苦月欹空。","更若看鳷鵲，何人夜坐同。"]', '诗', 'shi', '', NULL, '九江送方干歸鏡湖 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9ffd27-0274-40de-8b93-8f3ccaf5b3f4', '廬山訪賈匡', '廬山訪賈匡', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["西城疾病日，此地少尋君。","古跡春猶在，遙泉夜盡聞。","片時三處雨，九疊幾重雲。","到者皆忘寐，神精與俗分。"]', '["西城疾病日，此地少尋君。","古跡春猶在，遙泉夜尽闻。","片时三处雨，九叠幾重云。","到者皆忘寐，神精與俗分。"]', '诗', 'shi', '', NULL, '廬山訪賈匡 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292ee42d-4b82-45b7-9b1a-c9abd0b7d389', '顧少府池上', '顧少府池上', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["池上分行種，公庭覺少塵。","根離潮水岸，韻爽判曹人。","正午廻魚影，方昏息鷺身。","無時不動詠，滄島思方頻。"]', '["池上分行種，公庭覺少塵。","根離潮水岸，韻爽判曹人。","正午廻鱼影，方昏息鷺身。","無时不动詠，滄島思方頻。"]', '诗', 'shi', '', NULL, '顧少府池上 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34fa182b-b19e-4847-b527-d42949e34b24', '喜友人歸上元別業', '喜友人归上元別業', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["一檣千里外，隱者興宜孤。","落日長邊海，秋風滿故都。","掩關苔色老，盤逕葉聲枯。","匡岳來時過，遲廻絕頂無。"]', '["一檣千里外，隐者兴宜孤。","落日长邊海，秋风满故都。","掩关苔色老，盤逕葉声枯。","匡岳来时過，遲廻絕頂無。"]', '诗', 'shi', '', NULL, '喜友人歸上元別業 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be69b7d-175e-44f0-bd5a-7f1fe621029d', '曲江暮春雪霽', '曲江暮春雪霽', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["霽動江池色，春殘一去游。","菰風生馬足，槐雪滴人頭。","北闕塵未起，南山青欲流。","如何多別地，却得醉汀洲。"]', '["霽动江池色，春殘一去游。","菰风生马足，槐雪滴人头。","北闕塵未起，南山青欲流。","如何多別地，却得醉汀洲。"]', '诗', 'shi', '', NULL, '曲江暮春雪霽 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7545c49-8015-4658-a29a-24c21e35a15b', '立春日', '立春日', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["春飲一杯酒，便吟春日詩。","木梢寒未覺，地脉暖先知。","鳥囀星沈後，山分雪薄時。","賞心無處說，悵望曲江池。"]', '["春饮一杯酒，便吟春日诗。","木梢寒未覺，地脉暖先知。","鸟囀星沈後，山分雪薄时。","賞心無处说，悵望曲江池。"]', '诗', 'shi', '', NULL, '立春日 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aacd7716-148f-4c14-a986-d5f80b59806d', '宿溪僧院', '宿溪僧院', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["少年雲溪裏，禪心夜更閑。","煎茶留靜者，靠月坐蒼山。","露白鐘尋定，螢多戶未關。","嵩陽大石室，何日譯經還。"]', '["少年云溪裏，禪心夜更闲。","煎茶留静者，靠月坐蒼山。","露白鐘尋定，螢多戶未关。","嵩陽大石室，何日譯經還。"]', '诗', 'shi', '', NULL, '宿溪僧院 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc793e3-a62f-4f09-ad26-aaac9155b867', '石頭懷古', '石头懷古', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["日月出又沒，臺城空白雲。","雖寬百姓土，漸缺六朝墳。","禾黍是亡國，山河歸聖君。","松聲驟雨足，幾寺晚鐘聞。"]', '["日月出又沒，台城空白云。","雖寬百姓土，漸缺六朝墳。","禾黍是亡国，山河归聖君。","松声驟雨足，幾寺晚鐘闻。"]', '诗', 'shi', '', NULL, '石頭懷古 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e250b1-36a6-4409-bbc4-d1f972174fd6', '浙右贈陸處士', '浙右贈陸处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["靜節灌園餘，得非成隱居。","長當庚子日，獨拜五經書。","白浪吹亡國，秋霜洗大虛。","門前是京口，身外不營儲。"]', '["静節灌园餘，得非成隐居。","长當庚子日，独拜五經书。","白浪吹亡国，秋霜洗大虛。","门前是京口，身外不營儲。"]', '诗', 'shi', '', NULL, '浙右贈陸處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('814e7769-7855-4fbe-87a9-ad85e3f78933', '哭胡處士', '哭胡处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["丘中久不起，將謂詔書來。","及見凌雲說，方知掩夜臺。","白衣歸北路，玄造亦遺才。","世上亡君後，詩聲更大哉。"]', '["丘中久不起，將謂詔书来。","及见凌云说，方知掩夜台。","白衣归北路，玄造亦遺才。","世上亡君後，诗声更大哉。"]', '诗', 'shi', '', NULL, '哭胡處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0eb8238-13ab-4dce-9ade-9fdc54d7da4e', '贈餘干袁明府', '贈餘干袁明府', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["一雨西城色，陶家心自清。","山銜中郭分，雲卷下湖程。","公署聞流木，人煙入廢城。","難忘楚盡處，新有越吟生。"]', '["一雨西城色，陶家心自清。","山銜中郭分，云卷下湖程。","公署闻流木，人煙入廢城。","难忘楚尽处，新有越吟生。"]', '诗', 'shi', '', NULL, '贈餘干袁明府 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f8767f-121a-4b06-a6e3-1c2ec9872e93', '贈雷鄉張明府', '贈雷乡張明府', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["任官征戰後，度日寄閑身。","封卷還高客，飛書問野人。","廢田教種糓，生路遣尋薪。","若起柴桑興，無先漉酒巾。"]', '["任官征戰後，度日寄闲身。","封卷還高客，飞书问野人。","廢田教種糓，生路遣尋薪。","若起柴桑兴，無先漉酒巾。"]', '诗', 'shi', '', NULL, '贈雷鄉張明府 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bfd7cb-d5b9-4e39-b847-d1fc8302e142', '岳陽晚泊', '岳陽晚泊', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["輕帆下闊流，便泊此沙洲。","湖影撼山朵，日陽燒野愁。","白波爭起倒，青嶼或沈浮。","是際船中望，東南仞仞秋。"]', '["轻帆下闊流，便泊此沙洲。","湖影撼山朵，日陽燒野愁。","白波爭起倒，青嶼或沈浮。","是際船中望，东南仞仞秋。"]', '诗', 'shi', '', NULL, '岳陽晚泊 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e188e47-e2bf-484a-b003-b09270b4e6ff', '覽春牓喜孫鄠成名', '覽春牓喜孫鄠成名', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["門外報春牓，喜君天子知。","舊愁渾似雪，見日總消時。","塔下牡丹氣，江頭楊柳絲。","風光若有分，無處不相宜。"]', '["门外報春牓，喜君天子知。","旧愁渾似雪，见日總消时。","塔下牡丹氣，江头楊柳絲。","风光若有分，無处不相宜。"]', '诗', 'shi', '', NULL, '覽春牓喜孫鄠成名 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f669eb-0f37-456f-abfc-39cd19a2827b', '己亥歲二首 一', '己亥歲二首 一', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["澤國江山入戰圖，生民何計樂樵蘇。","憑君莫話封侯事，一將功成萬骨枯。"]', '["澤国江山入戰圖，生民何計乐樵蘇。","憑君莫話封侯事，一將功成万骨枯。"]', '诗', 'shi', '', NULL, '己亥歲二首 一 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab08f3b-40af-4386-8737-024c2e437746', '己亥歲二首 二', '己亥歲二首 二', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["傳聞一戰百神愁，兩岸彊兵過未休。","誰道滄江總無事，近來長共血爭流。"]', '["傳闻一戰百神愁，兩岸彊兵過未休。","誰道滄江總無事，近来长共血爭流。"]', '诗', 'shi', '', NULL, '己亥歲二首 二 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('440c408d-c86d-4e0c-8526-99eb7c6429d0', '亂後入洪州西山', '亂後入洪州西山', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["寂寂陰溪水漱苔，塵中將得苦吟來。","東峰道士如相問，縣令而今不姓梅。"]', '["寂寂陰溪水漱苔，塵中將得苦吟来。","东峰道士如相问，縣令而今不姓梅。"]', '诗', 'shi', '', NULL, '亂後入洪州西山 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccfc68d-2834-4aae-b4d1-5d6c16d65094', '送僧入廬山', '送僧入廬山', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["若到江州二林寺，遍遊應未出雲霞。","廬山瀑布三千仞，畫破青霄始落斜。"]', '["若到江州二林寺，遍游應未出云霞。","廬山瀑布三千仞，畫破青霄始落斜。"]', '诗', 'shi', '', NULL, '送僧入廬山 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ad4fdb7-78f8-4346-a818-4aece9b30ece', '送僧入蜀過夏', '送僧入蜀過夏', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["師言結夏入巴峰，雲水廻頭幾萬重。","五月峨眉須近火，木皮領重只如冬。"]', '["師言結夏入巴峰，云水廻头幾万重。","五月峨眉須近火，木皮領重只如冬。"]', '诗', 'shi', '', NULL, '送僧入蜀過夏 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16dae25b-9b11-426c-a12a-f6e8f3e92cee', '江西逢僧省文 一', '江西逢僧省文 一', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["閩地高僧楚地逢，僧遊蠻錫挂垂松。","白雲逸性都無定，纔出雙峰愛五峰。"]', '["閩地高僧楚地逢，僧游蠻錫挂垂松。","白云逸性都無定，纔出雙峰愛五峰。"]', '诗', 'shi', '', NULL, '江西逢僧省文 一 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae603c61-4407-42e2-ac48-531173ad84d2', '江西逢僧省文 二', '江西逢僧省文 二', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["高僧不負雪峰期，却伴青霞入翠微。","百葉巖前霜欲降，九枝松上鶴初歸。","風生碧澗魚龍躍，威振金樓燕雀飛。","想得白蓮花上月，滿山猶帶舊光輝。"]', '["高僧不負雪峰期，却伴青霞入翠微。","百葉巖前霜欲降，九枝松上鹤初归。","风生碧澗鱼龙躍，威振金楼燕雀飞。","想得白蓮花上月，满山猶带旧光輝。"]', '诗', 'shi', '', NULL, '江西逢僧省文 二 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f3de8c-3a99-4972-8b4f-5db1e3d842ff', '水精念珠', '水精念珠', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["等量紅縷貫晶熒，盡道勻圓別未勝。","鑿斷玉潭盈尺水，琢成金地兩條冰。","輪時秪恐星侵佛，掛處常疑露滴僧。","幾度夜深尋不著，瑠[瓈]爲殿月爲燈。"]', '["等量紅縷貫晶熒，尽道勻圓別未勝。","鑿斷玉潭盈尺水，琢成金地兩條冰。","輪时秪恐星侵佛，掛处常疑露滴僧。","幾度夜深尋不著，瑠[瓈]爲殿月爲灯。"]', '诗', 'shi', '', NULL, '水精念珠 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b6a68f-07a9-4a33-a026-712d302704ee', '南海旅次', '南海旅次', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["憶歸休上越王臺，歸思臨高不易裁。","爲客正當無鴈處，故園誰道有書來。","城頭早角吹霜盡，郭裏殘潮蕩月回。","心似百花開未得，年年爭發被春催。"]', '["憶归休上越王台，归思臨高不易裁。","爲客正當無鴈处，故园誰道有书来。","城头早角吹霜尽，郭裏殘潮蕩月回。","心似百花开未得，年年爭發被春催。"]', '诗', 'shi', '', NULL, '南海旅次 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76a81f0-8853-4e1e-b053-bcce57a84681', '春草', '春草', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["不獨滿池塘，夢中佳句香。","春風有餘力，引上古城牆。"]', '["不独满池塘，梦中佳句香。","春风有餘力，引上古城牆。"]', '诗', 'shi', '', NULL, '春草 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('507eda7a-f94e-41cc-aefd-e6cbdec7c5a8', '金谷園', '金谷园', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["當年歌舞時，不說草離離。","今日歌舞盡，滿園秋露垂。"]', '["當年歌舞时，不说草離離。","今日歌舞尽，满园秋露垂。"]', '诗', 'shi', '', NULL, '金谷園 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d614385-94d5-4f15-b763-f186f2c39b8f', '夏日東齋', '夏日东斋', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["三庚到秋伏，偶來松檻立。","熱少清風多，開門放山入。"]', '["三庚到秋伏，偶来松檻立。","熱少清风多，开门放山入。"]', '诗', 'shi', '', NULL, '夏日東齋 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2554156a-583a-4ea5-871a-818c402a71f4', '南朝', '南朝', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["三籬蓋馳道，風烈一無取。","時見牧牛童，嗔牛喫禾黍。"]', '["三籬蓋驰道，风烈一無取。","时见牧牛童，嗔牛喫禾黍。"]', '诗', 'shi', '', NULL, '南朝 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b9e3f4-1b46-4ffc-81ef-fe000d21bba1', '言懷', '言懷', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["出山不得意，謁帝值戈鋋。","豈料爲文日，翻成用武年。"]', '["出山不得意，謁帝值戈鋋。","豈料爲文日，翻成用武年。"]', '诗', 'shi', '', NULL, '言懷 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c993f97-ee32-4756-8db7-df0514aa7c5d', '寒食日題杜鵑花', '寒食日題杜鵑花', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["一朵又一朵，併開寒食時。","誰家不禁火，總在此花枝。"]', '["一朵又一朵，併开寒食时。","誰家不禁火，總在此花枝。"]', '诗', 'shi', '', NULL, '寒食日題杜鵑花 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc3cb6b6-1b88-4007-91db-39554026921b', '鍾陵寒食日郊外閑游', '鍾陵寒食日郊外闲游', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["可憐時節足風情，杏子粥香如冷餳。","無奈春風輸舊火，遍教人喚作山櫻。"]', '["可怜时節足风情，杏子粥香如冷餳。","無奈春风輸旧火，遍教人喚作山櫻。"]', '诗', 'shi', '', NULL, '鍾陵寒食日郊外閑游 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90d2bd20-6aa8-4d27-913d-67f63d889d4b', '中秋對月', '中秋对月', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["無雲世界秋三五，共看蟾盤上海涯。","直到天頭天盡處，不曾私照一人家。"]', '["無云世界秋三五，共看蟾盤上海涯。","直到天头天尽处，不曾私照一人家。"]', '诗', 'shi', '', NULL, '中秋對月 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d31544-eddd-49ca-a1ea-a08dff1b37c9', '陪湖南李中丞宴隱溪', '陪湖南李中丞宴隐溪', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["竹林啼鳥不知休，羅列飛橋水亂流。","觸散柳絲回玉勒，約開蓮葉上蘭舟。","酒邊舊侶真何遜，雲裏新聲是莫愁。","若值主人嫌晝短，應陪秉燭夜深遊。"]', '["竹林啼鸟不知休，羅列飞橋水亂流。","觸散柳絲回玉勒，約开蓮葉上蘭舟。","酒邊旧侶真何遜，云裏新声是莫愁。","若值主人嫌晝短，應陪秉燭夜深游。"]', '诗', 'shi', '', NULL, '陪湖南李中丞宴隱溪 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65fad1eb-68f1-4230-9c76-baf6e4e55731', '別湖上主人', '別湖上主人', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["門繫釣舟雲滿岸，借君幽致坐移旬。","湖村夜呌白蕪鴈，菱市曉喧深浦人。","遠水日邊重作雪，寒林燒後別生春。","不辭更住醒還醉，太一東峰歸夢頻。"]', '["门繫釣舟云满岸，借君幽致坐移旬。","湖村夜呌白蕪鴈，菱市晓喧深浦人。","远水日邊重作雪，寒林燒後別生春。","不辞更住醒還醉，太一东峰归梦頻。"]', '诗', 'shi', '', NULL, '別湖上主人 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252223d3-2767-494c-995c-0b4811e69549', '贈廣宣大師', '贈廣宣大師', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["憶昔同游紫閣雲，別來三十二回春。","白頭相見雙林下，猶是清朝未退人。"]', '["憶昔同游紫閣云，別来三十二回春。","白头相见雙林下，猶是清朝未退人。"]', '诗', 'shi', '', NULL, '贈廣宣大師 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11911ea-7387-4848-a102-6c0808b9375d', '鍾陵寒食日與同年裴顏李先輩鄭校書郊外閑游', '鍾陵寒食日與同年裴顏李先輩鄭校书郊外闲游', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["寒節鍾陵香騎隨，同年相命楚江湄。","雲間影過鞦韆女，地上聲喧蹴踘兒。","何處寄烟歸草色，誰家送火在花枝。","銀瓶冷酒皆傾盡，半臥垂楊自不知。"]', '["寒節鍾陵香騎隨，同年相命楚江湄。","云间影過鞦韆女，地上声喧蹴踘兒。","何处寄烟归草色，誰家送火在花枝。","銀瓶冷酒皆傾尽，半臥垂楊自不知。"]', '诗', 'shi', '', NULL, '鍾陵寒食日與同年裴顏李先輩鄭校書郊外閑游 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b9012d-793b-4097-8ae8-e13582efb7bc', '江外除夜', '江外除夜', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["千門庭燎照樓臺，總爲年光急急催。","半夜臘因風卷去，五更春被角吹來。","寧無好鳥思花發，應有遊魚待凍開。","不是多歧漸平穩，誰能呼酒祝昭回。"]', '["千门庭燎照楼台，總爲年光急急催。","半夜臘因风卷去，五更春被角吹来。","寧無好鸟思花發，應有游鱼待凍开。","不是多歧漸平穩，誰能呼酒祝昭回。"]', '诗', 'shi', '', NULL, '江外除夜 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09a4098-9b28-418f-9eb3-4b279576c06f', '七夕', '七夕', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["牛女相期七夕秋，相逢俱喜鵲橫流。","彤雲縹緲廻金輅，明月嬋娟掛玉鉤。","燕羽幾曾添別恨，花容終不更含羞。","更殘便是分襟處，曉箭東來射翠樓。"]', '["牛女相期七夕秋，相逢俱喜鵲橫流。","彤云縹緲廻金輅，明月嬋娟掛玉鉤。","燕羽幾曾添別恨，花容終不更含羞。","更殘便是分襟处，晓箭东来射翠楼。"]', '诗', 'shi', '', NULL, '七夕 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad43450a-e60d-4c45-8329-a5901ea0b063', '羅浮山下書逸人壁', '羅浮山下书逸人壁', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["海上亭臺山下烟，買時幽邃不爭錢。","莫言白日催華髮，自有丹砂駐少年。","漁釣未歸深竹裏，琴壺猶戀落花邊。","可中更踐無人境，知是羅浮第幾天。"]', '["海上亭台山下烟，買时幽邃不爭錢。","莫言白日催华髮，自有丹砂駐少年。","漁釣未归深竹裏，琴壺猶戀落花邊。","可中更踐無人境，知是羅浮第幾天。"]', '诗', 'shi', '', NULL, '羅浮山下書逸人壁 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3381503-fa01-421e-844d-f5001c50b7cc', '天台瀑布', '天台瀑布', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["萬仞得名云瀑布，遠看如織掛天台。","休疑寶尺難量度，直恐金刀易剪裁。","噴向林梢成夏雪，傾來石上作春雷。","欲知便是銀河水，墮落人間合却廻。"]', '["万仞得名云瀑布，远看如织掛天台。","休疑寶尺难量度，直恐金刀易剪裁。","噴向林梢成夏雪，傾来石上作春雷。","欲知便是銀河水，墮落人间合却廻。"]', '诗', 'shi', '', NULL, '天台瀑布 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9002cdd8-2064-4d05-a6e1-3108c767644f', '桂江', '桂江', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["未識佳人尋桂水，水雲先解傍壺觴。","笋林次第添斑竹，雛鳥參差護錦囊。","乳洞此時連越井，石樓何日到僊鄉。","如飛似墮皆青壁，畫手不強元化強。"]', '["未識佳人尋桂水，水云先解傍壺觴。","笋林次第添斑竹，雛鸟參差護錦囊。","乳洞此时連越井，石楼何日到僊乡。","如飞似墮皆青壁，畫手不強元化強。"]', '诗', 'shi', '', NULL, '桂江 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('536de45e-a0e5-45ba-8b5c-a102944c3ef3', '南海', '南海', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["傾騰界漢沃諸蠻，立望何如畫此看。","無地不同方覺遠，共天無別始知寬。","文魮隔霧朝含碧，老蚌凌波夜吐丹。","萬狀千形皆得意，長鯨獨自轉身難。"]', '["傾腾界漢沃諸蠻，立望何如畫此看。","無地不同方覺远，共天無別始知寬。","文魮隔霧朝含碧，老蚌凌波夜吐丹。","万狀千形皆得意，长鯨独自轉身难。"]', '诗', 'shi', '', NULL, '南海 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52aacc69-47b6-499a-94a5-3b66eed1b276', '洞庭湖', '洞庭湖', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["東西南北各連空，波上唯留小朵峰。","長與岳陽翻鼓角，不離雲夢轉魚龍。","吸廻日月過千頃，鋪盡星河剩一重。","直到劫餘還作陸，是時應有羽人逢。"]', '["东西南北各連空，波上唯留小朵峰。","长與岳陽翻鼓角，不離云梦轉鱼龙。","吸廻日月過千頃，鋪尽星河剩一重。","直到劫餘還作陸，是时應有羽人逢。"]', '诗', 'shi', '', NULL, '洞庭湖 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2223b1-f7db-4623-99e0-8b171cb0392c', '霍山', '霍山', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["七千七百七十丈，丈丈藤蘿勢入天。","未必展來空似翅，不妨開去也成蓮。","月將河漢分巖轉，僧與龍蛇共窟眠。","直是畫工須閣筆，況無名畫可流傳。"]', '["七千七百七十丈，丈丈藤蘿勢入天。","未必展来空似翅，不妨开去也成蓮。","月將河漢分巖轉，僧與龙蛇共窟眠。","直是畫工須閣笔，況無名畫可流傳。"]', '诗', 'shi', '', NULL, '霍山 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d15de4-e38a-4449-bd14-86c7b60df075', '巫峽', '巫峽', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["巫山蒼翠峽通津，下有仙宮楚女真。","不逐彩雲歸碧落，却爲暮雨撲行人。","年年舊事音容在，日日誰家夢想頻。","應是荆山留不住，至今猶得覩芳塵。"]', '["巫山蒼翠峽通津，下有仙宮楚女真。","不逐彩云归碧落，却爲暮雨撲行人。","年年旧事音容在，日日誰家梦想頻。","應是荆山留不住，至今猶得覩芳塵。"]', '诗', 'shi', '', NULL, '巫峽 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baf9f108-31d6-40a5-b438-4bedd4d042d8', '送陳樵校書歸泉州', '送陳樵校书归泉州', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["巨塔列名題，詩心亦罕齊。","除官京下闕，乞假海門西。","別席侵殘漏，歸程避戰鼙。","關遙秦鴈斷，家近瘴雲低。","候馬春風館，迎船曉月溪。","帝京須早入，莫被刺桐迷。"]', '["巨塔列名題，诗心亦罕齊。","除官京下闕，乞假海门西。","別席侵殘漏，归程避戰鼙。","关遙秦鴈斷，家近瘴云低。","候马春风館，迎船晓月溪。","帝京須早入，莫被刺桐迷。"]', '诗', 'shi', '', NULL, '送陳樵校書歸泉州 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58e3fe8d-2241-4e07-b8d6-586e4a84820d', '贈鏡湖處士方干二首 一', '贈镜湖处士方干二首 一', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["包含教化剩搜羅，句出東甌奈峭何。","世路不妨平處少，才人唯是屈聲多。","雲來島上便幽石，月到湖心忌白波。","後輩難爲措機杼，先生織字得龍梭。"]', '["包含教化剩搜羅，句出东甌奈峭何。","世路不妨平处少，才人唯是屈声多。","云来島上便幽石，月到湖心忌白波。","後輩难爲措機杼，先生织字得龙梭。"]', '诗', 'shi', '', NULL, '贈鏡湖處士方干二首 一 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b79b3b7-65f4-4447-b261-71104bc2c748', '贈鏡湖處士方干二首 二', '贈镜湖处士方干二首 二', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["秪擬應星眠越絕，唯將麗什當高勳。","磨礱清濁人難會，織絡虛無帝亦聞。","鳥道未知山足雨，漁家已沒鏡中雲。","他時莫爲三徴起，門外沙鷗解笑君。"]', '["秪擬應星眠越絕，唯將丽什當高勳。","磨礱清濁人难會，织絡虛無帝亦闻。","鸟道未知山足雨，漁家已沒镜中云。","他时莫爲三徴起，门外沙鷗解笑君。"]', '诗', 'shi', '', NULL, '贈鏡湖處士方干二首 二 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48507ceb-70ba-4016-a16d-757fca6588f8', '拜訪陸處士', '拜訪陸处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["萬卷書邊人半白，再來惟恐降玄纁。","性靈比鶴爭多少，氣力登山較幾分。","吟鬢漸無前度漆，寢衣猶有昨宵雲。","將知谷口耕烟者，低視齊梁楚趙君。"]', '["万卷书邊人半白，再来惟恐降玄纁。","性靈比鹤爭多少，氣力登山較幾分。","吟鬢漸無前度漆，寢衣猶有昨宵云。","將知谷口耕烟者，低視齊梁楚趙君。"]', '诗', 'shi', '', NULL, '拜訪陸處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5021cd-f042-408b-8dc8-9055635a8b69', '嶺南道中', '嶺南道中', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["百花成實未成歸，未必歸心與志違。","但有壺觴資逸詠，盡交風景入清機。","半川陰霧藏高木，一道晴蜺雜落暉。","遊子馬前芳草合，鷓鴣啼歇又南飛。"]', '["百花成實未成归，未必归心與志違。","但有壺觴資逸詠，尽交风景入清機。","半川陰霧藏高木，一道晴蜺杂落暉。","游子马前芳草合，鷓鴣啼歇又南飞。"]', '诗', 'shi', '', NULL, '嶺南道中 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170982ce-64fe-49ab-8864-3be563f53501', '春日自吳門之陽羨道中書事', '春日自吳门之陽羨道中书事', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["勝異恣遊應未遍，路岐猶去幾時還。","浪花湖闊虹蜺斷，柳線村深鳥雀閑。","千室綺羅浮畫檝，兩州絲竹會茶山。","眼前便是神僊事，何必須言洞府間。"]', '["勝異恣游應未遍，路岐猶去幾时還。","浪花湖闊虹蜺斷，柳線村深鸟雀闲。","千室綺羅浮畫檝，兩州絲竹會茶山。","眼前便是神僊事，何必須言洞府间。"]', '诗', 'shi', '', NULL, '春日自吳門之陽羨道中書事 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73de3c4b-708f-4016-a4d9-e1b5423f8f20', '將入關行次湘陰', '將入关行次湘陰', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["背顧秦城在何處，圖書作伴過湘東。","神鵶亂噪黃陵近，候鴈斜沈夢澤空。","打槳天連晴水白，燒田雲隔夜山紅。","也知漸老巖棲穩，爭奈文闈有至公。"]', '["背顧秦城在何处，圖书作伴過湘东。","神鵶亂噪黄陵近，候鴈斜沈梦澤空。","打槳天連晴水白，燒田云隔夜山紅。","也知漸老巖棲穩，爭奈文闈有至公。"]', '诗', 'shi', '', NULL, '將入關行次湘陰 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be55448-af23-40b4-967f-8429af5ff42a', '題昭州山寺常寂上人水閣', '題昭州山寺常寂上人水閣', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["常寂常居常寂裏，年年月月是空空。","堦前未放巖根斷，屋下長教海眼通。","本爲入來尋佛窟，不期行處踏龍宮。","他時憶著堪圖畫，一朵雲山二水中。"]', '["常寂常居常寂裏，年年月月是空空。","堦前未放巖根斷，屋下长教海眼通。","本爲入来尋佛窟，不期行处踏龙宮。","他时憶著堪圖畫，一朵云山二水中。"]', '诗', 'shi', '', NULL, '題昭州山寺常寂上人水閣 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3350f07b-4161-4507-bcd5-90f107c08feb', '廣州貽匡緒法師', '廣州貽匡緒法師', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["口宣微密不思議，不是除貪即誡癡。","祗待外方緣了日，爭看內殿詔來時。","週廻海樹侵階疾，迢遞江潮應井遲。","必竟懶過高坐寺，未能全讓法雲師。"]', '["口宣微密不思議，不是除貪即誡癡。","祗待外方緣了日，爭看內殿詔来时。","週廻海樹侵階疾，迢遞江潮應井遲。","必竟懶過高坐寺，未能全讓法云師。"]', '诗', 'shi', '', NULL, '廣州貽匡緒法師 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1bed828-6a98-40cf-8348-3bab4960fdaf', '贈道人', '贈道人', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["住山因以福爲庭，便向山中隱姓名。","閬苑駕將雕羽去，洞天贏得綠毛生。","日邊腸胃餐霞火，月裏肌膚飲露英。","顧我從來斷浮濁，擬驅雞犬上三清。"]', '["住山因以福爲庭，便向山中隐姓名。","閬苑駕將雕羽去，洞天贏得綠毛生。","日邊腸胃餐霞火，月裏肌膚饮露英。","顧我從来斷浮濁，擬驱雞犬上三清。"]', '诗', 'shi', '', NULL, '贈道人 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f8982b-2cde-4694-b016-e49ef7f7ad35', '送乞雨禪師臨遇南遊', '送乞雨禪師臨遇南游', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["活得枯樵耕者知，巡方又欲向天涯。","珠穿閩國菩提子，杖把靈峰榔栗枝。","春蘚任封降虎石，夜雷從傍養龍池。","生緣在地南浮去，自此孤雲不可期。"]', '["活得枯樵耕者知，巡方又欲向天涯。","珠穿閩国菩提子，杖把靈峰榔栗枝。","春蘚任封降虎石，夜雷從傍養龙池。","生緣在地南浮去，自此孤云不可期。"]', '诗', 'shi', '', NULL, '送乞雨禪師臨遇南遊 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3b965c-327c-4c51-82d7-a441012584de', '南海陪鄭司空遊荔園', '南海陪鄭司空游荔园', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["荔枝時節出旌斿，南國名園盡興遊。","亂結羅紋照襟袖，別含瓊露爽咽喉。","葉中新火欺寒食，樹上丹砂勝錦州。","他日爲霖不將去，也須圖畫取風流。"]', '["荔枝时節出旌斿，南国名园尽兴游。","亂結羅紋照襟袖，別含瓊露爽咽喉。","葉中新火欺寒食，樹上丹砂勝錦州。","他日爲霖不將去，也須圖畫取风流。"]', '诗', 'shi', '', NULL, '南海陪鄭司空遊荔園 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11fe4bfb-12c3-49ff-be32-c2d0c0eb526d', '李郎中林亭', '李郎中林亭', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["秪向砌邊流野水，樽前上下看魚兒。","筍蹊已長過人竹，藤徑從添拂面絲。","若許白猿垂近戶，即無紅果壓低枝。","大才必擬逍遙去，更遣何人佐盛時。"]', '["秪向砌邊流野水，樽前上下看鱼兒。","筍蹊已长過人竹，藤徑從添拂面絲。","若許白猿垂近戶，即無紅果壓低枝。","大才必擬逍遙去，更遣何人佐盛时。"]', '诗', 'shi', '', NULL, '李郎中林亭 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5503150e-71dc-49a7-8def-13caa36391a7', '夜飲', '夜饮', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["良宵公子宴蘭堂，濃麝薰人獸吐香。","雲帶金龍銜畫燭，星羅銀鳳瀉瓊漿。","滿屏珠樹開春景，一曲歌聲遶翠梁。","席上未知簾幕曉，青娥低語指東方。"]', '["良宵公子宴蘭堂，濃麝薰人獸吐香。","云带金龙銜畫燭，星羅銀鳳瀉瓊漿。","满屏珠樹开春景，一曲歌声遶翠梁。","席上未知簾幕晓，青娥低語指东方。"]', '诗', 'shi', '', NULL, '夜飲 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba81e09d-ed44-4ed2-bcae-f88890f28e48', '駙馬宅宴罷', '駙马宅宴罷', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["粉牆殘月照宮祠，宴闋銀瓶一半欹。","學語鸎兒飛未穩，放身斜墜綠楊枝。"]', '["粉牆殘月照宮祠，宴闋銀瓶一半欹。","学語鸎兒飞未穩，放身斜墜綠楊枝。"]', '诗', 'shi', '', NULL, '駙馬宅宴罷 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f13058-08c4-43b1-bfd7-6208b6800009', '弔建州李員外', '弔建州李員外', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["銘旌歸故里，猿鳥亦悽然。","已葬桐江月，空廻建水船。","客傳爲郡日，僧說讀書年。","恐有吟魂在，深山古木邊。"]', '["銘旌归故里，猿鸟亦悽然。","已葬桐江月，空廻建水船。","客傳爲郡日，僧说读书年。","恐有吟魂在，深山古木邊。"]', '诗', 'shi', '', NULL, '弔建州李員外 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a16189-8aba-4ec6-98d5-cd9edd8b995a', '弔李翰林', '弔李翰林', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["李白雖然成異物，逸名猶與萬方傳。","昔朝曾侍玄宗側，大夜應歸賀監邊。","山木易高迷故壠，國風長在見遺篇。","投金渚畔春楊柳，自此何人繫酒船。"]', '["李白雖然成異物，逸名猶與万方傳。","昔朝曾侍玄宗側，大夜應归賀監邊。","山木易高迷故壠，国风长在见遺篇。","投金渚畔春楊柳，自此何人繫酒船。"]', '诗', 'shi', '', NULL, '弔李翰林 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129c3a1c-96d6-4dfc-8970-9aa1c8f2c12a', '山中', '山中', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["要路豪家非往還，巖門先有不曾關。","衆心惟恐地無剩，吾意亦憂天惜閑。","白練曳泉窗下石，絳羅垂果枕前山。","樵夫豈解營生業，貴欲自安麋鹿間。"]', '["要路豪家非往還，巖门先有不曾关。","衆心惟恐地無剩，吾意亦憂天惜闲。","白練曳泉窗下石，絳羅垂果枕前山。","樵夫豈解營生業，貴欲自安麋鹿间。"]', '诗', 'shi', '', NULL, '山中 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bf1e0a-9707-4eb4-ad1f-7f12cf2b1e04', '山寺引泉', '山寺引泉', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["劈碎琅玕意有餘，細泉高引入香廚。","山僧未肯言根本，莫是銀河漏泄無。"]', '["劈碎琅玕意有餘，細泉高引入香廚。","山僧未肯言根本，莫是銀河漏泄無。"]', '诗', 'shi', '', NULL, '山寺引泉 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a0cb981-3fb4-4aa1-80c0-88632650daad', '友人池上詠蘆', '友人池上詠蘆', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["秋聲誰種得，蕭瑟在池欄。","葉澀栖蟬穩，叢疎宿鷺難。","歛煙宜下□，颯吹省先寒。","此物生蒼島，令人憶釣竿。"]', '["秋声誰種得，蕭瑟在池欄。","葉澀栖蟬穩，叢疎宿鷺难。","歛煙宜下□，颯吹省先寒。","此物生蒼島，令人憶釣竿。"]', '诗', 'shi', '', NULL, '友人池上詠蘆 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40c07ba-f6f5-4de8-a182-5c4fdcd71f47', '商山', '商山', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["垂白商於原下住，兒孫共死一身忙。","木弓未得長離手，猶與官家射麝香。"]', '["垂白商於原下住，兒孫共死一身忙。","木弓未得长離手，猶與官家射麝香。"]', '诗', 'shi', '', NULL, '商山 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849ae158-1eb5-40e2-a2a8-6d57fcdec8b3', '荆南道中', '荆南道中', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["十月荒郊雪氣催，依稀愁色認陽臺。","遊秦分繫三條燭，出楚心殊一寸灰。","高柳莫遮寒月落，空桑不放夜風廻。","如何住在猿聲裏，却被蟬吟引下來。"]', '["十月荒郊雪氣催，依稀愁色認陽台。","游秦分繫三條燭，出楚心殊一寸灰。","高柳莫遮寒月落，空桑不放夜风廻。","如何住在猿声裏，却被蟬吟引下来。"]', '诗', 'shi', '', NULL, '荆南道中 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174237fd-4a64-4bd7-81af-113eddea3303', '武德殿朝退望九衢春色', '武德殿朝退望九衢春色', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["玉殿朝初退，天街一看春。","南山初過雨，北闕淨無塵。","夾道夭桃滿，連溝御柳新。","蘇舒同舜澤，煦嫗竝堯仁。","佳氣浮軒蓋，和風襲縉紳。","自茲憐萬物，同入發生辰。"]', '["玉殿朝初退，天街一看春。","南山初過雨，北闕淨無塵。","夾道夭桃满，連溝御柳新。","蘇舒同舜澤，煦嫗竝堯仁。","佳氣浮軒蓋，和风襲縉紳。","自茲怜万物，同入發生辰。"]', '诗', 'shi', '', NULL, '武德殿朝退望九衢春色 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b757c5-c8d8-4907-ab69-62dc827c5ab6', '弔北邙', '弔北邙', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["山下望山上，夕陽看又曛。","無人醫白髮，少地著新墳。","歲代殊相遠，賢愚旋不分。","東歸聊一弔，亂木倚寒雲。"]', '["山下望山上，夕陽看又曛。","無人醫白髮，少地著新墳。","歲代殊相远，賢愚旋不分。","东归聊一弔，亂木倚寒云。"]', '诗', 'shi', '', NULL, '弔北邙 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0840e1-56d4-4c22-9502-85d506741dec', '及第勅下宴中獻座主杜侍郎', '及第勅下宴中獻座主杜侍郎', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["得召丘牆淚却頻，若無公道也無因。","門前送勅朱衣吏，席上銜杯碧落人。","半夜笙歌教泥月，平明桃杏放燒春。","南山雖有歸溪路，爭那酬恩未殺身。"]', '["得召丘牆泪却頻，若無公道也無因。","门前送勅朱衣吏，席上銜杯碧落人。","半夜笙歌教泥月，平明桃杏放燒春。","南山雖有归溪路，爭那酬恩未殺身。"]', '诗', 'shi', '', NULL, '及第勅下宴中獻座主杜侍郎 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf796e44-b7cd-4e4d-b198-a2596a92375d', '梢雲', '梢云', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["殊質資靈貺，陵空發瑞雲。","梢梢含樹影，郁郁動霞文。","不比因風起，全非觸石分。","葉光閑泛灩，枝彩靜氛氳。","隱見心無宰，裴回慶自君。","翻飛如可託，長願在橫汾。"]', '["殊質資靈貺，陵空發瑞云。","梢梢含樹影，郁郁动霞文。","不比因风起，全非觸石分。","葉光闲泛灩，枝彩静氛氳。","隐见心無宰，裴回慶自君。","翻飞如可託，长願在橫汾。"]', '诗', 'shi', '', NULL, '梢雲 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b58dc5e-2f51-407b-afde-157926ac4449', '白角簟', '白角簟', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["角簟工夫已到頭，夏來全占滿牀秋。","若言保惜歸華屋，秪合封題寄列侯。","學卷曉冰長怕綻，解鋪寒水不教流。","蒲桃錦是瀟湘底，曾得王孫價倍酬。"]', '["角簟工夫已到头，夏来全占满牀秋。","若言保惜归华屋，秪合封題寄列侯。","学卷晓冰长怕綻，解鋪寒水不教流。","蒲桃錦是瀟湘底，曾得王孫價倍酬。"]', '诗', 'shi', '', NULL, '白角簟 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86ed60df-bb60-4663-98c4-008fc8facbae', '碧角簟', '碧角簟', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["細皮重疊織霜紋，滑膩鋪牀勝錦茵。","八尺碧天無點翳，一方青玉絕纖塵。","蠅行只恐煙黏足，客臥混疑水浸身。","五月不教炎氣入，滿堂秋色冷龍鱗。"]', '["細皮重叠织霜紋，滑膩鋪牀勝錦茵。","八尺碧天無点翳，一方青玉絕纖塵。","蠅行只恐煙黏足，客臥混疑水浸身。","五月不教炎氣入，满堂秋色冷龙鱗。"]', '诗', 'shi', '', NULL, '碧角簟 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd6589c-7911-43a4-ada3-c572208724ca', '滕王閣春日晚望', '滕王閣春日晚望', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["凌春帝子閣，偶眺日移西。","浪勢平花塢，帆陰上柳堤。"]', '["凌春帝子閣，偶眺日移西。","浪勢平花塢，帆陰上柳堤。"]', '诗', 'shi', '', NULL, '滕王閣春日晚望 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba1af05-9c11-4788-977a-ce57b1890810', '句', '句', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["追遊若遇三清樂，行從應妨一日春。","石脉水流泉滴沙，鬼燈然點松柏花。","鹿眠荒圃寒蕪白，鴉噪殘陽敗葉飛。","華嶽影寒清露掌，海門風急白潮頭。"]', '["追游若遇三清乐，行從應妨一日春。","石脉水流泉滴沙，鬼灯然点松柏花。","鹿眠荒圃寒蕪白，鴉噪殘陽敗葉飞。","华嶽影寒清露掌，海门风急白潮头。"]', '诗', 'shi', '', NULL, '句 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a59d92e-c696-4f97-a7c5-236df0419bba', '頌魯', '頌魯', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["天推魯仲尼，周游布典墳。","遊遍七十國，不令遇一君。","一國如一遇，單車不轉輪。","良由至化力，爲國不爲身。","禮樂行未足，邅迴厄於陳。","禮樂今有餘，袞旒當聖人。","傷哉絕糧議，千載誤云云。"]', '["天推魯仲尼，周游布典墳。","游遍七十国，不令遇一君。","一国如一遇，單车不轉輪。","良由至化力，爲国不爲身。","禮乐行未足，邅迴厄於陳。","禮乐今有餘，袞旒當聖人。","傷哉絕糧議，千載誤云云。"]', '诗', 'shi', '', NULL, '頌魯 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('627090b2-5064-4c69-9150-abb3e70451fe', '醫人', '醫人', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["古人醫在心，心正藥自真。","今人醫在手，手濫藥不神。","我願天地鑪，多銜扁鵲身。","遍行君臣藥，先從凍餒均。","自然六合內，少聞貧病人。"]', '["古人醫在心，心正藥自真。","今人醫在手，手濫藥不神。","我願天地鑪，多銜扁鵲身。","遍行君臣藥，先從凍餒均。","自然六合內，少闻貧病人。"]', '诗', 'shi', '', NULL, '醫人 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8621171-5488-4eec-9716-861c79c1df63', '西施', '西施', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["吳王從驕佚，天產西施出。","豈徒伐一人，所希救羣物。","良由上天意，惡盈戒奢侈。","不獨破吳國，不獨生越水。","在周名襃姒，在紂名妲己。","變化本多塗，生殺亦如此。","君王政不修，立地生西子。"]', '["吳王從驕佚，天產西施出。","豈徒伐一人，所希救羣物。","良由上天意，惡盈戒奢侈。","不独破吳国，不独生越水。","在周名襃姒，在紂名妲己。","变化本多塗，生殺亦如此。","君王政不修，立地生西子。"]', '诗', 'shi', '', NULL, '西施 蘇拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73295826-245f-4fb0-b4bc-4b3be383313f', '金谷園', '金谷园', '2f6f0734-9f2f-40a4-b9b5-ef0c45f03018', '唐', '["積金累作山，山高小於址。","栽花比綠珠，花落還相似。","徒有敵國富，不能買東市。","徒有絕世容，不能樓上死。","秪此上高樓，何如在平地。"]', '["積金累作山，山高小於址。","栽花比綠珠，花落還相似。","徒有敵国富，不能買东市。","徒有絕世容，不能楼上死。","秪此上高楼，何如在平地。"]', '诗', 'shi', '', NULL, '金谷園 蘇拯 shi');
